//  РАЗДЕЛ: МОНИТОРИНГ МАГАЗИНОВ
// ═════════════════════════════════════════════════════
const MON_META = {
  open:   { label: 'Открыта', cls: 'ok',   dot: 'g' },
  closed: { label: 'Закрыта', cls: 'gray', dot: 'gray' },
  idle:   { label: 'Нет смены', cls: 'off', dot: 'r' },
};
async function renderMonitoring(force) {
  const box = $('monBody');
  box.innerHTML = `<div class="loading">⏳ Проверяю статус касс…</div>`;
  try {
    // всегда свежие данные (статус онлайн) — без кеша
    const d = await posApi(`?action=monitoring`);
    const s = d.stats || {};
    const rows = d.rows || [];
    const srv = d.serverTime ? d.serverTime.replace('T', ' ').slice(0, 16) : '';

    box.innerHTML = `
      <div class="kpis" style="grid-template-columns:repeat(auto-fit,minmax(160px,1fr))">
        ${kpi('🔓','Смен открыто', fmtInt(s.open||0),'g', 'из '+fmtInt(s.kassas||0)+' касс')}
        ${kpi('🔒','Закрыто сегодня', fmtInt(s.closed||0),'gray','')}
        ${kpi('⚠️','Без смены', fmtInt(s.idle||0), (s.idle?'r':'gray'),'')}
        ${kpi('💵','Продажи сегодня', money(s.salesToday||0),'g', fmtInt(s.receiptsToday||0)+' чеков')}
      </div>

      <div class="card card-pad">
        <div class="card-h-row">
          <h3>Статус касс</h3>
          <span class="muted">на ${esc(srv)} · <a href="#" id="monRefresh" style="color:var(--g2);font-weight:600;text-decoration:none">⭯ Обновить</a></span>
        </div>
        <div class="tbl-wrap"><table class="tbl">
          <thead><tr>
            <th>Касса / Магазин</th><th>Статус</th><th>Кассир</th>
            <th>Открыта</th><th>Закрыта</th><th class="r">Чеков</th><th class="r">Продажи</th>
          </tr></thead>
          <tbody>${rows.map(r => {
            const m = MON_META[r.state] || MON_META.idle;
            return `<tr>
              <td><b>${esc(r.kassa)}</b>${r.offline?` <span class="badge gray" style="font-size:10px">offline</span>`:''}<div class="muted" style="font-size:12px">${esc(r.shop||'—')}</div></td>
              <td><span class="badge ${m.cls}">${m.label}</span></td>
              <td>${esc(r.seller||'—')}</td>
              <td>${r.openedAt?dushTime(r.openedAt,false):'—'}</td>
              <td>${r.closedAt?dushTime(r.closedAt,false):(r.state==='open'?'<span class="muted">сейчас</span>':'—')}</td>
              <td class="r">${fmtInt(r.receipts||0)}</td>
              <td class="r strong">${money(r.totalSales||0)}</td>
            </tr>`;
          }).join('')}</tbody>
        </table></div>
      </div>
    `;
    const rf = $('monRefresh');
    if (rf) rf.onclick = (e) => { e.preventDefault(); renderMonitoring(true); };
    bumpSync();
  } catch (e) {
    box.innerHTML = errBar('Не удалось загрузить мониторинг: ' + (e.message || e));
  }
}

// ═════════════════════════════════════════════════════
//  РАЗДЕЛ: ОТЧЁТ ПО СНЯТИЮ ДС (наличные к инкассации)
// ═════════════════════════════════════════════════════
let cashLastReport = null;
// бейдж платёжной системы (Alif / DC) рядом с названием типа оплаты
function payBadge(key) {
  if (key === 'alifqr' || key === 'alifwlt') return ' <span class="pay-badge pb-alif">alif</span>';
  if (key === 'dcqr' || key === 'dcwlt') return ' <span class="pay-badge pb-dc">dc</span>';
  return '';
}
// галочка/крестик сверки
function crCheck(ok) {
  return ok
    ? '<span class="cr-ok" title="Совпадает">✓</span>'
    : '<span class="cr-bad" title="Расхождение">✗</span>';
}
async function renderCashReport(force) {
  const box = $('cashBody');
  box.innerHTML = `<div class="loading">⏳ Формирую отчёт по продажам…</div>`;
  try {
    const d = await cachedApi(`salesrep:${state.from}:${state.to}`, `?action=sales-report&from=${state.from}&to=${state.to}`);
    const rep = d.report || {};
    cashLastReport = rep;
    const g = rep.grand || {};
    const shops = rep.shops || [];
    // Динамические колонки типов оплат из backend (устойчиво к изменению набора)
    const buckets = (rep.buckets && rep.buckets.length)
      ? rep.buckets
      : [{ key:'cash',label:'Наличные' },{ key:'alifqr',label:'Alif QR' },{ key:'alifwlt',label:'Alif кошелёк' },{ key:'dcwlt',label:'DC кошелёк' },{ key:'dcqr',label:'DC QR' }];
    const per = state.from === state.to ? state.from : state.from + ' — ' + state.to;

    // ── Иерархическая таблица как в образце:
    //  № | Тип оплаты | Продажа | Возврат | Итого с учётом возврата | Сумма по кассе | Сверка
    //  Группа = магазин (жирная строка), под-строки = типы оплаты.
    const PB = payBadge; // бейдж Alif/DC рядом с лейблом
    let rowsHtml = '';
    shops.forEach((s, si) => {
      const num = si + 1;
      // строка-заголовок магазина
      rowsHtml += `<tr class="cr-shop">
        <td class="cr-num">${num}</td>
        <td><b>${esc(s.shop || '—')}</b></td>
        <td class="r strong">${money(s.saleTotal || 0)}</td>
        <td class="r ${(s.retTotal||0)>0?'cr-ret':'muted'}">${money(s.retTotal || 0)}</td>
        <td class="r strong">${money(s.total || 0)}</td>
        <td class="r strong">${money(s.total || 0)}</td>
        <td class="c">${crCheck(true)}</td>
      </tr>`;
      // под-строки по типам оплаты (только ненулевые по продаже или возврату)
      buckets.forEach((b, bi) => {
        const sale = (s.sale && s.sale[b.key]) || 0;
        const ret = (s.ret && s.ret[b.key]) || 0;
        if (Math.abs(sale) < 0.005 && Math.abs(ret) < 0.005) return;
        const net = sale - ret;
        rowsHtml += `<tr class="cr-sub">
          <td class="cr-num muted">${num}.${bi + 1}</td>
          <td class="cr-type">${esc(b.label)}${PB(b.key)}</td>
          <td class="r">${money(sale)}</td>
          <td class="r ${ret>0?'cr-ret':'muted'}">${money(ret)}</td>
          <td class="r strong">${money(net)}</td>
          <td class="c"><input type="text" class="cr-cash" value="${fmtNum(net)}" data-net="${net}"></td>
          <td class="c cr-vcell">${crCheck(true)}</td>
        </tr>`;
      });
      // Прочее (если есть)
      const oSale = (s.sale && s.sale.other) || 0, oRet = (s.ret && s.ret.other) || 0;
      if (Math.abs(oSale) >= 0.005 || Math.abs(oRet) >= 0.005) {
        const net = oSale - oRet;
        rowsHtml += `<tr class="cr-sub">
          <td class="cr-num muted">${num}.${buckets.length + 1}</td>
          <td class="cr-type">Прочее</td>
          <td class="r">${money(oSale)}</td>
          <td class="r ${oRet>0?'cr-ret':'muted'}">${money(oRet)}</td>
          <td class="r strong">${money(net)}</td>
          <td class="c"><input type="text" class="cr-cash" value="${fmtNum(net)}" data-net="${net}"></td>
          <td class="c cr-vcell">${crCheck(true)}</td>
        </tr>`;
      }
    });
    // итоговая строка
    const grandRow = `<tr class="cr-grand">
      <td></td>
      <td><b>Итого по всем магазинам</b></td>
      <td class="r strong">${money(g.saleTotal || 0)}</td>
      <td class="r ${(g.retTotal||0)>0?'cr-ret':'muted'}">${money(g.retTotal || 0)}</td>
      <td class="r strong">${money(g.total || 0)}</td>
      <td class="r strong">${money(g.total || 0)}</td>
      <td class="c">${crCheck(true)}</td>
    </tr>`;

    box.innerHTML = `
      <div class="kpis" style="grid-template-columns:repeat(auto-fit,minmax(160px,1fr))">
        ${kpi('💰','Итого продаж', money(g.total || 0), 'g', fmtInt(g.receipts || 0) + ' чеков · ' + per)}
        ${kpi('📈','Продажа', money(g.saleTotal || 0), 'gray', 'без учёта возвратов')}
        ${kpi('↩️','Возврат', money(g.retTotal || 0), (g.retTotal?'r':'gray'), 'за период')}
        ${kpi('💵','Наличные', money(g.cash || 0), 'g', 'с учётом возврата')}
      </div>

      <div class="card card-pad cr-doc">
        <!-- шапка-документ как в печатном PDF -->
        <div class="cr-head">
          <div class="cr-brand">
            <img src="icon-192.png" alt="OrtoSalon" class="cr-logo">
            <div>
              <div class="cr-brand-name">OrtoSalon</div>
              <div class="cr-brand-sub">Ортопедический салон</div>
            </div>
          </div>
          <div class="cr-meta">
            <div class="cr-doc-title">Отчёт о снятии денежных средств</div>
            <div class="cr-doc-meta">Дата формирования: ${esc(nowDushLabel())}</div>
            <div class="cr-doc-meta">Отчётный период: ${esc(per)}</div>
          </div>
        </div>
        <div class="cr-hr"></div>

        <div class="card-h-row">
          <h3 style="color:#108589">Движения денежных средств по типам оплаты</h3>
          <div style="display:flex;align-items:center;gap:10px">
            ${shops.length ? `<button class="btn btn-sm btn-ghost" id="cashExportPdf">📄 PDF</button>
            <button class="btn btn-sm btn-primary" id="cashExportXlsx">📗 Excel</button>` : ''}
          </div>
        </div>
        ${shops.length ? `<div class="tbl-wrap"><table class="tbl cr-tbl">
          <thead><tr>
            <th class="cr-num">№</th><th>Тип оплаты</th>
            <th class="r">Продажа, сом.</th><th class="r">Возврат, сом.</th>
            <th class="r">Итого с учётом возврата, сом.</th>
            <th class="c">Сумма по кассе / выписке, сом.</th>
            <th class="c">Сверка</th>
          </tr></thead>
          <tbody>${rowsHtml}${grandRow}</tbody>
        </table></div>
        <!-- подписи как в печатном варианте -->
        <div class="cr-sign">
          <div class="cr-sign-item"><span>Ответственный:</span><i></i></div>
          <div class="cr-sign-item"><span>Подпись:</span><i></i></div>
          <div class="cr-sign-item"><span>Дата:</span><i></i></div>
        </div>
        <div class="cr-foot">Спасибо за работу! · OrtoSalon — забота о ваших ногах каждый день</div>` : `<div class="tbl-empty">Нет продаж за период</div>`}
      </div>
    `;
    // живая сверка: при редактировании «Суммы по кассе» — пересчёт галочки
    box.querySelectorAll('.cr-cash').forEach(inp => {
      inp.addEventListener('input', () => {
        const net = Number(inp.dataset.net) || 0;
        const val = parseFloat(String(inp.value).replace(/\s/g, '').replace(',', '.')) || 0;
        const ok = Math.abs(val - net) < 0.5;
        const cell = inp.closest('tr').querySelector('.cr-vcell');
        if (cell) cell.innerHTML = crCheck(ok);
        inp.style.borderColor = ok ? '' : 'var(--r,#c0392b)';
      });
    });
    // бинды экспорта (кнопки появляются только при наличии данных)
    const bp = $('cashExportPdf'); if (bp) bp.addEventListener('click', () => cashExportPdf(rep, buckets, per));
    const bx = $('cashExportXlsx'); if (bx) bx.addEventListener('click', () => cashExportXlsx(rep, buckets, per));
    bumpSync();
  } catch (e) {
    box.innerHTML = errBar('Не удалось загрузить отчёт: ' + (e.message || e));
  }
}

// числовой формат без HTML (для PDF/Excel)
function cashNumTxt(n) { return fmtNum(n); }

// ── Экспорт Отчёта по снятию ДС → PDF (книжный, по образцу) ──
// Структура как в окне: иерархия магазин→типы оплаты, колонки
// № / Тип оплаты / Продажа / Возврат / Итого / Сумма по кассе / Сверка.
function cashExportPdf(rep, buckets, per) {
  try {
    if (!rep || !(rep.shops || []).length) { alert('Сначала сформируйте отчёт'); return; }
    const g = rep.grand || {};
    const shops = rep.shops || [];
    const { jsPDF } = window.jspdf;
    const doc = new jsPDF({ unit: 'mm', format: 'a4', orientation: 'portrait' });
    const FONT = (doc.getFontList && doc.getFontList().DejaVuSans) ? 'DejaVuSans' : 'helvetica';
    const W = 210, M = 12, PH = 297;
    const N = (v) => cashNumTxt(v || 0);          // число без HTML
    const badge = (k) => (k === 'alifqr' || k === 'alifwlt') ? ' (alif)' : ((k === 'dcqr' || k === 'dcwlt') ? ' (dc)' : '');

    // ── Шапка: логотип-стопа (вектор) + название слева, реквизиты справа ──
    let y = 16;
    // простой знак стопы из кругов (без внешних картинок)
    doc.setFillColor(16, 133, 137);
    doc.circle(M + 3, y - 1, 2.6, 'F');
    [[7.5, -4.5, 1.0], [9.2, -2.6, 1.1], [9.2, -0.4, 1.1], [8.0, 1.5, 1.0]].forEach(([dx, dy, r]) =>
      doc.circle(M + dx, y + dy, r, 'F'));
    doc.setFont(FONT, 'bold'); doc.setFontSize(16); doc.setTextColor(16, 133, 137);
    doc.text('OrtoSalon', M + 13, y);
    doc.setFont(FONT, 'normal'); doc.setFontSize(8); doc.setTextColor(120, 120, 120);
    doc.text('Ортопедический салон', M + 13, y + 4.5);
    // справа
    doc.setFont(FONT, 'bold'); doc.setFontSize(14); doc.setTextColor(40, 40, 40);
    doc.text('Отчёт о снятии денежных средств', W - M, y - 1, { align: 'right' });
    doc.setFont(FONT, 'normal'); doc.setFontSize(8.5); doc.setTextColor(120, 120, 120);
    doc.text('Дата формирования: ' + nowDushLabel(), W - M, y + 4, { align: 'right' });
    doc.text('Отчётный период: ' + per, W - M, y + 8, { align: 'right' });
    y += 15;
    doc.setDrawColor(16, 133, 137); doc.setLineWidth(0.5);
    doc.line(M, y, W - M, y);
    y += 8;

    doc.setFont(FONT, 'bold'); doc.setFontSize(12); doc.setTextColor(16, 133, 137);
    doc.text('Движения денежных средств по типам оплаты', M, y);
    y += 3;

    // ── Строим body с флагами типа строки (для стилей) ──
    const head = [['№', 'Тип оплаты', 'Продажа,\nсом.', 'Возврат,\nсом.', 'Итого с учётом\nвозврата, сом.', 'Сумма по кассе /\nвыписке, сом.', 'Сверка']];
    const body = [];
    const shopRowIdx = [];              // индексы строк-магазинов
    // в печатном варианте колонка «Сумма по кассе» ПУСТАЯ (вписывают вручную), и галочка не ставится
    shops.forEach((s, si) => {
      const num = si + 1;
      shopRowIdx.push(body.length);
      body.push([String(num), s.shop || '—', N(s.saleTotal), N(s.retTotal), N(s.total), '', '']);
      buckets.forEach((b, bi) => {
        const sale = (s.sale && s.sale[b.key]) || 0;
        const ret = (s.ret && s.ret[b.key]) || 0;
        if (Math.abs(sale) < 0.005 && Math.abs(ret) < 0.005) return;
        body.push([num + '.' + (bi + 1), b.label + badge(b.key), N(sale), N(ret), N(sale - ret), '', '']);
      });
      const oSale = (s.sale && s.sale.other) || 0, oRet = (s.ret && s.ret.other) || 0;
      if (Math.abs(oSale) >= 0.005 || Math.abs(oRet) >= 0.005)
        body.push([num + '.' + (buckets.length + 1), 'Прочее', N(oSale), N(oRet), N(oSale - oRet), '', '']);
    });
    const foot = [['', 'Итого по всем магазинам', N(g.saleTotal), N(g.retTotal), N(g.total), '', '']];

    doc.autoTable({
      startY: y + 3,
      head, body, foot,
      styles: { font: FONT, fontSize: 8, cellPadding: 2, halign: 'right', valign: 'middle', lineColor: [232, 236, 236], lineWidth: 0.1 },
      headStyles: { font: FONT, fontStyle: 'bold', fillColor: [16, 133, 137], textColor: 255, halign: 'center', fontSize: 7.5, valign: 'middle' },
      footStyles: { font: FONT, fontStyle: 'bold', fillColor: [209, 250, 229], textColor: [4, 120, 87], halign: 'right', fontSize: 8.5 },
      columnStyles: {
        0: { halign: 'center', cellWidth: 12 },
        1: { halign: 'left', cellWidth: 46 },
        2: { cellWidth: 24 }, 3: { cellWidth: 22 }, 4: { cellWidth: 28 }, 5: { cellWidth: 28 },
        6: { halign: 'center' },
      },
      margin: { left: M, right: M },
      didParseCell: (data) => {
        // строки-магазины — зелёный фон + жирный
        if (data.section === 'body' && shopRowIdx.includes(data.row.index)) {
          data.cell.styles.fillColor = [236, 253, 245];
          data.cell.styles.fontStyle = 'bold';
          data.cell.styles.textColor = [4, 120, 87];
        }
        // колонка «Сумма по кассе» — пустая рамка (вписывают вручную)
        if (data.column.index === 5 && data.section !== 'head') {
          data.cell.styles.lineWidth = 0.3; data.cell.styles.lineColor = [180, 190, 190];
        }
      },
      // в печатном варианте галочку НЕ ставим: колонка «Сверка» заполняется вручную
    });
    y = (doc.lastAutoTable ? doc.lastAutoTable.finalY : y) + 16;

    // ── Подписи ──
    if (y > PH - 34) { doc.addPage(); y = 24; }
    doc.setFont(FONT, 'normal'); doc.setFontSize(9.5); doc.setTextColor(60, 60, 60);
    doc.setDrawColor(150, 150, 150); doc.setLineWidth(0.3);
    const segW = (W - 2 * M - 20) / 3;
    doc.text('Ответственный:', M, y);
    doc.line(M + 26, y, M + segW, y);
    doc.text('Подпись:', M + segW + 10, y);
    doc.line(M + segW + 27, y, M + 2 * segW + 10, y);
    doc.text('Дата:', M + 2 * segW + 20, y);
    doc.line(M + 2 * segW + 32, y, W - M, y);
    y += 12;

    // ── Футер ──
    doc.setFont(FONT, 'bold'); doc.setFontSize(9); doc.setTextColor(16, 133, 137);
    doc.text('Спасибо за работу!', W / 2, PH - 14, { align: 'center' });
    doc.setFont(FONT, 'normal'); doc.setFontSize(7.5); doc.setTextColor(150, 160, 160);
    doc.text('OrtoSalon — забота о ваших ногах каждый день · данные из 1С (Чеки ККМ)', W / 2, PH - 9, { align: 'center' });

    const fn = per.replace(/[^0-9]+/g, '_').replace(/^_|_$/g, '') || 'period';
    doc.save('otchet_snyatie_DS_' + fn + '.pdf');
  } catch (e) {
    alert('Не удалось сформировать PDF: ' + (e.message || e));
  }
}

// ── Экспорт Отчёта по снятию ДС → Excel (SheetJS) ──
function cashExportXlsx(rep, buckets, per) {
  try {
    if (!rep || !(rep.shops || []).length) { alert('Сначала сформируйте отчёт'); return; }
    if (!window.XLSX) { alert('Библиотека Excel не загрузилась — обновите страницу (Ctrl+F5)'); return; }
    const g = rep.grand || {};
    const shops = rep.shops || [];
    const num = v => Number(v) || 0;
    const badge = (k) => (k === 'alifqr' || k === 'alifwlt') ? ' (alif)' : ((k === 'dcqr' || k === 'dcwlt') ? ' (dc)' : '');
    // иерархическая структура по образцу
    const head = ['№', 'Тип оплаты', 'Продажа, сом.', 'Возврат, сом.', 'Итого с учётом возврата, сом.', 'Сумма по кассе / выписке, сом.', 'Сверка'];
    const aoa = [
      ['Отчёт о снятии денежных средств · OrtoSalon'],
      ['Отчётный период: ' + per + '   ·   Дата формирования: ' + nowDushLabel()],
      [],
      head,
    ];
    shops.forEach((s, si) => {
      const n = si + 1;
      aoa.push([n, s.shop || '—', num(s.saleTotal), num(s.retTotal), num(s.total), num(s.total), '✓']);
      buckets.forEach((b, bi) => {
        const sale = num(s.sale && s.sale[b.key]), ret = num(s.ret && s.ret[b.key]);
        if (Math.abs(sale) < 0.005 && Math.abs(ret) < 0.005) return;
        aoa.push([n + '.' + (bi + 1), b.label + badge(b.key), sale, ret, sale - ret, sale - ret, '✓']);
      });
      const oS = num(s.sale && s.sale.other), oR = num(s.ret && s.ret.other);
      if (Math.abs(oS) >= 0.005 || Math.abs(oR) >= 0.005)
        aoa.push([n + '.' + (buckets.length + 1), 'Прочее', oS, oR, oS - oR, oS - oR, '✓']);
    });
    aoa.push(['', 'Итого по всем магазинам', num(g.saleTotal), num(g.retTotal), num(g.total), num(g.total), '✓']);

    const ws = XLSX.utils.aoa_to_sheet(aoa);
    ws['!cols'] = [{ wch: 6 }, { wch: 26 }, { wch: 15 }, { wch: 14 }, { wch: 20 }, { wch: 20 }, { wch: 9 }];
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, 'Снятие ДС');
    const fn = per.replace(/[^0-9]+/g, '_').replace(/^_|_$/g, '') || 'period';
    XLSX.writeFile(wb, 'Отчёт_снятие_ДС_' + fn + '.xlsx');
  } catch (e) {
    alert('Не удалось сформировать Excel: ' + (e.message || e));
  }
}

// ═════════════════════════════════════════════════
//  РАЗДЕЛ: ОТЧЁТЫ ПО ПРОДАЖАМ ЗА ДЕНЬ (независимый от 1С)
//  Список суточных отчётов закрытых смен; клик — все чеки дня + способы оплаты.
// ══════════════════════════════════════════════════
const srReportCache = {};  // id -> детали отчёта (чеки)

async function renderShiftReports(force) {
  const box = $('srBody');
  box.innerHTML = `<div class="loading">⏳ Загружаю отчёты…</div>`;
  try {
    const d = await posApi(`?action=shift-reports&from=${state.from}&to=${state.to}${kassaQS()}`, { method: 'GET' });
    const reports = d.reports || [];
    const t = d.totals || {};
    const per = state.from === state.to ? state.from : state.from + ' — ' + state.to;
    box.innerHTML = `
      <div class="kpis" style="grid-template-columns:repeat(auto-fit,minmax(170px,1fr))">
        ${kpi('💵','Наличные', money(t.cash||0),'g','за '+per)}
        ${kpi('💳','Безналичные', money(t.noncash||0),'blue','карты/QR/кошельки')}
        ${kpi('∑','Выручка', money(t.sales||0),'gray', (t.returns? 'возвраты '+money(t.returns) : ''))}
        ${kpi('📊','Отчётов смен', fmtInt(reports.length),'gray', fmtInt(t.receipts||0)+' чеков')}
      </div>

      <div class="card card-pad">
        <div class="card-h-row"><h3>Отчёты по закрытым сменам</h3><span class="muted">${fmtInt(reports.length)}</span></div>
        ${reports.length ? `<div class="tbl-wrap"><table class="tbl sr-tbl">
          <thead><tr><th style="width:26px"></th><th>Дата</th><th>Касса / Магазин</th><th>Кассир</th><th>Закрыта</th><th class="r">Чеков</th><th class="r">Наличные</th><th class="r">Безнал</th><th class="r">Итого</th></tr></thead>
          <tbody>${reports.map((r,i)=>srRowHTML(r,i)).join('')}</tbody>
        </table></div>` : `<div class="tbl-empty">Нет отчётов за период (отчёт создаётся при закрытии смены)</div>`}
      </div>
    `;
    // клик по строке — раскрытие деталей
    box.querySelectorAll('tr.sr-row').forEach(tr => {
      tr.addEventListener('click', () => toggleShiftReport(tr));
    });
    bumpSync();
  } catch (e) {
    box.innerHTML = errBar('Не удалось загрузить отчёты: ' + (e.message || e));
  }
}

function srRowHTML(r, i) {
  return `<tr class="sr-row" data-idx="${i}" data-id="${esc(r.id)}">
      <td class="c"><span class="caret">›</span></td>
      <td><b>${esc(r.date||'')}</b></td>
      <td><b>${esc(r.kassa||'—')}</b><div class="muted" style="font-size:12px">${esc(r.shop||'')}</div></td>
      <td>${esc(r.seller||'—')}</td>
      <td>${r.closedAt?dushTime(r.closedAt,true):'—'}</td>
      <td class="r">${fmtInt(r.receiptsCount||0)}</td>
      <td class="r strong" style="color:var(--g2)">${money(r.cashTotal||0)}</td>
      <td class="r">${money(r.noncashTotal||0)}</td>
      <td class="r strong">${money(r.totalSales||0)}</td>
    </tr>
    <tr class="sr-det" id="srDet-${i}" style="display:none"><td colspan="9"><div id="srDetBody-${i}"></div></td></tr>`;
}

async function toggleShiftReport(tr) {
  const idx = tr.dataset.idx;
  const id = tr.dataset.id;
  const detRow = $('srDet-' + idx);
  const body = $('srDetBody-' + idx);
  const caret = tr.querySelector('.caret');
  if (!detRow || !body) return;
  if (detRow.style.display !== 'none') {
    detRow.style.display = 'none';
    tr.classList.remove('open');
    if (caret) caret.textContent = '›';
    return;
  }
  detRow.style.display = '';
  tr.classList.add('open');
  if (caret) caret.textContent = '‹';
  if (srReportCache[id]) { body.innerHTML = renderShiftReportDetail(srReportCache[id]); return; }
  body.innerHTML = `<div class="rc-det-loading">⏳ Загружаю чеки смены…</div>`;
  try {
    const d = await posApi(`?action=shift-report&id=${encodeURIComponent(id)}`, { method: 'GET' });
    srReportCache[id] = d.report || {};
    if (detRow.style.display !== 'none') body.innerHTML = renderShiftReportDetail(srReportCache[id]);
  } catch (e) {
    body.innerHTML = `<div class="rc-det-err">⚠ Не удалось загрузить: ${esc(e.message || e)}</div>`;
  }
}

function srPayLabel(rc) {
  const cash = Number(rc.cash_total)||0, nc = Number(rc.noncash_total)||0;
  if (cash>0 && nc>0) return payModeBadge('mixed');
  if (cash>0) return payModeBadge('cash');
  if (nc>0) return payModeBadge('card');
  return payModeBadge(null);
}

function renderShiftReportDetail(rep) {
  if (!rep || !rep.id) return `<div class="rc-det-empty">Отчёт не найден</div>`;
  const recs = Array.isArray(rep.receipts) ? rep.receipts : [];
  const bd = rep.paymentsBreakdown || {};
  const bdKeys = Object.keys(bd);
  const rows = recs.map((rc, i) => {
    const paysTxt = (Array.isArray(rc.payments) && rc.payments.length)
      ? rc.payments.map(p => `${esc(p.label||'Прочее')}: ${fmtNum(Number(p.amount)||0)}`).join(', ')
      : '—';
    return `<tr>
      <td class="c muted">${i+1}</td>
      <td class="strong">№${esc(rc.number||'')}</td>
      <td>${rc.sold_at?dushTime(rc.sold_at,true):'—'}</td>
      <td>${esc(rc.seller||'—')}</td>
      <td class="c">${fmtInt(rc.items_count||0)}</td>
      <td>${srPayLabel(rc)}</td>
      <td class="muted" style="font-size:12px">${esc(paysTxt)}</td>
      <td class="r strong tnum">${fmtNum(Number(rc.total)||0)} ${CUR}</td>
    </tr>`;
  }).join('');
  const bdHTML = bdKeys.length
    ? bdKeys.map(k => `<span class="sr-bd-chip">${esc(k)}: <b>${fmtNum(Number(bd[k])||0)} ${CUR}</b></span>`).join('')
    : '<span class="muted">—</span>';
  return `
    <div class="sr-det-summary">
      <div class="sr-sum-item"><span class="muted">💵 Наличные</span><b style="color:var(--g2)">${money(rep.cashTotal||0)}</b></div>
      <div class="sr-sum-item"><span class="muted">💳 Безналичные</span><b>${money(rep.noncashTotal||0)}</b></div>
      <div class="sr-sum-item"><span class="muted">∑ Выручка</span><b>${money(rep.totalSales||0)}</b></div>
      ${rep.totalReturns? `<div class="sr-sum-item"><span class="muted">↩ Возвраты</span><b style="color:var(--r,#c0392b)">${money(rep.totalReturns)}</b></div>`:''}
    </div>
    <div class="sr-bd-row">${bdHTML}</div>
    <div class="rc-det-head">🧾 Чеки дня — ${fmtInt(recs.length)}</div>
    ${recs.length ? `<div class="tbl-wrap"><table class="tbl rc-items">
      <thead><tr><th style="width:30px">#</th><th>№ чека</th><th>Время</th><th>Кассир</th><th class="c">Позиций</th><th>Вид оплаты</th><th>Детали оплаты</th><th class="r">Сумма</th></tr></thead>
      <tbody>${rows}</tbody>
      <tfoot><tr class="tbl-total"><td colspan="7" class="r">Итого</td><td class="r tnum">${money(rep.totalSales||0)}</td></tr></tfoot>
    </table></div>` : `<div class="tbl-empty">В этой смене нет чеков</div>`}
  `;
}

// кеш состава чеков по ref (чтобы не дёргать 1С при повторном раскрытии)
const rcItemsCache = {};
async function toggleReceipt(tr) {
  const idx = tr.dataset.idx;
  const ref = tr.dataset.ref;
  const num = tr.dataset.num;
  const detRow = $('rcDet-' + idx);
  const body = $('rcDetBody-' + idx);
  const caret = tr.querySelector('.caret');
  if (!detRow || !body) return;

  // тоггл: если открыт — закрываем
  if (detRow.style.display !== 'none') {
    detRow.style.display = 'none';
    tr.classList.remove('open');
    if (caret) caret.textContent = '›';
    return;
  }
  detRow.style.display = '';
  tr.classList.add('open');
  if (caret) caret.textContent = '‹';

  if (!ref) { body.innerHTML = `<div class="rc-det-empty">⚠ У чека нет идентификатора — состав недоступен</div>`; return; }

  // контекст строки (продавец/магазин/время) — фолбэк для «Информации о чеке»
  const rowCtx = { seller: tr.dataset.seller || '', shop: tr.dataset.shop || '', date: tr.dataset.date || '' };

  // из кеша
  if (rcItemsCache[ref]) { body.innerHTML = renderReceiptItems(rcItemsCache[ref], num, rowCtx); wireReceiptDetail(body); return; }

  body.innerHTML = `<div class="rc-det-loading">⏳ Загружаю состав чека…</div>`;
  try {
    const d = await posApi(`?action=receipt-items&ref=${encodeURIComponent(ref)}`, { method: 'GET' });
    rcItemsCache[ref] = d;
    // если за время загрузки строку не закрыли
    if (detRow.style.display !== 'none') { body.innerHTML = renderReceiptItems(d, num, rowCtx); wireReceiptDetail(body); }
  } catch (e) {
    body.innerHTML = `<div class="rc-det-err">⚠ Не удалось загрузить состав: ${esc(e.message || e)}</div>`;
  }
}

// Навешивает обработчики внутри раскрытого чека: копирование uid, печать. Гасит
// всплытие клика, чтобы не свернуть строку при нажатии на кнопки/поля.
function wireReceiptDetail(body) {
  if (!body) return;
  body.addEventListener('click', (ev) => ev.stopPropagation());
  body.querySelectorAll('.rc-copy').forEach(btn => {
    btn.addEventListener('click', async (ev) => {
      ev.stopPropagation();
      const val = btn.dataset.copy || '';
      if (!val) return;
      try {
        if (navigator.clipboard && navigator.clipboard.writeText) await navigator.clipboard.writeText(val);
        else { const ta = document.createElement('textarea'); ta.value = val; document.body.appendChild(ta); ta.select(); document.execCommand('copy'); ta.remove(); }
        btn.classList.add('rc-copied');
        setTimeout(() => btn.classList.remove('rc-copied'), 1200);
      } catch (_) {}
    });
  });
  const printBtn = body.querySelector('.rc-btn-print');
  if (printBtn) printBtn.addEventListener('click', (ev) => { ev.stopPropagation(); window.print(); });
  const dotsBtn = body.querySelector('.rc-btn-dots');
  if (dotsBtn) dotsBtn.addEventListener('click', (ev) => ev.stopPropagation());
  const editBtn = body.querySelector('.rc-btn-edit');
  if (editBtn) editBtn.addEventListener('click', (ev) => {
    ev.stopPropagation();
    const ref = editBtn.dataset.editRef || '';
    const num = editBtn.dataset.editNum || '';
    openReceiptEditModal(ref, num, body);
  });
}

// ═════════════════════════════════════════════════
//  МОДАЛКА РЕДАКТИРОВАНИЯ ЧЕКА (только админ, только Supabase)
//  Меняем: способы оплаты, позиции (кол-во/цена/скидка), сумма пересчитывается.
//  Можно аннулировать чек (void). 1С НЕ трогаем.
// ═════════════════════════════════════════════════
const PAY_KEYS_UI = [
  { key: 'cash',    label: 'Наличные' },
  { key: 'alifqr',  label: 'Alif QR' },
  { key: 'alifwlt', label: 'Alif кошелёк' },
  { key: 'dcqr',    label: 'DC QR' },
  { key: 'dcwlt',   label: 'DC кошелёк' },
];

function openReceiptEditModal(ref, num, cardBody) {
  const d = rcItemsCache[ref];
  if (!d) { alert('Данные чека не загружены'); return; }
  const items = (d.items || []).map((it, i) => ({
    lineNo: (it.lineNo != null ? it.lineNo : i),
    name: it.name || 'Товар',
    barcode: it.barcode || '',
    sizeLabel: it.sizeLabel || '',
    nomC1Ref: it.nomC1Ref || it.nom_c1_ref || '',
    charC1Ref: it.charC1Ref || it.char_c1_ref || '',
    qty: Number(it.qty) || 1,
    price: Number(it.priceUnit != null ? it.priceUnit : it.price) || 0,
    discountPct: Number(it.discountPct) || 0,
    discountSum: Number(it.discountSum) || 0,
  }));
  // текущая раскладка оплаты
  const cash0 = Number(d.cashTotal) || 0;
  const noncash0 = Number(d.noncashTotal) || 0;
  const payInit = {};
  PAY_KEYS_UI.forEach(p => payInit[p.key] = 0);
  // если есть детализация payments[] — берём её, иначе cash/noncash
  if (Array.isArray(d.payments) && d.payments.length) {
    d.payments.forEach(p => { if (payInit[p.key] != null) payInit[p.key] += Number(p.amount) || 0; });
  } else {
    payInit.cash = cash0;
    if (noncash0 > 0) payInit.dcqr = noncash0; // безнал без деталей → DC QR по умолчанию
  }

  const st = { ref, num, items, pay: payInit, voided: !!d.voided, busy: false };

  let ov = document.getElementById('rcEditOverlay');
  if (ov) ov.remove();
  ov = document.createElement('div');
  ov.id = 'rcEditOverlay';
  ov.className = 'rcedit-overlay';
  ov.addEventListener('click', (ev) => { if (ev.target === ov) ov.remove(); });
  document.body.appendChild(ov);

  function itemsTotal() { return st.items.reduce((s, it) => s + Math.max(0, it.qty * it.price - it.discountSum), 0); }
  function payTotal() { return PAY_KEYS_UI.reduce((s, p) => s + (Number(st.pay[p.key]) || 0), 0); }

  function paint() {
    const itTotal = itemsTotal();
    const pTotal = payTotal();
    const diff = Math.round((pTotal - itTotal) * 100) / 100;
    const itemRows = st.items.map((it, i) => `
      <tr data-i="${i}">
        <td class="c">${i + 1}</td>
        <td class="rce-name">${esc(it.name)}${it.sizeLabel ? ` <span class="muted">(${esc(normSizeShort(it.sizeLabel))})</span>` : ''}</td>
        <td><input type="number" class="rce-in rce-qty" data-i="${i}" value="${it.qty}" min="0" step="1"></td>
        <td><input type="number" class="rce-in rce-price" data-i="${i}" value="${it.price}" min="0" step="0.01"></td>
        <td><input type="number" class="rce-in rce-disc" data-i="${i}" value="${it.discountSum}" min="0" step="0.01"></td>
        <td class="r tnum rce-line">${fmtNum(Math.max(0, it.qty * it.price - it.discountSum))}</td>
        <td class="c"><button class="rce-del" data-i="${i}" title="Удалить">✕</button></td>
      </tr>`).join('');
    const payRows = PAY_KEYS_UI.map(p => `
      <div class="rce-payrow">
        <label>${esc(p.label)}</label>
        <input type="number" class="rce-in rce-pay" data-key="${p.key}" value="${Number(st.pay[p.key]) || 0}" min="0" step="0.01">
      </div>`).join('');
    ov.innerHTML = `
      <div class="rcedit-modal" role="dialog">
        <div class="rcedit-head">
          <h3>Редактирование чека № ${esc(st.num)}</h3>
          <button class="rcedit-x" title="Закрыть">✕</button>
        </div>
        <div class="rcedit-warn">⚠ Правка влияет только на отчёты РМК (Supabase). В 1С чек НЕ изменяется.</div>
        <div class="rcedit-body">
          <div class="rce-sec">
            <div class="rce-sec-h"><span>Позиции</span></div>
            <table class="rce-tbl">
              <thead><tr><th class="c">#</th><th>Товар</th><th>Кол-во</th><th>Цена</th><th>Скидка</th><th class="r">Сумма</th><th></th></tr></thead>
              <tbody>${itemRows || '<tr><td colspan="7" class="c muted" style="padding:12px">Нет позиций</td></tr>'}</tbody>
              <tfoot><tr><td colspan="5" class="r">Итого по позициям</td><td class="r strong tnum">${fmtNum(itTotal)} с.</td><td></td></tr></tfoot>
            </table>
          </div>
          <div class="rce-sec">
            <div class="rce-sec-h"><span>Оплата</span></div>
            <div class="rce-pays">${payRows}</div>
            <div class="rce-paysum ${diff === 0 ? 'ok' : 'bad'}">
              Оплачено: <b class="tnum">${fmtNum(pTotal)} с.</b>
              ${diff === 0 ? '<span class="rce-ok">✓ сходится</span>' : `<span class="rce-diff">расхождение с позициями: ${fmtNum(diff)} с.</span>`}
            </div>
          </div>
          <label class="rce-void"><input type="checkbox" class="rce-void-cb" ${st.voided ? 'checked' : ''}> Аннулировать чек (исключить из отчётов)</label>
          <div class="rce-note-wrap"><label>Комментарий (причина правки)</label><input type="text" class="rce-note" placeholder="напр.: ошибка кассира"></div>
        </div>
        <div class="rcedit-foot">
          <button class="rce-delete" ${st.busy ? 'disabled' : ''} title="Удалить чек полностью">🗑 Удалить чек</button>
          <button class="rce-cancel">Отмена</button>
          <button class="rce-save" ${st.busy ? 'disabled' : ''}>${st.busy ? 'Сохраняю…' : 'Сохранить'}</button>
        </div>
      </div>`;
    wireModal();
  }

  function wireModal() {
    ov.querySelector('.rcedit-x').onclick = () => ov.remove();
    ov.querySelector('.rce-cancel').onclick = () => ov.remove();
    ov.querySelectorAll('.rce-qty').forEach(el => el.onchange = () => { const i = +el.dataset.i; st.items[i].qty = Math.max(0, Number(el.value) || 0); paint(); });
    ov.querySelectorAll('.rce-price').forEach(el => el.onchange = () => { const i = +el.dataset.i; st.items[i].price = Math.max(0, Number(el.value) || 0); paint(); });
    ov.querySelectorAll('.rce-disc').forEach(el => el.onchange = () => { const i = +el.dataset.i; st.items[i].discountSum = Math.max(0, Number(el.value) || 0); paint(); });
    ov.querySelectorAll('.rce-del').forEach(el => el.onclick = () => { const i = +el.dataset.i; st.items.splice(i, 1); paint(); });
    ov.querySelectorAll('.rce-pay').forEach(el => el.onchange = () => { st.pay[el.dataset.key] = Math.max(0, Number(el.value) || 0); paint(); });
    ov.querySelector('.rce-void-cb').onchange = (e) => { st.voided = e.target.checked; };
    ov.querySelector('.rce-save').onclick = () => doSave();
    const delBtn = ov.querySelector('.rce-delete');
    if (delBtn) delBtn.onclick = () => doDelete();
  }

  async function doDelete() {
    if (st.busy) return;
    const okConfirm = confirm(
      'Удалить чек № ' + (st.num || '—') + '?\n\n' +
      'Если чек был проведён в 1С — он будет аннулирован (исчезнет из истории и отчётов).\n' +
      'Если чек битый/не попал в 1С (дубль) — он будет удалён полностью.\n\n' +
      'Действие нельзя отменить через интерфейс.'
    );
    if (!okConfirm) return;
    const note = (ov.querySelector('.rce-note') || {}).value || '';
    st.busy = true; paint();
    try {
      const r = await posApi('?action=delete-receipt', {
        method: 'POST',
        body: JSON.stringify({ ref: st.ref, deletedBy: state.user || 'admin', note }),
      });
      if (!r || r.ok === false) throw new Error((r && r.error) || 'ошибка удаления');
      delete rcItemsCache[st.ref];
      if (state.cache) state.cache = {};
      ov.remove();
      alert(r.mode === 'hard' ? 'Чек удалён полностью' : 'Чек аннулирован');
      // обновить список истории, если есть функция перезагрузки
      if (typeof renderHistory === 'function') { try { renderHistory(true); } catch (_) {} }
    } catch (e) {
      st.busy = false; paint();
      alert('Ошибка: ' + (e.message || e));
    }
  }

  async function doSave() {
    if (st.busy) return;
    const note = (ov.querySelector('.rce-note') || {}).value || '';
    // payments — только ненулевые
    const payments = PAY_KEYS_UI
      .map(p => ({ key: p.key, amount: Math.round((Number(st.pay[p.key]) || 0) * 100) / 100 }))
      .filter(p => p.amount > 0);
    const itemsPayload = st.items.map((it, i) => ({
      lineNo: i,
      name: it.name, barcode: it.barcode, sizeLabel: it.sizeLabel,
      nomC1Ref: it.nomC1Ref, charC1Ref: it.charC1Ref,
      qty: it.qty, price: it.price, discountSum: it.discountSum, discountPct: it.discountPct,
    }));
    st.busy = true; paint();
    try {
      const r = await posApi('?action=edit-receipt', {
        method: 'POST',
        body: JSON.stringify({
          ref: st.ref,
          editedBy: state.user || 'admin',
          note,
          payments,
          items: itemsPayload,
          voided: st.voided,
        }),
      });
      if (!r || r.ok === false) throw new Error((r && r.error) || 'ошибка сохранения');
      // инвалидируем кеш и обновляем карточку
      delete rcItemsCache[st.ref];
      if (state.cache) state.cache = {};
      ov.remove();
      alert('Чек обновлён');
      // перезагрузить состав чека в карточке
      if (cardBody) {
        cardBody.innerHTML = `<div class="rc-det-loading">⏳ Обновляю…</div>`;
        try {
          const dd = await posApi(`?action=receipt-items&ref=${encodeURIComponent(st.ref)}`, { method: 'GET' });
          rcItemsCache[st.ref] = dd;
          cardBody.innerHTML = renderReceiptItems(dd, st.num, {});
          wireReceiptDetail(cardBody);
        } catch (_) {}
      }
    } catch (e) {
      st.busy = false; paint();
      alert('Ошибка: ' + (e.message || e));
    }
  }

  paint();
}

// badge способа оплаты для блока «Оплата»
function payModeBadge(mode) {
  if (mode === 'cash') return '<span class="pay-badge pay-cash">Наличные</span>';
  if (mode === 'card') return '<span class="pay-badge pay-card">Безналичные</span>';
  if (mode === 'mixed') return '<span class="pay-badge pay-mixed">Смешанная</span>';
  return '<span class="pay-badge pay-unknown muted">нет данных</span>';
}

function renderReceiptItems(d, num, ctx) {
  ctx = ctx || {};
  const items = (d && d.items) || [];
  const number = num || d.number || '';
  const seller = d.seller || ctx.seller || '—';
  const shop = d.shop || ctx.shop || '—';
  const dateIso = d.date || ctx.date || '';
  const dtLabel = dateIso ? dushTime(dateIso, true) : '—';
  const cashier = d.cashier || seller || '—';
  const opLabel = d.opType === 'return' ? 'Возврат' : 'Продажа';
  const uid = d.ref || '';
  const uidShort = uid ? (uid.replace(/-/g, '').slice(0, 12)) : '—';
  const source = d.source || 'РМК';

  // ── состав чека ──
  const rowsHtml = items.length ? items.map((it, i) => {
    const hasDisc = (it.discountSum && it.discountSum > 0) || (it.discountPct && it.discountPct > 0);
    const discTxt = hasDisc
      ? `<span class="rc-disc">−${fmtNum(it.discountSum || 0)}${it.discountPct ? ` (${it.discountPct}%)` : ''}</span>`
      : '<span class="rc-dash">—</span>';
    const size = it.sizeLabel ? esc(normSizeShort(it.sizeLabel)) : '<span class="rc-dash">—</span>';
    return `<tr>
      <td class="c rc-idx">${i + 1}</td>
      <td class="rc-name">${esc(it.name)}</td>
      <td class="c">${size}</td>
      <td class="c tnum">${fmtInt(it.qty)} шт</td>
      <td class="r tnum">${fmtNum(it.priceUnit)} с.</td>
      <td class="r">${discTxt}</td>
      <td class="r strong tnum">${fmtNum(it.sum)} с.</td>
    </tr>`;
  }).join('') : `<tr><td colspan="7" class="rc-dash c" style="padding:16px">В чеке нет позиций</td></tr>`;
  const total = (d.itemsTotal != null ? d.itemsTotal : d.docTotal) || 0;

  // ── оплата ──
  const cash = Number(d && d.cashTotal) || 0;
  const noncash = Number(d && d.noncashTotal) || 0;
  const paid = cash + noncash || total;
  const change = Math.max(0, paid - total);
  const payRows = [];
  if (cash > 0) payRows.push(`<div class="rc-pay-line"><span>Наличные</span><span class="tnum">${fmtNum(cash)} с.</span></div>`);
  if (noncash > 0) payRows.push(`<div class="rc-pay-line"><span>Безналичные</span><span class="tnum">${fmtNum(noncash)} с.</span></div>`);
  if (!payRows.length) payRows.push(`<div class="rc-pay-line"><span>Наличные</span><span class="tnum">${fmtNum(total)} с.</span></div>`);

  const icoPrint = `<svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M6 9V3h12v6M6 18H4a2 2 0 0 1-2-2v-4a2 2 0 0 1 2-2h16a2 2 0 0 1 2 2v4a2 2 0 0 1-2 2h-2"/><rect x="6" y="14" width="12" height="8" rx="1"/></svg>`;
  const icoDots = `<svg width="16" height="16" viewBox="0 0 24 24" fill="currentColor"><circle cx="12" cy="5" r="1.6"/><circle cx="12" cy="12" r="1.6"/><circle cx="12" cy="19" r="1.6"/></svg>`;
  const icoPrinter = `<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7"><path d="M6 9V3h12v6M6 18H4a2 2 0 0 1-2-2v-4a2 2 0 0 1 2-2h16a2 2 0 0 1 2 2v4a2 2 0 0 1-2 2h-2"/><rect x="6" y="14" width="12" height="8" rx="1"/></svg>`;
  const icoUser = `<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7"><circle cx="12" cy="8" r="3.4"/><path d="M5 20c0-3.3 3.1-5.5 7-5.5s7 2.2 7 5.5"/></svg>`;
  const icoHash = `<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7"><path d="M9 3 7 21M17 3l-2 18M4 8h16M3 16h16"/></svg>`;
  const icoSrc = `<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7"><path d="M6 2h9l5 5v13a1 1 0 0 1-1 1H6a1 1 0 0 1-1-1V3a1 1 0 0 1 1-1z"/><path d="M14 2v6h6"/></svg>`;
  const icoCopy = `<svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><rect x="9" y="9" width="11" height="11" rx="2"/><path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1"/></svg>`;
  const icoEdit = `<svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M12 20h9"/><path d="M16.5 3.5a2.1 2.1 0 0 1 3 3L7 19l-4 1 1-4 12.5-12.5z"/></svg>`;

  return `
    <div class="rc-det">
      <div class="rc-det-grid">
        <div class="rc-col-items">
          <div class="rc-sec-head"><h4>Состав чека</h4></div>
          <div class="rc-poscount">${fmtInt(items.length)} ${plural(items.length,'позиция','позиции','позиций')}</div>
          <div class="rc-items-wrap">
            <table class="rc-items-tbl">
              <thead><tr><th class="c">#</th><th>Товар</th><th class="c">Размер</th><th class="c">Кол-во</th><th class="r">Цена</th><th class="r">Скидка</th><th class="r">Сумма</th></tr></thead>
              <tbody>${rowsHtml}</tbody>
              <tfoot><tr class="rc-items-total"><td colspan="6" class="r">Итого</td><td class="r tnum">${fmtNum(total)} с.</td></tr></tfoot>
            </table>
          </div>
        </div>

        <div class="rc-col-info">
          <div class="rc-sec-head rc-info-head"><h4>Информация о чеке</h4>
            <div class="rc-info-actions">
              <button class="rc-btn-print" data-print="${esc(uid)}">${icoPrint}<span>Печать чека</span></button>
              ${state.allowedTabs === '*' ? `<button class="rc-btn-edit" data-edit-ref="${esc(uid)}" data-edit-num="${esc(number)}">${icoEdit}<span>Редактировать</span></button>` : ''}
              <button class="rc-btn-dots" title="Ещё">${icoDots}</button>
            </div>
          </div>
          <div class="rc-info-cols">
            <div class="rc-info-block">
              <div class="rc-meta-pair"><div class="rc-meta-k">№ чека</div><div class="rc-meta-v strong">${esc(number)}</div></div>
              <div class="rc-meta-pair"><div class="rc-meta-k">Продавец</div><div class="rc-meta-v">${esc(seller)}</div></div>
              <div class="rc-meta-pair"><div class="rc-meta-k">Тип чека</div><div class="rc-meta-v">${esc(opLabel)}</div></div>
            </div>
            <div class="rc-info-block">
              <div class="rc-meta-pair"><div class="rc-meta-k">Дата и время</div><div class="rc-meta-v">${esc(dtLabel)}</div></div>
              <div class="rc-meta-pair"><div class="rc-meta-k">Магазин</div><div class="rc-meta-v">${esc(shop)}</div></div>
            </div>
            <div class="rc-info-block rc-pay-block">
              <div class="rc-pay-title"><span>Оплата</span><span class="badge ok rc-pay-status">Оплачен</span></div>
              <div class="rc-pay-method">${payModeBadge(d.payMode)}</div>
              ${payRows.join('')}
              <div class="rc-pay-line"><span>Сдача</span><span class="tnum">${fmtNum(change)} с.</span></div>
              <div class="rc-pay-line rc-pay-grand"><span>Итого оплачено</span><span class="tnum">${fmtNum(paid)} с.</span></div>
            </div>
          </div>
        </div>
      </div>

      <div class="rc-metabar">
        <div class="rc-metabar-item">${icoPrinter}<div><div class="rc-mb-k">Распечатан</div><div class="rc-mb-v">${esc(dtLabel)}</div></div></div>
        <div class="rc-metabar-item">${icoUser}<div><div class="rc-mb-k">Кассир</div><div class="rc-mb-v">${esc(cashier)}</div></div></div>
        <div class="rc-metabar-item">${icoHash}<div><div class="rc-mb-k">Уникальный код чека</div><div class="rc-mb-v rc-uid">${esc(uidShort)}<button class="rc-copy" data-copy="${esc(uid)}" title="Копировать">${icoCopy}</button></div></div></div>
        <div class="rc-metabar-item">${icoSrc}<div><div class="rc-mb-k">Источник</div><div class="rc-mb-v">${esc(source)}</div></div></div>
      </div>
    </div>`;
}

// краткая метка размера: «размер:21» → «21», «размеры:42» → «42»
function normSizeShort(s) {
  const m = String(s || '').replace(/^\s*размер[ыа]?\s*:?\s*/i, '').trim();
  return m || String(s || '');
}
// простое склонение
function plural(n, one, few, many) {
  const a = Math.abs(n) % 100, b = a % 10;
  if (a > 10 && a < 20) return many;
  if (b > 1 && b < 5) return few;
  if (b === 1) return one;
  return many;
}


// ══════════════════════════════════════════════════════════
//  РАЗДЕЛ: ПЕРЕМЕЩЕНИЕ ТОВАРОВ (склад → склад, со сканером и документом 1С)
//  Пошаговый мастер: 1) выбор складов → 2) сканер → 3) товар добавлен →
//  4) список → 5) сверка → 6) подтверждение → 7) успех (+PDF)
// ══════════════════════════════════════════════════════════
const TR = {
  mode: 'new',         // new (мастер создания) | journal (журнал документов)
  step: 'setup',       // setup | scan | added | list | check | confirm | done
  fromRef: '', fromName: '',
  toRef: '',   toName: '',
  comment: '',
  warehouses: [],      // [{id,name,c1Ref}]
  items: [],           // [{barcode, name, sizeLabel, price, productC1Ref, charC1Ref, qty}]
  lastAdded: null,     // последний добавленный товар (экран «Товар добавлен»)
  sender: '', receiver: '',
  scanner: null,       // Html5Qrcode инстанс
  scanning: false,
  busy: false,
  result: null,        // ответ transfer-create {number, ref, date, ...}
  // ── журнал документов ──
  jList: null,         // массив документов журнала
  jFilter: '',         // '' | 'draft' | 'posted'
  jDoc: null,          // открытая карточка документа
  jBusy: false,
};

async function renderTransfer(force) {
  const box = $('trBody');
  if (force) { TR.step = 'setup'; TR.items = []; TR.result = null; }
  // загрузим склады один раз
  if (!TR.warehouses.length) {
    box.innerHTML = `<div class="loading">⏳ Загружаю склады…</div>`;
    try {
      const d = await posApi('?action=transfer-warehouses', { method: 'GET' });
      TR.warehouses = d.warehouses || [];
    } catch (e) { box.innerHTML = errBar('Не удалось загрузить склады: ' + e.message); return; }
  }
  trPaint();
}

// переключатель режимов раздела (Новое / Журнал)
function trTabsHTML() {
  return `
  <div class="tr-tabs">
    <button class="tr-tab ${TR.mode==='new'?'active':''}" id="trTabNew">➕ Новое перемещение</button>
    <button class="tr-tab ${TR.mode==='journal'?'active':''}" id="trTabJournal">📒 Журнал документов</button>
  </div>`;
}

// единый рендер по текущему шагу
function trPaint() {
  const box = $('trBody');
  if (!box) return;
  // если уходим со сканера — гасим камеру
  if (!(TR.mode === 'new' && TR.step === 'scan')) trStopScanner();

  if (TR.mode === 'journal') {
    box.innerHTML = trTabsHTML() + (TR.jDoc ? trDocCardHTML() : trJournalHTML());
    trBindTabs();
    if (TR.jDoc) trBindDocCard(); else trBindJournal();
    return;
  }

  // режим «Новое»: мастер. Вкладки показываем только на первом шаге (не мешать сканеру)
  const tabs = (TR.step === 'setup') ? trTabsHTML() : '';
  if (TR.step === 'setup')   box.innerHTML = tabs + trSetupHTML();
  else if (TR.step === 'scan')    box.innerHTML = trScanHTML();
  else if (TR.step === 'added')   box.innerHTML = trAddedHTML();
  else if (TR.step === 'list')    box.innerHTML = trListHTML();
  else if (TR.step === 'check')   box.innerHTML = trCheckHTML();
  else if (TR.step === 'confirm') box.innerHTML = trConfirmHTML();
  else if (TR.step === 'done')    box.innerHTML = trDoneHTML();
  if (TR.step === 'setup') trBindTabs();
  trBind();
  if (TR.step === 'scan') trStartScanner();
}

function trBindTabs() {
  const n = $('trTabNew'), j = $('trTabJournal');
  if (n) n.addEventListener('click', () => { TR.mode='new'; TR.step='setup'; trPaint(); });
  if (j) j.addEventListener('click', () => { TR.mode='journal'; TR.jDoc=null; trLoadJournal(); });
}

// ──────────────────── ЖУРНАЛ ДОКУМЕНТОВ ────────────────────
async function trLoadJournal() {
  TR.jBusy = true; trPaint();
  try {
    const qs = TR.jFilter ? ('&status=' + TR.jFilter) : '';
    const d = await posApi('?action=transfer-doc-list&limit=200' + qs, { method: 'GET' });
    TR.jList = d.docs || [];
  } catch (e) { TR.jList = []; }
  TR.jBusy = false; trPaint();
}

function trStatusBadge(st) {
  return st === 'posted'
    ? '<span class="tr-badge tr-badge-ok">Проведён</span>'
    : '<span class="tr-badge tr-badge-draft">Черновик</span>';
}

function trJournalHTML() {
  if (TR.jBusy && TR.jList === null) return `<div class="loading">⏳ Загрузка журнала…</div>`;
  const docs = TR.jList || [];
  const rows = docs.map(d => `
    <tr class="tr-jrow" data-open="${esc(d.id)}">
      <td><b>${esc(d.doc_number)}</b></td>
      <td>${esc((d.doc_date||'').slice(0,10).split('-').reverse().join('.'))}</td>
      <td>${esc(d.from_name||'—')} → ${esc(d.to_name||'—')}</td>
      <td class="c">${fmtInt(d.items_count||0)}</td>
      <td class="c">${trStatusBadge(d.status)}</td>
      <td class="c"><button class="tr-print-btn" data-print="${esc(d.id)}" title="Распечатать документ">🖨</button></td>
    </tr>`).join('');
  return `
  <div class="tr-wrap">
    <div class="tr-card">
      <div class="tr-card-head sm"><span class="tr-ic">📒</span><div><h2>Журнал перемещений</h2><p>Локальные документы (без 1С)</p></div></div>
      <div class="tr-jfilters">
        <button class="tr-chip ${TR.jFilter===''?'active':''}" data-flt="">Все</button>
        <button class="tr-chip ${TR.jFilter==='posted'?'active':''}" data-flt="posted">Проведённые</button>
        <button class="tr-chip ${TR.jFilter==='draft'?'active':''}" data-flt="draft">Черновики</button>
        <button class="tr-btn tr-btn-ghost tr-jrefresh" id="trJRefresh">↻ Обновить</button>
      </div>
      <div class="tbl-wrap">
        <table class="tbl tr-tbl">
          <thead><tr><th>№ док.</th><th>Дата</th><th>Маршрут</th><th class="c">Строк</th><th class="c">Статус</th><th class="c">Печать</th></tr></thead>
          <tbody>${rows || '<tr><td colspan="6" class="tr-empty">Документов нет</td></tr>'}</tbody>
        </table>
      </div>
    </div>
  </div>`;
}

function trBindJournal() {
  const on = (id, fn) => { const el = $(id); if (el) el.addEventListener('click', fn); };
  on('trJRefresh', trLoadJournal);
  document.querySelectorAll('[data-flt]').forEach(b => b.addEventListener('click', () => {
    TR.jFilter = b.dataset.flt; trLoadJournal();
  }));
  document.querySelectorAll('[data-open]').forEach(r => r.addEventListener('click', () => {
    trOpenDoc(r.dataset.open);
  }));
  // Кнопка печати в строке журнала — не открываем карточку (stopPropagation)
  document.querySelectorAll('[data-print]').forEach(b => b.addEventListener('click', (e) => {
    e.stopPropagation();
    trPrintDoc(b.dataset.print);
  }));
}

async function trOpenDoc(id) {
  TR.jBusy = true;
  try {
    const d = await posApi('?action=transfer-doc-get&id=' + encodeURIComponent(id), { method: 'GET' });
    TR.jDoc = d.doc || null;
  } catch (e) { TR.jDoc = null; }
  TR.jBusy = false; trPaint();
}

// ── карточка документа ──
function trDocCardHTML() {
  const d = TR.jDoc || {};
  const posted = d.status === 'posted';
  const items = d.items || [];
  const rows = items.map(it => `
    <tr>
      <td>${esc(it.product_name || '—')}</td>
      <td class="c"><span class="tr-code">${esc(String(it.unique_barcode||'').slice(-4))}</span></td>
      <td class="c">${esc(it.size_label || '—')}</td>
      <td class="c">${it.moved ? '<span class="tr-badge tr-badge-ok">✓</span>' : '<span class="tr-badge tr-badge-draft">—</span>'}</td>
      <td class="c"><button class="tr-del" data-rm="${esc(it.id)}" title="Убрать из документа">✕</button></td>
    </tr>`).join('');
  return `
  <div class="tr-wrap">
    <div class="tr-card">
      <div class="tr-doc-head">
        <button class="tr-btn tr-btn-ghost" id="trDocBack">← К журналу</button>
        <div class="tr-doc-title">${esc(d.doc_number)} ${trStatusBadge(d.status)}</div>
      </div>
      <div class="tr-conf-grid">
        <div class="tr-conf-row"><span>Откуда</span><b>${esc(d.from_name||'—')}</b></div>
        <div class="tr-conf-row"><span>Куда</span><b>${esc(d.to_name||'—')}</b></div>
        <div class="tr-conf-row"><span>Дата</span><b>${esc((d.doc_date||'').slice(0,10).split('-').reverse().join('.'))}</b></div>
        <div class="tr-conf-row"><span>Строк</span><b>${fmtInt(items.length)}</b></div>
        ${d.sender_name ? `<div class="tr-conf-row"><span>Отправил</span><b>${esc(d.sender_name)}</b></div>`:''}
        ${d.comment ? `<div class="tr-conf-row"><span>Комментарий</span><b>${esc(d.comment)}</b></div>`:''}
      </div>

      <div class="tr-info"><span class="tr-info-ic">ℹ️</span><div>${posted
        ? 'Документ <b>проведён</b>. Добавление строки сразу перемещает товар на получателя, удаление — возвращает на отправителя.'
        : 'Документ — <b>черновик</b>. Товар не перемещён, пока вы не нажмёте «Провести».'}</div></div>

      <div class="tr-additem">
        <input type="text" id="trAddBc" class="tr-input" inputmode="numeric" placeholder="Штрихкод для добавления…">
        <button class="tr-btn tr-btn-outline" id="trAddItemBtn">➕ Добавить</button>
      </div>
      <div id="trDocErr"></div>

      <div class="tbl-wrap">
        <table class="tbl tr-tbl">
          <thead><tr><th>Товар</th><th class="c">Код</th><th class="c">Размер</th><th class="c">Перем.</th><th class="c"></th></tr></thead>
          <tbody>${rows || '<tr><td colspan="5" class="tr-empty">Строк нет</td></tr>'}</tbody>
        </table>
      </div>

      <div class="tr-actions tr-doc-actions">
        ${posted
          ? '<button class="tr-btn tr-btn-outline" id="trUnpost">↩ Отменить проведение</button>'
          : '<button class="tr-btn tr-btn-primary" id="trPost">✓ Провести</button>'}
        <button class="tr-btn tr-btn-outline" id="trDocPrint">🖨 Печать</button>
        <button class="tr-btn tr-btn-danger" id="trDocDelete">🗑 Удалить документ</button>
      </div>
    </div>
  </div>`;
}

function trBindDocCard() {
  const on = (id, fn) => { const el = $(id); if (el) el.addEventListener('click', fn); };
  const d = TR.jDoc || {};
  on('trDocBack', () => { TR.jDoc = null; trPaint(); });
  on('trPost', () => trDocAction('transfer-doc-post', { id: d.id }));
  on('trUnpost', () => trDocAction('transfer-doc-unpost', { id: d.id }));
  on('trDocPrint', () => trPrintDocData(d)); // данные уже загружены — печатаем напрямую
  on('trAddItemBtn', trDocAddItem);
  const bcInp = $('trAddBc');
  if (bcInp) bcInp.addEventListener('keydown', e => { if (e.key === 'Enter') trDocAddItem(); });
  document.querySelectorAll('[data-rm]').forEach(b => b.addEventListener('click', () => {
    trDocAction('transfer-doc-remove-item', { id: d.id, itemId: b.dataset.rm });
  }));
  on('trDocDelete', async () => {
    if (!confirm('Удалить документ ' + (d.doc_number||'') + '? Если он проведён — товары вернутся на склад-отправитель.')) return;
    if (TR.jBusy) return; TR.jBusy = true;
    try {
      const r = await posApi('?action=transfer-doc-delete', { method: 'POST', body: JSON.stringify({ id: d.id }) });
      TR.jBusy = false;
      if (r.ok) { TR.jDoc = null; trLoadJournal(); }
      else { const e=$('trDocErr'); if(e) e.innerHTML = errBar(r.error || 'Ошибка удаления'); }
    } catch (ex) { TR.jBusy = false; const e=$('trDocErr'); if(e) e.innerHTML = errBar(ex.message); }
  });
}

async function trDocAction(action, payload) {
  if (TR.jBusy) return; TR.jBusy = true;
  const errBox = $('trDocErr');
  try {
    const r = await posApi('?action=' + action, { method: 'POST', body: JSON.stringify(payload) });
    TR.jBusy = false;
    if (r.ok) {
      TR.jDoc = r.doc || TR.jDoc;
      // предупреждение о неперемещённых
      if (r.notMoved && r.notMoved.length) {
        setTimeout(() => { const e=$('trDocErr'); if(e) e.innerHTML = errBar('Не перемещено: ' + r.notMoved.map(x=>x.barcode+' ('+x.reason+')').join('; ')); }, 50);
      }
      trPaint();
    } else {
      if (errBox) errBox.innerHTML = errBar(r.error || 'Ошибка');
    }
  } catch (ex) { TR.jBusy = false; if (errBox) errBox.innerHTML = errBar(ex.message); }
}

async function trDocAddItem() {
  const inp = $('trAddBc');
  const bc = (inp && inp.value || '').trim();
  const errBox = $('trDocErr');
  if (!bc) { if (errBox) errBox.innerHTML = errBar('Введите штрихкод'); return; }
  if (TR.jBusy) return; TR.jBusy = true;
  try {
    const r = await posApi('?action=transfer-doc-add-item', { method: 'POST', body: JSON.stringify({ id: TR.jDoc.id, barcode: bc }) });
    TR.jBusy = false;
    if (r.ok) { TR.jDoc = r.doc || TR.jDoc; trPaint(); }
    else { if (errBox) errBox.innerHTML = errBar(r.error || 'Ошибка добавления'); }
  } catch (ex) { TR.jBusy = false; if (errBox) errBox.innerHTML = errBar(ex.message); }
}

// ──────────────────── ПЕЧАТЬ ДОКУМЕНТА ПЕРЕМЕЩЕНИЯ ────────────────────
// Из журнала: сначала догружаем полный документ (со строками) по id, затем печатаем.
async function trPrintDoc(id) {
  if (!id) return;
  try {
    const r = await posApi('?action=transfer-doc-get&id=' + encodeURIComponent(id), { method: 'GET' });
    const doc = r.doc || null;
    if (!doc) { alert('Не удалось загрузить документ для печати'); return; }
    trPrintDocData(doc);
  } catch (ex) {
    alert('Ошибка загрузки документа: ' + (ex && ex.message || ex));
  }
}

// Формирует печатную HTML-форму документа и открывает системный диалог печати.
function trPrintDocData(d) {
  d = d || {};
  const items = Array.isArray(d.items) ? d.items : [];
  const dateStr = (d.doc_date || '').slice(0, 10).split('-').reverse().join('.') || '—';
  const timeStr = (function(){ try { return new Date(d.doc_date || Date.now()).toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'}); } catch(_) { return ''; } })();
  const statusTxt = d.status === 'posted' ? 'Проведён' : 'Черновик';
  const P = (s) => String(s == null ? '' : s)
    .replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');

  const rowsHtml = items.length
    ? items.map((it, i) => `
      <tr>
        <td class="n">${i + 1}</td>
        <td>${P(it.product_name || '—')}</td>
        <td class="c">${P(it.size_label || '—')}</td>
        <td class="c mono">${P(it.unique_barcode || '—')}</td>
      </tr>`).join('')
    : `<tr><td colspan="4" class="empty">Строк нет</td></tr>`;

  const html = `<!doctype html>
<html lang="ru"><head><meta charset="utf-8">
<title>Перемещение ${P(d.doc_number || '')}</title>
<style>
  * { box-sizing: border-box; }
  body { font-family: 'Segoe UI', Arial, sans-serif; color:#111; margin:0; padding:24px 28px; font-size:13px; }
  .doc-head { display:flex; justify-content:space-between; align-items:flex-start; border-bottom:2px solid #111; padding-bottom:12px; margin-bottom:16px; }
  .doc-org { font-size:16px; font-weight:700; }
  .doc-org small { display:block; font-weight:400; font-size:11px; color:#555; margin-top:2px; }
  .doc-meta { text-align:right; font-size:12px; }
  h1 { font-size:18px; margin:0 0 4px; }
  .doc-num { font-size:15px; font-weight:700; }
  .route { display:flex; gap:32px; margin:14px 0 6px; }
  .route div { font-size:13px; }
  .route span { display:block; font-size:11px; color:#666; margin-bottom:2px; text-transform:uppercase; letter-spacing:.4px; }
  .route b { font-size:14px; }
  .extra { font-size:12px; color:#333; margin:2px 0 14px; }
  .extra span { color:#666; }
  table { width:100%; border-collapse:collapse; margin-top:8px; }
  th, td { border:1px solid #999; padding:6px 8px; text-align:left; font-size:12px; }
  th { background:#f0f0f0; font-weight:700; }
  td.n { width:36px; text-align:center; color:#555; }
  td.c, th.c { text-align:center; }
  td.mono { font-family:'Consolas','Courier New',monospace; font-size:11px; letter-spacing:.3px; }
  td.empty { text-align:center; color:#888; padding:18px; }
  .total { margin-top:10px; font-size:13px; font-weight:700; text-align:right; }
  .signs { display:flex; justify-content:space-between; margin-top:42px; gap:40px; }
  .signs div { flex:1; }
  .signs .line { border-top:1px solid #111; margin-top:34px; padding-top:4px; font-size:11px; color:#555; text-align:center; }
  .signs .who { font-size:12px; font-weight:600; }
  .foot { margin-top:28px; font-size:10px; color:#999; text-align:center; border-top:1px solid #ddd; padding-top:8px; }
  @media print { body { padding:0; } @page { margin:16mm 14mm; } }
</style></head>
<body>
  <div class="doc-head">
    <div class="doc-org">Ортосалон<small>Документ перемещения товаров между складами</small></div>
    <div class="doc-meta">
      <div class="doc-num">${P(d.doc_number || '—')}</div>
      <div>от ${P(dateStr)}${timeStr ? ' ' + P(timeStr) : ''}</div>
      <div>Статус: ${P(statusTxt)}</div>
    </div>
  </div>

  <div class="route">
    <div><span>Откуда (отправитель)</span><b>${P(d.from_name || '—')}</b></div>
    <div><span>Куда (получатель)</span><b>${P(d.to_name || '—')}</b></div>
  </div>
  ${d.sender_name ? `<div class="extra"><span>Отправил:</span> ${P(d.sender_name)}</div>` : ''}
  ${d.receiver_name ? `<div class="extra"><span>Принял:</span> ${P(d.receiver_name)}</div>` : ''}
  ${d.comment ? `<div class="extra"><span>Комментарий:</span> ${P(d.comment)}</div>` : ''}

  <table>
    <thead><tr><th class="c">№</th><th>Наименование товара</th><th class="c">Размер</th><th class="c">Штрихкод</th></tr></thead>
    <tbody>${rowsHtml}</tbody>
  </table>
  <div class="total">Итого позиций: ${items.length}</div>

  <div class="signs">
    <div><div class="who">Сдал (отправитель)</div><div class="line">подпись / Ф.И.О.</div></div>
    <div><div class="who">Принял (получатель)</div><div class="line">подпись / Ф.И.О.</div></div>
  </div>

  <div class="foot">Напечатано ${P(new Date().toLocaleString('ru-RU'))} · РМК Ортосалон</div>
</body></html>`;

  const w = window.open('', '_blank');
  if (!w) { alert('Разрешите всплывающие окна для печати документа'); return; }
  w.document.open();
  w.document.write(html);
  w.document.close();
  // Ждём отрисовку, затем печать
  w.onload = function () { try { w.focus(); w.print(); } catch (_) {} };
  setTimeout(() => { try { w.focus(); w.print(); } catch (_) {} }, 400);
}

const trUnits = () => TR.items.reduce((s, it) => s + (Number(it.qty) || 1), 0);
const trUniqCodes = () => new Set(TR.items.map(i => i.barcode)).size;
const last4 = (bc) => String(bc || '').slice(-4);

// ── Экран 1: выбор складов ──
function trSetupHTML() {
  const opts = (sel) => TR.warehouses.map(w =>
    `<option value="${esc(w.c1Ref)}" ${sel === w.c1Ref ? 'selected' : ''}>${esc(w.name)}</option>`).join('');
  return `
  <div class="tr-wrap">
    <div class="tr-card tr-setup">
      <div class="tr-card-head"><span class="tr-ic">🔄</span><div><h2>Новое перемещение</h2><p>Выберите склады отправителя и получателя</p></div></div>
      <label class="tr-fld"><span>Откуда (склад-отправитель)</span>
        <select id="trFrom" class="tr-select"><option value="">— выберите склад —</option>${opts(TR.fromRef)}</select></label>
      <label class="tr-fld"><span>Куда (склад-получатель)</span>
        <select id="trTo" class="tr-select"><option value="">— выберите склад —</option>${opts(TR.toRef)}</select></label>
      <label class="tr-fld"><span>Комментарий (необязательно)</span>
        <input type="text" id="trComment" class="tr-input" maxlength="200" placeholder="Напр. плановое пополнение" value="${esc(TR.comment)}"></label>
      <div class="tr-info">
        <span class="tr-info-ic">ℹ️</span>
        <div>После выбора складов откроется камера для сканирования штрихкодов товаров. Каждый отсканированный товар добавится в список перемещения. Документ будет создан и проведён в 1С.</div>
      </div>
      <div id="trSetupErr"></div>
      <button class="tr-btn tr-btn-primary tr-btn-block" id="trStart">📷 Начать сканирование</button>
    </div>
  </div>`;
}

// ── Экран 2: сканер ──
function trScanHTML() {
  return `
  <div class="tr-scan-screen">
    <div class="tr-scan-top">
      <button class="tr-scan-x" id="trScanClose">✕</button>
      <div class="tr-scan-route">${esc(TR.fromName)} → ${esc(TR.toName)}</div>
      <div class="tr-scan-count">${fmtInt(TR.items.length)} тов.</div>
    </div>
    <div class="tr-scan-view">
      <div id="trReader" class="tr-reader"></div>
      <div class="tr-scan-frame"></div>
    </div>
    <div class="tr-scan-hint" id="trScanHint">Отсканируйте штрихкод товара</div>
    <div class="tr-scan-manual">
      <input type="text" id="trManual" class="tr-input" inputmode="numeric" placeholder="Или введите штрихкод вручную">
      <button class="tr-btn tr-btn-ghost" id="trManualAdd">Добавить</button>
    </div>
    <button class="tr-btn tr-btn-outline tr-btn-block" id="trScanFinish">Завершить сканирование (${fmtInt(TR.items.length)})</button>
  </div>`;
}

// ── Экран 3: товар добавлен ──
function trAddedHTML() {
  const it = TR.lastAdded || {};
  return `
  <div class="tr-wrap">
    <div class="tr-card tr-added">
      <div class="tr-added-badge">✓</div>
      <h2 class="tr-added-title">Товар добавлен</h2>
      <div class="tr-prod-card">
        <div class="tr-prod-name">${esc(it.name || '—')}</div>
        <div class="tr-prod-sub">${esc(it.productCode || '')}</div>
        <div class="tr-prod-grid">
          <div><span>Код (посл. 4)</span><b>${esc(last4(it.barcode))}</b></div>
          <div><span>Размер</span><b>${esc(it.sizeLabel || '—')}</b></div>
          <div><span>Кол-во</span><b>${fmtInt(it.qty || 1)}</b></div>
        </div>
      </div>
      <button class="tr-btn tr-btn-primary tr-btn-block" id="trAddNext">📷 Добавить следующий товар</button>
      <button class="tr-btn tr-btn-outline tr-btn-block" id="trGoList">Завершить сканирование (${fmtInt(TR.items.length)})</button>
    </div>
  </div>`;
}

// ── Экран 4: список товаров ──
function trListHTML() {
  const rows = TR.items.map((it, i) => `
    <tr>
      <td class="tr-td-name"><div class="tr-nm">${esc(it.name || '—')}</div><div class="tr-nm-sub">${esc(it.productCode || '')}</div></td>
      <td class="c"><span class="tr-code">${esc(last4(it.barcode))}</span></td>
      <td class="c">${esc(it.sizeLabel || '—')}</td>
      <td class="c">${fmtInt(it.qty || 1)}</td>
      <td class="c"><button class="tr-del" data-del="${i}" title="Убрать">✕</button></td>
    </tr>`).join('');
  return `
  <div class="tr-wrap">
    <div class="tr-kpis">
      <div class="tr-kpi"><span>Товаров</span><b>${fmtInt(TR.items.length)}</b></div>
      <div class="tr-kpi"><span>Всего единиц</span><b>${fmtInt(trUnits())}</b></div>
    </div>
    <div class="tr-card">
      <div class="tr-card-head sm"><span class="tr-ic">📋</span><div><h2>Список товаров</h2><p>${esc(TR.fromName)} → ${esc(TR.toName)}</p></div></div>
      <div class="tbl-wrap">
        <table class="tbl tr-tbl">
          <thead><tr><th>Товар</th><th class="c">Код</th><th class="c">Размер</th><th class="c">Кол-во</th><th class="c"></th></tr></thead>
          <tbody>${rows || '<tr><td colspan="5" class="tr-empty">Список пуст</td></tr>'}</tbody>
        </table>
      </div>
      <div class="tr-actions">
        <button class="tr-btn tr-btn-outline" id="trBackScan">📷 Ещё сканировать</button>
        <button class="tr-btn tr-btn-primary" id="trToCheck" ${TR.items.length ? '' : 'disabled'}>Перейти к сверке →</button>
      </div>
    </div>
  </div>`;
}

// ── Экран 5: сверка ──
function trCheckHTML() {
  const codes = TR.items.map(i => i.barcode);
  const dupMap = {};
  codes.forEach(c => { dupMap[c] = (dupMap[c] || 0) + 1; });
  const dups = Object.keys(dupMap).filter(c => dupMap[c] > 1);
  const notFound = TR.items.filter(i => !i.productC1Ref).length;
  const matched = TR.items.filter(i => i.productC1Ref).length;
  return `
  <div class="tr-wrap">
    <div class="tr-kpis three">
      <div class="tr-kpi"><span>Товаров</span><b>${fmtInt(TR.items.length)}</b></div>
      <div class="tr-kpi"><span>Единиц по факту</span><b>${fmtInt(trUnits())}</b></div>
      <div class="tr-kpi"><span>Уникальных кодов</span><b>${fmtInt(trUniqCodes())}</b></div>
    </div>
    <div class="tr-card">
      <div class="tr-card-head sm"><span class="tr-ic">✅</span><div><h2>Сверка товаров</h2><p>Проверьте коды и количество перед проведением</p></div></div>
      <div class="tr-check-block">
        <div class="tr-check-title">Проверка кодов</div>
        <div class="tr-check-row ok"><span>Совпадают (найдены в 1С)</span><b>${fmtInt(matched)}</b></div>
        <div class="tr-check-row ${notFound ? 'warn' : ''}"><span>Не найдены</span><b>${fmtInt(notFound)}</b></div>
        <div class="tr-check-row ${dups.length ? 'warn' : ''}"><span>Дублируются</span><b>${fmtInt(dups.length)}</b></div>
      </div>
      <div class="tr-check-block">
        <div class="tr-check-title">Проверка количества</div>
        <div class="tr-check-row ok"><span>Совпадает</span><b>${fmtInt(TR.items.length)}</b></div>
        <div class="tr-check-row"><span>Излишки</span><b>0</b></div>
        <div class="tr-check-row"><span>Недостача</span><b>0</b></div>
      </div>
      ${dups.length ? `<div class="tr-info warn"><span class="tr-info-ic">⚠️</span><div>Обнаружены повторяющиеся штрихкоды: ${dups.map(d=>last4(d)).join(', ')}. Один экземпляр = один уникальный штрихкод.</div></div>` : ''}
      <div class="tr-actions">
        <button class="tr-btn tr-btn-outline" id="trBackList">← Назад к списку</button>
        <button class="tr-btn tr-btn-primary" id="trToConfirm">Подтвердить перемещение →</button>
      </div>
    </div>
  </div>`;
}

// ── Экран 6: подтверждение ──
function trConfirmHTML() {
  return `
  <div class="tr-wrap">
    <div class="tr-card">
      <div class="tr-card-head sm"><span class="tr-ic">📝</span><div><h2>Подтверждение перемещения</h2><p>Проверьте данные и укажите ответственных</p></div></div>
      <div class="tr-conf-info">
        <div class="tr-conf-row"><span>Откуда</span><b>${esc(TR.fromName)}</b></div>
        <div class="tr-conf-row"><span>Куда</span><b>${esc(TR.toName)}</b></div>
        <div class="tr-conf-row"><span>Товаров</span><b>${fmtInt(TR.items.length)}</b></div>
        <div class="tr-conf-row"><span>Единиц</span><b>${fmtInt(trUnits())}</b></div>
        <div class="tr-conf-row"><span>Уникальных кодов</span><b>${fmtInt(trUniqCodes())}</b></div>
        ${TR.comment ? `<div class="tr-conf-row"><span>Комментарий</span><b>${esc(TR.comment)}</b></div>` : ''}
      </div>
      <div class="tr-resp">
        <div class="tr-resp-title">Ответственные</div>
        <label class="tr-fld"><span>Отправил</span><input type="text" id="trSender" class="tr-input" placeholder="ФИО отправившего" value="${esc(TR.sender)}"></label>
        <label class="tr-fld"><span>Принял</span><input type="text" id="trReceiver" class="tr-input" placeholder="ФИО принявшего" value="${esc(TR.receiver)}"></label>
      </div>
      <div class="tr-info"><span class="tr-info-ic">ℹ️</span><div>При нажатии будет создан и проведён документ «Перемещение товаров» в 1С. Экземпляры автоматически перевесятся на склад-получатель.</div></div>
      <div id="trConfirmErr"></div>
      <div class="tr-actions">
        <button class="tr-btn tr-btn-outline" id="trBackCheck">← Назад</button>
        <button class="tr-btn tr-btn-primary" id="trDoTransfer">🔄 Переместить товары</button>
      </div>
    </div>
  </div>`;
}

// ── Экран 7: успех ──
function trDoneHTML() {
  const r = TR.result || {};
  return `
  <div class="tr-wrap">
    <div class="tr-card tr-added tr-done">
      <div class="tr-added-badge">✓</div>
      <h2 class="tr-added-title">Перемещение выполнено успешно</h2>
      <div class="tr-done-num">№ ${esc(r.number || '—')}</div>
      <div class="tr-done-date">${esc(r.dateLabel || nowDushLabel())}</div>
      <div class="tr-done-sub">${esc(TR.fromName)} → ${esc(TR.toName)} · ${fmtInt(TR.items.length)} тов. / ${fmtInt(trUnits())} ед.</div>
      <button class="tr-btn tr-btn-primary tr-btn-block" id="trPdf">📄 Скачать документ (PDF)</button>
      <button class="tr-btn tr-btn-outline tr-btn-block" id="trHome">На главную</button>
    </div>
  </div>`;
}

// ── обработчики ──
function trBind() {
  const on = (id, ev, fn) => { const el = $(id); if (el) el.addEventListener(ev, fn); };
  if (TR.step === 'setup') {
    on('trFrom', 'change', e => { TR.fromRef = e.target.value; TR.fromName = trWhName(e.target.value); });
    on('trTo', 'change', e => { TR.toRef = e.target.value; TR.toName = trWhName(e.target.value); });
    on('trComment', 'input', e => { TR.comment = e.target.value; });
    on('trStart', 'click', () => {
      const err = $('trSetupErr');
      if (!TR.fromRef || !TR.toRef) { err.innerHTML = errBar('Выберите оба склада'); return; }
      if (TR.fromRef === TR.toRef) { err.innerHTML = errBar('Склады отправителя и получателя должны отличаться'); return; }
      TR.step = 'scan'; trPaint();
    });
  } else if (TR.step === 'scan') {
    on('trScanClose', 'click', () => { TR.step = TR.items.length ? 'list' : 'setup'; trPaint(); });
    on('trScanFinish', 'click', () => { TR.step = TR.items.length ? 'list' : 'setup'; trPaint(); });
    on('trManualAdd', 'click', () => { const v = ($('trManual').value || '').trim(); if (v) trHandleScan(v); });
    on('trManual', 'keydown', e => { if (e.key === 'Enter') { const v = (e.target.value||'').trim(); if (v) trHandleScan(v); } });
  } else if (TR.step === 'added') {
    on('trAddNext', 'click', () => { TR.step = 'scan'; trPaint(); });
    on('trGoList', 'click', () => { TR.step = 'list'; trPaint(); });
  } else if (TR.step === 'list') {
    on('trBackScan', 'click', () => { TR.step = 'scan'; trPaint(); });
    on('trToCheck', 'click', () => { if (TR.items.length) { TR.step = 'check'; trPaint(); } });
    document.querySelectorAll('[data-del]').forEach(b => b.addEventListener('click', () => {
      TR.items.splice(Number(b.dataset.del), 1); trPaint();
    }));
  } else if (TR.step === 'check') {
    on('trBackList', 'click', () => { TR.step = 'list'; trPaint(); });
    on('trToConfirm', 'click', () => { TR.step = 'confirm'; trPaint(); });
  } else if (TR.step === 'confirm') {
    on('trSender', 'input', e => { TR.sender = e.target.value; });
    on('trReceiver', 'input', e => { TR.receiver = e.target.value; });
    on('trBackCheck', 'click', () => { TR.step = 'check'; trPaint(); });
    on('trDoTransfer', 'click', trDoTransfer);
  } else if (TR.step === 'done') {
    on('trPdf', 'click', trBuildPDF);
    on('trHome', 'click', () => { TR.step = 'setup'; TR.items = []; TR.result = null; TR.comment=''; TR.sender=''; TR.receiver=''; trPaint(); });
  }
}

function trWhName(ref) { const w = TR.warehouses.find(x => x.c1Ref === ref); return w ? w.name : ''; }

// ── сканер ──
function trStartScanner() {
  const el = $('trReader');
  if (!el || TR.scanning) return;
  if (typeof Html5Qrcode === 'undefined') { const h = $('trScanHint'); if (h) h.textContent = 'Сканер недоступен — введите штрихкод вручную'; return; }
  try {
    TR.scanner = new Html5Qrcode('trReader', { verbose: false });
    TR.scanning = true;
    const fmts = (window.Html5QrcodeSupportedFormats) ? [
      Html5QrcodeSupportedFormats.EAN_13, Html5QrcodeSupportedFormats.EAN_8, Html5QrcodeSupportedFormats.CODE_128,
    ] : undefined;
    TR.scanner.start({ facingMode: 'environment' },
      { fps: 10, qrbox: { width: 260, height: 160 }, ...(fmts ? { formatsToSupport: fmts } : {}) },
      (txt) => { const bc = String(txt || '').trim(); if (bc) trHandleScan(bc); },
      () => {}
    ).catch(err => { const h = $('trScanHint'); if (h) h.textContent = 'Нет доступа к камере — введите штрихкод вручную'; TR.scanning = false; });
  } catch (e) { TR.scanning = false; }
}
function trStopScanner() {
  if (TR.scanner && TR.scanning) {
    try { TR.scanner.stop().then(() => { try { TR.scanner.clear(); } catch(_){} }).catch(()=>{}); } catch(_){}
  }
  TR.scanning = false; TR.scanner = null;
}

let trScanLock = false;
async function trHandleScan(barcode) {
  if (TR.busy || trScanLock) return;
  trScanLock = true;
  setTimeout(() => { trScanLock = false; }, 900); // антидребезг
  const hint = $('trScanHint');
  // дубликат экземпляра — один штрихкод = один экземпляр
  if (TR.items.some(i => i.barcode === barcode)) {
    if (hint) { hint.textContent = 'Этот штрихкод уже добавлен'; hint.classList.add('warn'); setTimeout(()=>hint&&hint.classList.remove('warn'),1500); }
    return;
  }
  if (hint) hint.textContent = 'Ищу товар…';
  TR.busy = true;
  try {
    const d = await posApi(`?action=transfer-scan&barcode=${encodeURIComponent(barcode)}&warehouse=${encodeURIComponent(TR.fromRef)}`, { method: 'GET' });
    if (!d.found) {
      if (hint) { hint.textContent = 'Товар не найден: ' + barcode; hint.classList.add('warn'); setTimeout(()=>hint&&hint.classList.remove('warn'),2000); }
      TR.busy = false; return;
    }
    // ПРЕДОХРАНИТЕЛЬ СНЯТ (по требованию 2026-08-08):
    // разрешаем добавлять ЛЮБОЙ найденный экземпляр независимо от склада/статуса.
    // При проведении сервер (moveUnitLocal) восстановит его в in_stock
    // и переместит на склад-получатель. Показываем только инфо-подсказку,
    // если товар числится не там/не in_stock — но НЕ блокируем.
    // Откат: вернуть блок `if (d.inSourceWh !== true) { … return; }`.
    if (d.inSourceWh !== true && hint) {
      const st = d.status && d.status !== 'in_stock' ? ' (' + d.status + ')' : '';
      hint.textContent = 'ℹ️ Товар числится на другом складе' + st + ' — будет восстановлен и перемещён';
      setTimeout(()=>hint&&(hint.textContent=''),3200);
    }
    const it = {
      barcode: d.uniqueBarcode || barcode,
      name: d.name || '—',
      productCode: d.productCode || '',
      sizeLabel: (d.sizeLabel || '').replace(/^размер:\s*/i, ''),
      price: Number(d.price) || 0,
      productC1Ref: d.productC1Ref || null,
      charC1Ref: d.charC1Ref || null,
      qty: 1,
    };
    TR.items.push(it);
    TR.lastAdded = it;
    TR.busy = false;
    TR.step = 'added';
    trPaint();
  } catch (e) {
    TR.busy = false;
    if (hint) { hint.textContent = 'Ошибка: ' + e.message; hint.classList.add('warn'); setTimeout(()=>hint&&hint.classList.remove('warn'),2000); }
  }
}

// ── проведение (WRITE в 1С — только по явному нажатию пользователя) ──
async function trDoTransfer() {
  if (TR.busy) return;
  const err = $('trConfirmErr');
  const btn = $('trDoTransfer');
  TR.busy = true;
  if (btn) { btn.disabled = true; btn.textContent = '⏳ Создаю документ в 1С…'; }
  try {
    const body = {
      fromC1Ref: TR.fromRef, toC1Ref: TR.toRef, comment: TR.comment,
      senderName: TR.sender, receiverName: TR.receiver,
      items: TR.items.map(i => ({ barcode: i.barcode, productC1Ref: i.productC1Ref, charC1Ref: i.charC1Ref, price: i.price, qty: i.qty })),
      dryRun: false,
    };
    const d = await posApi('?action=transfer-create', { method: 'POST', body: JSON.stringify(body) });
    TR.result = { number: d.number, ref: d.ref, date: d.date, dateLabel: d.date ? dushTime(d.date, true) : nowDushLabel(), sumTotal: d.sumTotal };
    TR.busy = false;
    TR.step = 'done';
    trPaint();
  } catch (e) {
    TR.busy = false;
    if (btn) { btn.disabled = false; btn.textContent = '🔄 Переместить товары'; }
    if (err) err.innerHTML = errBar('Не удалось провести перемещение: ' + e.message);
  }
}

// ── PDF документа перемещения ──
function trBuildPDF() {
  const r = TR.result || {};
  try {
    const { jsPDF } = window.jspdf;
    const doc = new jsPDF({ unit: 'mm', format: 'a4' });
    // шрифт с кириллицей (из fonts-dejavu.js); fallback — helvetica
    const FONT = (doc.getFontList && doc.getFontList().DejaVuSans) ? 'DejaVuSans' : 'helvetica';
    const W = 210, M = 14;
    let y = 18;
    doc.setFont(FONT, 'bold'); doc.setFontSize(16);
    doc.text('Перемещение товаров', M, y);
    doc.setFontSize(11); doc.setFont(FONT, 'normal');
    doc.text('Документ №: ' + (r.number || '-'), M, y + 7);
    doc.text('Дата: ' + (r.dateLabel || nowDushLabel()), M, y + 13);
    y += 22;
    doc.setDrawColor(210); doc.line(M, y, W - M, y); y += 8;

    doc.setFont(FONT, 'bold'); doc.text('Откуда:', M, y);
    doc.setFont(FONT, 'normal'); doc.text(String(TR.fromName || '-'), M + 24, y);
    y += 7;
    doc.setFont(FONT, 'bold'); doc.text('Куда:', M, y);
    doc.setFont(FONT, 'normal'); doc.text(String(TR.toName || '-'), M + 24, y);
    y += 9;
    doc.setFont(FONT, 'bold'); doc.text('Отправил:', M, y);
    doc.setFont(FONT, 'normal'); doc.text(String(TR.sender || '____________________'), M + 24, y);
    doc.setFont(FONT, 'bold'); doc.text('Принял:', W/2, y);
    doc.setFont(FONT, 'normal'); doc.text(String(TR.receiver || '____________________'), W/2 + 22, y);
    y += 6;

    const rows = TR.items.map((it, i) => [
      String(i + 1), String(it.name || '-'), last4(it.barcode), it.sizeLabel || '-', String(it.qty || 1),
    ]);
    doc.autoTable({
      startY: y + 2,
      head: [['#', 'Товар', 'Код (посл.4)', 'Размер', 'Кол-во']],
      body: rows,
      styles: { font: FONT, fontSize: 9, cellPadding: 2 },
      headStyles: { font: FONT, fontStyle: 'bold', fillColor: [16, 185, 129], textColor: 255, halign: 'center' },
      columnStyles: { 0: { halign: 'center', cellWidth: 12 }, 2: { halign: 'center' }, 3: { halign: 'center' }, 4: { halign: 'center' } },
      margin: { left: M, right: M },
    });
    let yy = doc.lastAutoTable.finalY + 8;
    doc.setFont(FONT, 'bold'); doc.setFontSize(11);
    doc.text('Итого единиц: ' + trUnits(), M, yy);
    doc.text('Уник. кодов: ' + trUniqCodes(), M + 70, yy);
    yy += 14;
    doc.setDrawColor(16, 185, 129); doc.setLineWidth(0.6);
    doc.roundedRect(M, yy - 6, W - 2*M, 12, 2, 2);
    doc.setTextColor(16, 133, 96);
    doc.text('Перемещение подтверждено', W/2, yy + 2, { align: 'center' });
    doc.setTextColor(0,0,0);

    doc.save(`peremeshchenie_${r.number || 'doc'}.pdf`);
  } catch (e) {
    alert('Не удалось сформировать PDF: ' + e.message);
  }
}


// ══════════════════════════════════════════════════════════
//  РАЗДЕЛ: ДВИЖЕНИЕ ДЕНЕЖНЫХ СРЕДСТВ (расходы/выручка + ИИ)
// ══════════════════════════════════════════════════════════
const FIN = {
  loaded: false,
  cats: [],        // категории
  salons: [],      // [{warehouse_id,name}]
  expenses: [],    // расходы за период
  sub: 'overview', // под-вкладка: overview | expenses | fixed | compare | revenue | suppliers | employees
  page: 1,
  perPage: 25,
  flt: { cat: '', salon: '', kind: '', q: '' },
  form: { kind: 'variable' }, // состояние панели добавления
  // расширение «Выручка-Расходы»
  profit: null,      // сводка прибыли (fin-profit)
  suppliers: null,   // [{...,debt_tjs,debt_foreign}]
  employees: null,   // [{...,salaries:[]}]
  fx: null,          // {USD:{rate,date},CNY:{...}}
  supOpsOpen: null,  // id открытого поставщика (история операций)
};

// первый и последний день текущего месяца по Душанбе (для дефолтного периода)
function finMonthBounds() {
  const t = dushToday();               // YYYY-MM-DD
  const ym = t.slice(0, 7);
  const first = ym + '-01';
  const y = +ym.slice(0, 4), m = +ym.slice(5, 7);
  const lastDay = new Date(Date.UTC(y, m, 0)).getUTCDate();
  const last = `${ym}-${String(lastDay).padStart(2, '0')}`;
  return { first, last, ym };
}
function finKindLabel(k) { return k === 'fixed' ? 'Постоянный' : 'Переменный'; }
function finOwnerLabel(o) { return o === 'salon' ? 'Салон' : (o === 'office' ? 'Офис' : 'Общий'); }
function finSalonName(id) { const s = FIN.salons.find(x => x.warehouse_id === id); return s ? s.name : '—'; }
function finCatName(id) { const c = FIN.cats.find(x => x.id === id); return c ? c.name : null; }
function finCatIcon(id) { const c = FIN.cats.find(x => x.id === id); return c && c.icon ? c.icon : '📌'; }
// период расхода для отображения: expense_date или период-месяц
function finExpDate(e) { return e.expense_date || (e.period_month ? e.period_month : ''); }

// ══════════════════════════════════════════════════════════
//  РАЗДЕЛ: БЕКАПЫ (резервное копирование и восстановление)
// ══════════════════════════════════════════════════════════
const BK = { loaded: false, tab: 'state', overview: null, runs: [], sel: null, sections: [], secPage: 1, secPer: 10 };

// человеческий размер (байты → KB/MB/GB)
function fmtBytes(n) {
  const b = Number(n) || 0;
  if (b < 1024) return b + ' B';
  if (b < 1024 * 1024) return (b / 1024).toFixed(2) + ' KB';
  if (b < 1024 * 1024 * 1024) return (b / (1024 * 1024)).toFixed(2) + ' MB';
  return (b / (1024 * 1024 * 1024)).toFixed(2) + ' GB';
}
// ISO → «DD.MM.YYYY HH:MM» по Душанбе (+5)
function bkDT(iso) {
  if (!iso) return '—';
  const d = new Date(iso); if (isNaN(d)) return '—';
  const s = new Date(d.getTime() + 5 * 3600 * 1000);
  const p = (x) => String(x).padStart(2, '0');
  return `${p(s.getUTCDate())}.${p(s.getUTCMonth() + 1)}.${s.getUTCFullYear()} ${p(s.getUTCHours())}:${p(s.getUTCMinutes())}`;
}
// минут → «через N мин / N ч M мин»
function bkMinsUntil(iso) {
  if (!iso) return '—';
  const diff = Math.round((new Date(iso) - new Date()) / 60000);
  if (diff <= 0) return 'сейчас';
  if (diff < 60) return `через ${diff} мин`;
  return `через ${Math.floor(diff / 60)} ч ${diff % 60} мин`;
}

async function renderBackups(force) {
  const box = $('bkBody');
  if (force) BK.loaded = false;
  if (!BK.loaded) {
    box.innerHTML = `<div class="loading">⏳ Загружаю данные бэкапов…</div>`;
    try {
      const [ov, ls] = await Promise.all([
        posApi('?action=backup-overview', { method: 'GET' }),
        posApi('?action=backup-list&limit=200', { method: 'GET' }),
      ]);
      BK.overview = ov || {};
      BK.runs = (ls && ls.runs) || [];
      const defFull = BK.runs.find(r => r.kind === 'full') || BK.runs[0] || null;
      BK.sel = defFull ? defFull.run_id : null;
      if (BK.sel) { await bkLoadSections(BK.sel); }
      BK.loaded = true;
    } catch (e) {
      box.innerHTML = errBar('Не удалось загрузить бэкапы: ' + (e.message || e));
      return;
    }
  }
  bkPaint();
}

async function bkLoadSections(runId) {
  const d = await posApi('?action=backup-sections&run_id=' + encodeURIComponent(runId), { method: 'GET' });
  BK.sections = (d && d.sections) || [];
  BK.secPage = 1;
}

function bkTabBtn(key, label) {
  return `<button class="bk-tab ${BK.tab === key ? 'active' : ''}" data-bktab="${key}">${label}</button>`;
}

function bkPaint() {
  const box = $('bkBody');
  box.innerHTML = `
    <div class="bk-tabs">
      ${bkTabBtn('state', 'Состояние')}
      ${bkTabBtn('history', 'История')}
      ${bkTabBtn('settings', 'Настройки')}
      ${bkTabBtn('restore', 'Восстановление')}
      <div class="bk-tabs-actions">
        <button class="btn btn-primary btn-sm" id="bkCreateNow">☁ Создать бэкап сейчас</button>
      </div>
    </div>
    <div id="bkTabBody"></div>
    <div class="bk-footinfo">
      <span class="bk-footinfo-ic">ℹ</span>
      <b>Информация:</b> Бэкапы хранятся в Supabase и проверяются на целостность после каждого создания. Транзакционные — каждые 30 мин, полный — раз в сутки.
    </div>
  `;
  box.querySelectorAll('.bk-tab').forEach(b =>
    b.addEventListener('click', () => { BK.tab = b.dataset.bktab; bkPaint(); }));
  $('bkCreateNow').addEventListener('click', () => bkCreate('full'));
  bkPaintTab();
}

function bkPaintTab() {
  const t = BK.tab;
  if (t === 'state') return bkPaintState();
  if (t === 'history') return bkPaintHistory();
  if (t === 'settings') return bkPaintSettings();
  if (t === 'restore') return bkPaintRestore();
}

// ─── ВКЛАДКА «СОСТОЯНИЕ»: 6 KPI + таблица разделов ───
function bkPaintState() {
  const box = $('bkTabBody');
  const o = BK.overview || {};
  const lf = o.last_full || null;
  const rpo = o.rpo_minutes;
  const rpoTone = rpo == null ? 'gray' : (rpo <= 45 ? 'g' : (rpo <= 120 ? 'amber' : 'red'));
  const rpoSub = rpo == null ? 'нет данных' : (rpo <= 45 ? 'Норма' : (rpo <= 120 ? 'Повышенный' : 'Критичный'));
  const kpis = `
    <div class="kpis bk-kpis">
      ${kpi('✅', 'Последний успешный бэкап', lf ? `<span style="font-size:19px">${bkDT(lf.at)}</span>` : '—', 'g', lf ? 'Полный бэкап' : 'нет бэкапов')}
      ${kpi('⏱', 'Следующий бэкап', `<span style="font-size:19px">${bkDT(o.next_tx_at)}</span>`, 'gray', bkMinsUntil(o.next_tx_at) + ' · инкрементальный')}
      ${kpi('🗄', 'Размер последней копии', lf ? fmtBytes(lf.size_bytes) : '—', 'gray', 'сжатый jsonb')}
      ${kpi('🛡', 'Защищено данных', `${fmtInt(o.sections_total || 0)} <small>разд.</small>`, 'g', fmtInt(o.records_total || 0) + ' записей')}
      ${kpi('☁', 'Статус хранилища', 'Supabase <small>OK</small>', 'g', `полных ${fmtInt(o.full_count || 0)} · tx ${fmtInt(o.tx_count || 0)}`)}
      ${kpi('⚠', 'RPO (потеря данных)', rpo == null ? '—' : `${rpo} <small>мин</small>`, rpoTone, rpoSub)}
    </div>`;

  box.innerHTML = kpis + `
    <div class="card card-pad" style="margin-top:4px">
      <div class="card-h-row">
        <div><h3>Состояние разделов</h3><div class="muted" style="font-size:12.5px;margin-top:2px">Сверка данных в последнем бэкапе</div></div>
        <button class="btn btn-ghost btn-sm" id="bkRefreshSec">↻ Проверить все разделы</button>
      </div>
      <div id="bkSecWrap"></div>
    </div>`;
  $('bkRefreshSec').addEventListener('click', async () => {
    if (!BK.sel) return;
    $('bkSecWrap').innerHTML = `<div class="loading">⏳ Проверяю…</div>`;
    try { await bkLoadSections(BK.sel); } catch (e) { $('bkSecWrap').innerHTML = errBar(e.message || e); return; }
    bkPaintSections();
  });
  bkPaintSections();
}

function bkPaintSections() {
  const wrap = $('bkSecWrap'); if (!wrap) return;
  const all = BK.sections || [];
  if (!all.length) { wrap.innerHTML = `<div class="tbl-empty">Нет данных по разделам</div>`; return; }
  const per = BK.secPer, page = BK.secPage;
  const pages = Math.max(1, Math.ceil(all.length / per));
  const rows = all.slice((page - 1) * per, page * per);
  const statusBadge = (m) => m === 'ok'
    ? `<span class="badge ok">✓ Успешно</span>`
    : (m === 'partial' ? `<span class="badge amber2">⚠ Частично</span>` : `<span class="badge off">—</span>`);
  const checkBadge = (s) => s.match === 'ok'
    ? `<span class="bk-chk ok">Совпадает</span>`
    : (s.match === 'partial' ? `<span class="bk-chk bad">${s.diff > 0 ? '+' : ''}${s.diff} зап.</span>` : `<span class="bk-chk">—</span>`);
  const body = rows.map(s => `
    <tr>
      <td class="strong">${esc(s.title)}</td>
      <td class="muted">${esc(s.data_type)}</td>
      <td class="r tnum">${s.live_count == null ? '—' : fmtInt(s.live_count)}</td>
      <td class="r tnum">${fmtInt(s.backup_count)}</td>
      <td class="c muted">${bkDT(s.created_at)}</td>
      <td class="c">${statusBadge(s.match)}</td>
      <td class="c">${checkBadge(s)}</td>
      <td class="r muted">${fmtBytes(s.size_bytes)}</td>
    </tr>`).join('');
  wrap.innerHTML = `
    <div class="tbl-wrap">
      <table class="tbl">
        <thead><tr>
          <th>Раздел</th><th>Тип данных</th><th class="r">Записей в системе</th>
          <th class="r">В последнем бэкапе</th><th class="c">Последний бэкап</th>
          <th class="c">Статус</th><th class="c">Проверка</th><th class="r">Размер</th>
        </tr></thead>
        <tbody>${body}</tbody>
      </table>
    </div>
    <div class="bk-pager">
      <span class="muted">Показано ${rows.length} из ${all.length}</span>
      <div class="bk-pager-btns">
        <button class="btn btn-ghost btn-sm" id="bkSecPrev" ${page <= 1 ? 'disabled' : ''}>‹</button>
        <span class="bk-pager-cur">${page} / ${pages}</span>
        <button class="btn btn-ghost btn-sm" id="bkSecNext" ${page >= pages ? 'disabled' : ''}>›</button>
      </div>
    </div>`;
  const pv = $('bkSecPrev'), nx = $('bkSecNext');
  if (pv) pv.addEventListener('click', () => { if (BK.secPage > 1) { BK.secPage--; bkPaintSections(); } });
  if (nx) nx.addEventListener('click', () => { if (BK.secPage < pages) { BK.secPage++; bkPaintSections(); } });
}

// ─── ВКЛАДКА «ИСТОРИЯ» ───
function bkPaintHistory() {
  const box = $('bkTabBody');
  const runs = BK.runs || [];
  const rowsH = runs.map(r => `
    <tr>
      <td class="c muted">${bkDT(r.created_at)}</td>
      <td class="c">${r.kind === 'tx' ? '<span class="badge off">Инкрементальный</span>' : '<span class="badge ok">Полный</span>'}</td>
      <td class="r muted">${fmtBytes(r.size_bytes)}</td>
      <td class="r tnum">${fmtInt(r.rows_total)}</td>
      <td class="c tnum">${fmtInt(r.tables_count)}</td>
      <td class="muted" style="font-size:12px">${esc(r.version || '')}</td>
      <td class="c"><span class="badge ok">✓ Успешно</span></td>
      <td class="c"><button class="btn btn-ghost btn-sm" data-bkrestore="${esc(r.run_id)}">↺ Восстановить</button></td>
    </tr>`).join('');
  box.innerHTML = `
    <div class="card card-pad">
      <div class="card-h-row"><h3>История бэкапов</h3><span class="muted">Всего точек: ${runs.length}</span></div>
      <div class="tbl-wrap"><table class="tbl">
        <thead><tr><th class="c">Дата и время</th><th class="c">Тип</th><th class="r">Размер</th><th class="r">Записей</th><th class="c">Разделов</th><th>Версия</th><th class="c">Статус</th><th class="c">Действия</th></tr></thead>
        <tbody>${rowsH || `<tr><td colspan="8" class="tbl-empty">Нет бэкапов</td></tr>`}</tbody>
      </table></div>
    </div>`;
  box.querySelectorAll('[data-bkrestore]').forEach(b =>
    b.addEventListener('click', () => { BK.sel = b.dataset.bkrestore; BK.tab = 'restore'; bkPaint(); }));
}

// ─── ВКЛАДКА «НАСТРОЙКИ» ───
function bkPaintSettings() {
  const box = $('bkTabBody');
  const row = (k, v) => `<div class="bk-set-row"><span class="bk-set-k">${k}</span><span class="bk-set-v">${v}</span></div>`;
  box.innerHTML = `
    <div class="card card-pad" style="max-width:640px">
      <div class="card-h-row"><h3>Настройки бэкапов</h3></div>
      ${row('Тип расписания', '<b>Смешанное</b>')}
      ${row('Инкрементальный (транзакции)', '<b class="bk-g">Каждые 30 минут</b>')}
      ${row('Полный бэкап', '<b class="bk-g">Ежедневно в 03:00 (Ташкент)</b>')}
      ${row('Хранение транзакционных', '24 часа (48 снимков)')}
      ${row('Хранение полных', '30 дней')}
      ${row('Хранилище', 'Supabase (PostgreSQL, таблица rmk_backups)')}
      ${row('Проверка целостности', 'Сверка со счётчиками live')}
      <div class="muted" style="font-size:12px;margin-top:14px">Расписание управляется Vercel Cron. Ручной бэкап — кнопкой «Создать бэкап сейчас».</div>
    </div>`;
}

// ─── ВКЛАДКА «ВОССТАНОВЛЕНИЕ» ───
function bkPaintRestore() {
  const box = $('bkTabBody');
  const runs = BK.runs || [];
  const opts = runs.map(r => `<option value="${esc(r.run_id)}" ${r.run_id === BK.sel ? 'selected' : ''}>${bkDT(r.created_at)} — ${r.kind === 'tx' ? 'инкрементальный' : 'полный'} (${fmtInt(r.rows_total)} зап.)</option>`).join('');
  const secs = BK.sections || [];
  const chk = secs.map(s => `
    <label class="bk-rest-chk"><input type="checkbox" class="bk-rt" value="${esc(s.table)}" checked> ${esc(s.title)} <span class="muted">(${fmtInt(s.backup_count)})</span></label>`).join('');
  box.innerHTML = `
    <div class="card card-pad">
      <div class="card-h-row"><div><h3>Быстрое восстановление</h3><div class="muted" style="font-size:12.5px;margin-top:2px">Сначала — безопасная проверка (dry-run), потом подтверждение.</div></div></div>
      <div class="bk-rest-grid">
        <div>
          <label class="bk-lbl">Точка восстановления</label>
          <select id="bkRunSel" class="bk-select">${opts || '<option>Нет точек</option>'}</select>
          <label class="bk-lbl" style="margin-top:12px">Тип восстановления</label>
          <div class="bk-mode">Upsert по id (обновить/добавить, без удаления текущих)</div>
        </div>
        <div>
          <div class="bk-rest-chk-head"><label class="bk-lbl">Разделы для восстановления</label><label class="bk-rest-chk bk-all"><input type="checkbox" id="bkAll" checked> Выбрать все</label></div>
          <div class="bk-rest-chks">${chk || '<span class="muted">Сначала выберите точку</span>'}</div>
        </div>
      </div>
      <div id="bkRestResult"></div>
      <div class="bk-rest-actions">
        <button class="btn btn-ghost" id="bkDryRun">🔍 Проверить (dry-run)</button>
        <button class="btn btn-primary" id="bkDoRestore" style="min-width:280px">↺ Запустить восстановление</button>
      </div>
    </div>`;
  $('bkRunSel').addEventListener('change', async (e) => {
    BK.sel = e.target.value;
    $('bkRestResult').innerHTML = `<div class="loading">⏳ Загружаю разделы…</div>`;
    try { await bkLoadSections(BK.sel); } catch (err) { $('bkRestResult').innerHTML = errBar(err.message || err); return; }
    bkPaintRestore();
  });
  const allCb = $('bkAll');
  if (allCb) allCb.addEventListener('change', () => {
    box.querySelectorAll('.bk-rt').forEach(c => { c.checked = allCb.checked; });
  });
  $('bkDryRun').addEventListener('click', () => bkRestore(true));
  $('bkDoRestore').addEventListener('click', () => bkRestore(false));
}

function bkSelectedTables() {
  const box = $('bkTabBody');
  const all = Array.from(box.querySelectorAll('.bk-rt'));
  const checked = all.filter(c => c.checked).map(c => c.value);
  if (!all.length || checked.length === all.length) return null;
  return checked;
}

async function bkRestore(dryRun) {
  if (!BK.sel) { alert('Сначала выберите точку восстановления'); return; }
  const tables = bkSelectedTables();
  const selCount = tables == null ? (BK.sections || []).length : tables.length;
  if (selCount === 0) { alert('Выберите хотя бы один раздел'); return; }
  if (!dryRun) {
    const ptLabel = bkDT((BK.runs.find(r => r.run_id === BK.sel) || {}).created_at);
    if (!confirm(`ВНИМАНИЕ: реальное восстановление из точки ${ptLabel}.\nРазделов: ${selCount}. Данные будут обновлены/добавлены по id (без удаления текущих).\n\nПродолжить?`)) return;
  }
  const btn = dryRun ? $('bkDryRun') : $('bkDoRestore');
  const old = btn ? btn.textContent : '';
  if (btn) { btn.disabled = true; btn.textContent = dryRun ? 'Проверяю…' : 'Восстанавливаю…'; }
  try {
    const d = await posApi('?action=backup-restore', {
      method: 'POST',
      body: JSON.stringify({ run_id: BK.sel, tables, dry_run: dryRun }),
    });
    const rows = (d.tables || []).map(r => `<tr><td class="strong">${esc(r.title)}</td><td class="r tnum">${fmtInt(r.rows)}</td><td class="muted">${esc(r.note || '')}</td></tr>`).join('');
    const head = dryRun
      ? `<div class="bk-rest-note dry">🔍 Проверка (dry-run): будет восстановлено <b>${fmtInt(d.total_rows)}</b> записей. Реальная запись НЕ произведена.</div>`
      : `<div class="bk-rest-note done">✅ Восстановлено <b>${fmtInt(d.total_rows)}</b> записей в ${(d.tables||[]).length} раздел(ах).</div>`;
    $('bkRestResult').innerHTML = head + `<div class="tbl-wrap" style="margin-top:10px"><table class="tbl"><thead><tr><th>Раздел</th><th class="r">Записей</th><th>Примечание</th></tr></thead><tbody>${rows}</tbody></table></div>`;
  } catch (e) {
    $('bkRestResult').innerHTML = errBar('Ошибка восстановления: ' + (e.message || e));
  } finally {
    if (btn) { btn.disabled = false; btn.textContent = old; }
  }
}

async function bkCreate(kind) {
  const label = kind === 'tx' ? 'транзакционный' : 'полный';
  if (!confirm(`Создать ${label} бэкап сейчас?`)) return;
  const btn = $('bkCreateNow');
  const old = btn ? btn.textContent : '';
  if (btn) { btn.disabled = true; btn.textContent = 'Создаю…'; }
  try {
    const d = await posApi('?action=backup-create', {
      method: 'POST',
      body: JSON.stringify({ kind, version: 'RMK v' + RMK_VERSION + (kind === 'tx' ? ' tx' : ' manual'), keepDays: 30, keepHours: 24 }),
    });
    alert(`✅ Бэкап создан: ${fmtInt(d.rows_total)} записей в ${d.tables_count} таблицах.`);
    BK.loaded = false;
    renderBackups(true);
  } catch (e) {
    alert('Ошибка создания бэкапа: ' + (e.message || e));
  } finally {
    if (btn) { btn.disabled = false; btn.textContent = old; }
  }
}


async function renderFinance(force) {
  const box = $('finBody');
  if (force) FIN.loaded = false;
  if (!FIN.loaded) {
    box.innerHTML = `<div class="loading">⏳ Загружаю финансовые данные…</div>`;
    try {
      const b = finMonthBounds();
      if (!FIN._from) { FIN._from = b.first; FIN._to = b.last; }
      const [catsR, salonsR] = await Promise.all([
        cachedApi('fin:cats', '?action=fin-categories'),
        cachedApi('fin:salons', '?action=fin-salons'),
      ]);
      FIN.cats = catsR.categories || [];
      FIN.salons = salonsR.salons || [];
      await finLoadExpenses();
      FIN.loaded = true;
    } catch (e) {
      box.innerHTML = errBar('Не удалось загрузить финансы: ' + (e.message || e));
      return;
    }
  }
  finPaint();
}

// загрузка расходов за выбранный период (по period_month через from/to)
async function finLoadExpenses() {
  const fromM = (FIN._from || '').slice(0, 7) + '-01';
  const toM = (FIN._to || '').slice(0, 7) + '-01';
  const d = await posApi(`?action=fin-expenses&from=${fromM}&to=${toM}`, { method: 'GET' });
  FIN.expenses = (d.expenses || []);
}

// текущий набор расходов после клиентских фильтров (категория/салон/тип/поиск/подвкладка)
function finFiltered() {
  let arr = FIN.expenses.slice();
  if (FIN.sub === 'fixed') arr = arr.filter(e => e.kind === 'fixed');
  if (FIN.flt.kind) arr = arr.filter(e => e.kind === FIN.flt.kind);
  if (FIN.flt.cat) arr = arr.filter(e => (e.category_id || '') === FIN.flt.cat);
  if (FIN.flt.salon) arr = arr.filter(e => (e.warehouse_id || '') === FIN.flt.salon);
  if (FIN.flt.q) {
    const q = FIN.flt.q.toLowerCase();
    arr = arr.filter(e => {
      const cat = (finCatName(e.category_id) || '').toLowerCase();
      const t = (e.title || '').toLowerCase();
      const cm = (e.comment || '').toLowerCase();
      return cat.includes(q) || t.includes(q) || cm.includes(q);
    });
  }
  // фильтр по датам внутри периода (по expense_date, если задан)
  arr = arr.filter(e => {
    const d = e.expense_date;
    if (!d) return true;
    if (FIN._from && d < FIN._from) return false;
    if (FIN._to && d > FIN._to) return false;
    return true;
  });
  return arr;
}

function finPaint() {
  const box = $('finBody');
  const per = FIN._from === FIN._to ? FIN._from : `${FIN._from} — ${FIN._to}`;
  const all = FIN.expenses;
  const totalAll = all.reduce((s, e) => s + (+e.amount || 0), 0);
  const totalFixed = all.filter(e => e.kind === 'fixed').reduce((s, e) => s + (+e.amount || 0), 0);
  const totalVar = totalAll - totalFixed;
  const pFixed = totalAll ? Math.round(totalFixed / totalAll * 100) : 0;
  const pVar = totalAll ? 100 - pFixed : 0;

  const subChip = (key, label) =>
    `<button class="fin-chip ${FIN.sub === key ? 'active' : ''}" data-sub="${key}">${label}</button>`;

  box.innerHTML = `
    <!-- Верхняя панель: период + магазины + экспорт -->
    <div class="fin-toolbar">
      <div class="fin-period">
        <label>Период
          <span class="fin-daterange">
            <input type="date" id="finFrom" value="${FIN._from}">
            <span>—</span>
            <input type="date" id="finTo" value="${FIN._to}">
          </span>
        </label>
        <button class="btn btn-ghost btn-sm" id="finApplyPeriod">Применить</button>
      </div>
      <div class="fin-tb-right">
        <span class="badge off">Все магазины (${FIN.salons.length})</span>
        <button class="btn btn-ghost btn-sm" id="finExport">⬇ Экспорт</button>
      </div>
    </div>

    <!-- Под-вкладки -->
    <div class="fin-chips">
      ${subChip('overview', '📊 Обзор')}
      ${subChip('expenses', 'Постоянные/переменные расходы')}
      ${subChip('fixed', 'Расходы по категориям')}
      ${subChip('suppliers', '🏷 Долги поставщикам')}
      ${subChip('employees', '👥 Сотрудники и зарплаты')}
      ${subChip('compare', 'Сравнение 6 мес')}
      ${subChip('revenue', 'Выручка (ручной ввод)')}
    </div>

    <div id="finSubBody"></div>
  `;

  // события верхней панели
  $('finApplyPeriod').addEventListener('click', async () => {
    const f = $('finFrom').value, t = $('finTo').value;
    if (!f || !t) return;
    FIN._from = f; FIN._to = t; FIN.page = 1;
    $('finSubBody').innerHTML = `<div class="loading">⏳ Обновляю…</div>`;
    try { await finLoadExpenses(); } catch (e) { $('finSubBody').innerHTML = errBar(e.message || e); return; }
    finPaintSub();
  });
  $('finExport').addEventListener('click', finExportCsv);
  box.querySelectorAll('.fin-chip').forEach(b =>
    b.addEventListener('click', () => { FIN.sub = b.dataset.sub; FIN.page = 1; finPaint(); }));

  finPaintSub({ totalAll, totalFixed, totalVar, pFixed, pVar, per });
}

function finPaintSub(pre) {
  if (FIN.sub === 'overview') return finPaintOverview();
  if (FIN.sub === 'suppliers') return finPaintSuppliers();
  if (FIN.sub === 'employees') return finPaintEmployees();
  if (FIN.sub === 'compare') return finPaintCompare();
  if (FIN.sub === 'revenue') return finPaintRevenue();
  // expenses / fixed → одинаковая раскладка (fixed отфильтрован в finFiltered)
  finPaintExpenses(pre);
}

// ————— Основной экран расходов —————
function finPaintExpenses(pre) {
  const host = $('finSubBody');
  const all = FIN.expenses;
  const totalAll = all.reduce((s, e) => s + (+e.amount || 0), 0);
  const totalFixed = all.filter(e => e.kind === 'fixed').reduce((s, e) => s + (+e.amount || 0), 0);
  const totalVar = totalAll - totalFixed;
  const pFixed = totalAll ? Math.round(totalFixed / totalAll * 100) : 0;
  const pVar = totalAll ? 100 - pFixed : 0;

  // структура по категориям (для пончика) — по всем расходам периода
  const byCat = new Map();
  for (const e of all) {
    const key = e.category_id || ('t:' + (e.title || 'Прочее'));
    const name = finCatName(e.category_id) || e.title || 'Прочее';
    const cur = byCat.get(key) || { name, amount: 0 };
    cur.amount += (+e.amount || 0); byCat.set(key, cur);
  }
  const catList = Array.from(byCat.values()).sort((a, b) => b.amount - a.amount);

  const filtered = finFiltered();
  const totalFiltered = filtered.reduce((s, e) => s + (+e.amount || 0), 0);
  const pages = Math.max(1, Math.ceil(filtered.length / FIN.perPage));
  if (FIN.page > pages) FIN.page = pages;
  const pageRows = filtered.slice((FIN.page - 1) * FIN.perPage, FIN.page * FIN.perPage);

  const catOpts = ['<option value="">Все категории</option>']
    .concat(FIN.cats.map(c => `<option value="${c.id}" ${FIN.flt.cat === c.id ? 'selected' : ''}>${esc(c.name)}</option>`)).join('');
  const salonOpts = ['<option value="">Все магазины</option>']
    .concat(FIN.salons.map(s => `<option value="${s.warehouse_id}" ${FIN.flt.salon === s.warehouse_id ? 'selected' : ''}>${esc(s.name)}</option>`)).join('');

  host.innerHTML = `
    <!-- Панель фильтров -->
    <div class="fin-filters card card-pad">
      <div class="fin-flt-grid">
        <label class="fld-inline"><span>Категория</span>
          <select id="finFltCat">${catOpts}</select></label>
        <label class="fld-inline"><span>Магазин</span>
          <select id="finFltSalon">${salonOpts}</select></label>
        <label class="fld-inline"><span>Тип расхода</span>
          <select id="finFltKind">
            <option value="">Все типы</option>
            <option value="fixed" ${FIN.flt.kind === 'fixed' ? 'selected' : ''}>Постоянный</option>
            <option value="variable" ${FIN.flt.kind === 'variable' ? 'selected' : ''}>Переменный</option>
          </select></label>
        <label class="fld-inline fin-search"><span>Поиск</span>
          <input type="text" id="finFltQ" placeholder="Название, категория, комментарий…" value="${esc(FIN.flt.q)}"></label>
      </div>
    </div>

    <!-- KPI + пончик -->
    <div class="fin-grid-kpi">
      <div class="kpis" style="grid-template-columns:repeat(auto-fit,minmax(180px,1fr));margin-bottom:0">
        ${kpi('💸','Всего расходов', money(totalAll),'red', `${all.length} записей`)}
        ${kpi('📌','Постоянные', money(totalFixed),'amber', `${pFixed}% от суммы`)}
        ${kpi('🔁','Переменные', money(totalVar),'gray', `${pVar}% от суммы`)}
      </div>
      <div class="card card-pad fin-donut-card">
        <div class="card-h-row"><h3>Структура расходов</h3></div>
        <div class="fin-donut-wrap">
          <div class="chart-box" style="height:200px;position:relative"><canvas id="finDonut"></canvas></div>
          <div class="fin-legend" id="finLegend"></div>
        </div>
      </div>
    </div>

    <!-- Основной ряд: таблица + панель добавления -->
    <div class="fin-main-row">
      <div class="card card-pad fin-table-card">
        <div class="card-h-row">
          <h3>Список расходов</h3>
          <button class="btn btn-primary btn-sm" id="finAddBtn">+ Добавить расход</button>
        </div>
        <div class="tbl-wrap">
          <table class="tbl fin-tbl">
            <thead><tr>
              <th>Дата</th><th>Тип</th><th>Категория</th><th>Название</th>
              <th>Магазин</th><th class="r">Сумма</th><th>Комментарий</th><th></th>
            </tr></thead>
            <tbody>
              ${pageRows.length ? pageRows.map(finRowHtml).join('') :
                `<tr><td colspan="8" class="tbl-empty">Нет расходов по фильтрам</td></tr>`}
            </tbody>
            ${filtered.length ? `<tfoot><tr class="tbl-total">
              <td colspan="5">Итого (${filtered.length})</td>
              <td class="r neg">${money(totalFiltered)}</td><td colspan="2"></td>
            </tr></tfoot>` : ''}
          </table>
        </div>
        ${pages > 1 ? `<div class="fin-pager">
          <button class="btn btn-ghost btn-sm" id="finPrev" ${FIN.page <= 1 ? 'disabled' : ''}>‹ Назад</button>
          <span class="muted">Стр. ${FIN.page} из ${pages}</span>
          <button class="btn btn-ghost btn-sm" id="finNext" ${FIN.page >= pages ? 'disabled' : ''}>Вперёд ›</button>
        </div>` : ''}
      </div>

      <div class="card card-pad fin-add-card" id="finAddCard">
        <div class="card-h-row"><h3>Добавить расход</h3></div>
        ${finAddFormHtml()}
      </div>
    </div>

    <!-- ИИ-блоки -->
    <div class="fin-ai-row">
      <div class="card card-pad fin-ai-card">
        <div class="fin-ai-head"><span class="fin-ai-ic purple">🧠</span>
          <div><div class="fin-ai-title">ИИ-аналитик расходов</div>
          <div class="fin-ai-sub">Анализ структуры расходов за период на базе Claude</div></div></div>
        <div class="fin-ai-body" id="finAiAnalysisBody">
          <p class="muted">Нажмите «Подробнее», чтобы ИИ проанализировал расходы за выбранный месяц.</p>
        </div>
        <button class="btn btn-ghost btn-sm" id="finAiAnalysisBtn">Подробнее →</button>
      </div>
      <div class="card card-pad fin-ai-card">
        <div class="fin-ai-head"><span class="fin-ai-ic green">💡</span>
          <div><div class="fin-ai-title">ИИ-рекомендация</div>
          <div class="fin-ai-sub">Быстрое добавление расхода из текста</div></div></div>
        <div class="fin-ai-body">
          <textarea id="finAiText" class="fin-ai-text" rows="2" placeholder="Напр.: аренда Сиёма 4500 за июль"></textarea>
          <div id="finAiParsePreview"></div>
        </div>
        <button class="btn btn-ghost btn-sm" id="finAiParseBtn">Разобрать текст →</button>
      </div>
    </div>

    <!-- Графики -->
    <div class="fin-charts-row">
      <div class="card card-pad">
        <div class="card-h-row"><h3>Динамика расходов</h3><span class="muted">По дням</span></div>
        <div class="chart-box" style="height:220px"><canvas id="finTrend"></canvas></div>
      </div>
      <div class="card card-pad">
        <div class="card-h-row"><h3>Расходы по категориям (за период)</h3></div>
        ${catList.length ? hbars(catList.slice(0, 12).map(c => ({
          label: `${c.name}`, value: c.amount,
          extra: totalAll ? Math.round(c.amount / totalAll * 100) + '%' : ''
        })), { money: true }) : `<div class="tbl-empty">Нет данных</div>`}
      </div>
    </div>
  `;

  // ——— пончик ———
  finDrawDonut('finDonut', 'finLegend', catList);
  // ——— график динамики ———
  finDrawTrend('finTrend', filtered);

  // ——— события фильтров ———
  $('finFltCat').addEventListener('change', e => { FIN.flt.cat = e.target.value; FIN.page = 1; finPaintSub(); });
  $('finFltSalon').addEventListener('change', e => { FIN.flt.salon = e.target.value; FIN.page = 1; finPaintSub(); });
  $('finFltKind').addEventListener('change', e => { FIN.flt.kind = e.target.value; FIN.page = 1; finPaintSub(); });
  let qT;
  $('finFltQ').addEventListener('input', e => { clearTimeout(qT); const v = e.target.value; qT = setTimeout(() => { FIN.flt.q = v; FIN.page = 1; finPaintSub(); }, 250); });

  // пагинация
  if ($('finPrev')) $('finPrev').addEventListener('click', () => { if (FIN.page > 1) { FIN.page--; finPaintSub(); } });
  if ($('finNext')) $('finNext').addEventListener('click', () => { FIN.page++; finPaintSub(); });

  // строки: удаление
  host.querySelectorAll('[data-del]').forEach(b =>
    b.addEventListener('click', () => finDeleteExpense(b.dataset.del)));

  // кнопка «+ Добавить» — фокус на панель
  $('finAddBtn').addEventListener('click', () => {
    const c = $('finAddCard'); if (c) { c.classList.add('flash'); setTimeout(() => c.classList.remove('flash'), 800); c.scrollIntoView({ behavior: 'smooth', block: 'nearest' }); }
    const amt = $('finFAmount'); if (amt) amt.focus();
  });

  finBindAddForm();
  finBindAi();
}

function finRowHtml(e) {
  const dt = finExpDate(e);
  const dtShow = dt ? dt.slice(0, 10).split('-').reverse().join('.') : '—';
  const kindCls = e.kind === 'fixed' ? 'amber' : 'gray';
  return `<tr>
    <td class="muted">${dtShow}</td>
    <td><span class="badge ${kindCls}">${finKindLabel(e.kind)}</span></td>
    <td>${finCatIcon(e.category_id)} ${esc(finCatName(e.category_id) || '—')}</td>
    <td>${esc(e.title || '—')}</td>
    <td class="muted">${e.warehouse_id ? esc(finSalonName(e.warehouse_id)) : finOwnerLabel(e.owner_type)}</td>
    <td class="r neg strong">${money(+e.amount || 0)}</td>
    <td class="muted">${esc(e.comment || '')}</td>
    <td class="r"><button class="fin-del" data-del="${e.id}" title="Удалить">✕</button></td>
  </tr>`;
}

// ————— Форма добавления —————
function finAddFormHtml() {
  const f = FIN.form;
  const catOpts = ['<option value="">— выбрать —</option>']
    .concat(FIN.cats.map(c => `<option value="${c.id}" ${f.category_id === c.id ? 'selected' : ''}>${esc(c.name)}</option>`)).join('');
  const salonOpts = ['<option value="">— выбрать —</option>']
    .concat(FIN.salons.map(s => `<option value="${s.warehouse_id}" ${f.warehouse_id === s.warehouse_id ? 'selected' : ''}>${esc(s.name)}</option>`)).join('');
  const today = dushToday();
  return `
    <div class="fin-form">
      <div class="fin-kind-toggle">
        <button class="fin-kt ${f.kind !== 'variable' ? 'active' : ''}" data-kind="fixed">Постоянный</button>
        <button class="fin-kt ${f.kind === 'variable' ? 'active' : ''}" data-kind="variable">Переменный</button>
      </div>
      <label class="fld-inline"><span>Владелец</span>
        <select id="finFOwner">
          <option value="salon" ${f.owner_type === 'salon' || !f.owner_type ? 'selected' : ''}>Салон</option>
          <option value="office" ${f.owner_type === 'office' ? 'selected' : ''}>Офис</option>
          <option value="common" ${f.owner_type === 'common' ? 'selected' : ''}>Общий</option>
        </select></label>
      <label class="fld-inline" id="finFSalonWrap"><span>Магазин (салон)</span>
        <select id="finFSalon">${salonOpts}</select></label>
      <label class="fld-inline"><span>Категория</span>
        <select id="finFCat">${catOpts}</select></label>
      <label class="fld-inline"><span>Название</span>
        <input type="text" id="finFTitle" placeholder="Напр.: Аренда за июль" value="${esc(f.title || '')}"></label>
      <label class="fld-inline"><span>Сумма (с.)</span>
        <input type="number" id="finFAmount" min="0" step="0.01" placeholder="0.00" value="${f.amount != null ? f.amount : ''}"></label>
      <label class="fld-inline"><span>Дата</span>
        <input type="date" id="finFDate" value="${f.expense_date || today}"></label>
      <label class="fld-inline"><span>Комментарий</span>
        <input type="text" id="finFComment" placeholder="Необязательно" value="${esc(f.comment || '')}"></label>
      <button class="btn btn-primary btn-block" id="finSaveBtn">Сохранить расход</button>
      <div id="finSaveMsg"></div>
    </div>`;
}

function finBindAddForm() {
  const owner = $('finFOwner');
  const salonWrap = $('finFSalonWrap');
  const syncSalon = () => { salonWrap.style.display = owner.value === 'salon' ? '' : 'none'; };
  syncSalon();
  owner.addEventListener('change', () => { FIN.form.owner_type = owner.value; syncSalon(); });

  document.querySelectorAll('.fin-kt').forEach(b =>
    b.addEventListener('click', () => {
      FIN.form.kind = b.dataset.kind;
      document.querySelectorAll('.fin-kt').forEach(x => x.classList.toggle('active', x === b));
    }));

  $('finSaveBtn').addEventListener('click', finSaveExpense);
}

async function finSaveExpense() {
  const msg = $('finSaveMsg');
  const owner_type = $('finFOwner').value;
  const kind = document.querySelector('.fin-kt.active') ? document.querySelector('.fin-kt.active').dataset.kind : 'variable';
  const warehouse_id = $('finFSalon').value || null;
  const category_id = $('finFCat').value || null;
  const title = $('finFTitle').value.trim();
  const amount = parseFloat($('finFAmount').value);
  const expense_date = $('finFDate').value || null;
  const comment = $('finFComment').value.trim();

  if (!(amount >= 0) || isNaN(amount)) { msg.innerHTML = errBar('Введите корректную сумму'); return; }
  if (owner_type === 'salon' && !warehouse_id) { msg.innerHTML = errBar('Для салона выберите магазин'); return; }

  msg.innerHTML = `<div class="muted">Сохраняю…</div>`;
  try {
    await posApi('?action=fin-expense-create', { method: 'POST', body: JSON.stringify({
      owner_type, kind, warehouse_id, category_id, title, amount, expense_date, comment,
    }) });
    // сброс формы (кроме типа/владельца)
    FIN.form = { kind, owner_type, warehouse_id };
    state.cache = {}; // сбрасываем кеш
    await finLoadExpenses();
    finPaint();
    // сообщение об успехе покажем после перерисовки
    const m2 = $('finSaveMsg'); if (m2) m2.innerHTML = `<div class="fin-ok">✓ Расход добавлен</div>`;
  } catch (e) {
    msg.innerHTML = errBar('Не удалось сохранить: ' + (e.message || e));
  }
}

async function finDeleteExpense(id) {
  if (!confirm('Удалить этот расход?')) return;
  try {
    await posApi('?action=fin-expense-delete', { method: 'POST', body: JSON.stringify({ id }) });
    FIN.expenses = FIN.expenses.filter(e => e.id !== id);
    state.cache = {};
    finPaintSub();
  } catch (e) { alert('Не удалось удалить: ' + (e.message || e)); }
}

// ————— ИИ —————
function finBindAi() {
  $('finAiAnalysisBtn').addEventListener('click', finRunAiAnalysis);
  $('finAiParseBtn').addEventListener('click', finRunAiParse);
}

async function finRunAiAnalysis() {
  const body = $('finAiAnalysisBody');
  body.innerHTML = `<div class="loading">🧠 ИИ анализирует расходы…</div>`;
  try {
    const month = (FIN._from || dushToday()).slice(0, 7) + '-01';
    const d = await posApi('?action=fin-ai-analysis', { method: 'POST', body: JSON.stringify({ month }) });
    const a = d.analysis || {};
    const recs = Array.isArray(a.recommendations) ? a.recommendations : [];
    body.innerHTML = `
      <p class="fin-ai-summary">${esc(a.summary || '—')}</p>
      ${a.largest ? `<p class="muted">Наибольшая категория: <b>${esc(a.largest)}</b></p>` : ''}
      ${recs.length ? `<ul class="fin-ai-list">${recs.map(r => `<li>${esc(r)}</li>`).join('')}</ul>` : ''}
      <p class="muted" style="font-size:12px">Расходы: ${money(d.total_expenses || 0)} · Выручка: ${money(d.total_revenue || 0)}</p>`;
  } catch (e) {
    const m = (e.message || '') + '';
    body.innerHTML = errBar(m.includes('503') || m.toLowerCase().includes('anthropic') || m.toLowerCase().includes('ии недоступен')
      ? 'ИИ недоступен: не задан ключ Claude в настройках сервера.'
      : 'Не удалось получить анализ: ' + m);
  }
}

async function finRunAiParse() {
  const prev = $('finAiParsePreview');
  const text = $('finAiText').value.trim();
  if (!text) { prev.innerHTML = errBar('Введите текст расхода'); return; }
  prev.innerHTML = `<div class="loading">🤖 Разбираю…</div>`;
  try {
    const d = await posApi('?action=fin-ai-parse', { method: 'POST', body: JSON.stringify({ text }) });
    const p = d.preview || {};
    prev.innerHTML = `
      <div class="fin-parse-card">
        <div class="fin-parse-grid">
          <div><span class="muted">Тип</span><b>${finKindLabel(p.kind)}</b></div>
          <div><span class="muted">Владелец</span><b>${finOwnerLabel(p.owner_type)}${p.salon_name ? ' · ' + esc(p.salon_name) : ''}</b></div>
          <div><span class="muted">Категория</span><b>${esc(p.category_name || '—')}${p.category_is_new ? ' <span class="badge amber">новая</span>' : ''}</b></div>
          <div><span class="muted">Сумма</span><b>${money(p.amount || 0)}</b></div>
          <div><span class="muted">Месяц</span><b>${(p.period_month || '').slice(0, 7)}</b></div>
        </div>
        <button class="btn btn-primary btn-sm btn-block" id="finParseApply">Заполнить форму этими данными →</button>
      </div>`;
    $('finParseApply').addEventListener('click', () => {
      FIN.form = {
        kind: p.kind, owner_type: p.owner_type, warehouse_id: p.warehouse_id || '',
        category_id: p.category_id || '', title: p.title || (p.category_is_new ? p.category_name : ''),
        amount: p.amount || '', expense_date: (p.period_month || '').slice(0, 10),
      };
      // перерисуем только форму
      const card = $('finAddCard');
      if (card) { card.innerHTML = `<div class="card-h-row"><h3>Добавить расход</h3></div>` + finAddFormHtml(); finBindAddForm(); card.classList.add('flash'); setTimeout(() => card.classList.remove('flash'), 800); card.scrollIntoView({ behavior: 'smooth', block: 'nearest' }); }
    });
  } catch (e) {
    const m = (e.message || '') + '';
    prev.innerHTML = errBar(m.includes('503') || m.toLowerCase().includes('ии недоступен')
      ? 'ИИ недоступен: не задан ключ Claude в настройках сервера.'
      : 'Не удалось разобрать: ' + m);
  }
}

// ————— Пончик (Chart.js) —————
const FIN_DONUT_COLORS = ['#10b981','#059669','#3b82f6','#f59e0b','#e11d48','#8b5cf6','#14b8a6','#f97316','#0ea5e9','#ec4899','#84cc16','#64748b'];
function finDrawDonut(canvasId, legendId, catList) {
  const el = $(canvasId); if (!el) return;
  destroyChart(canvasId);
  const top = catList.slice(0, 8);
  const rest = catList.slice(8);
  const restSum = rest.reduce((s, x) => s + x.amount, 0);
  const items = restSum > 0 ? top.concat([{ name: 'Прочее', amount: restSum }]) : top;
  const total = items.reduce((s, x) => s + x.amount, 0);
  if (!total) { const lg = $(legendId); if (lg) lg.innerHTML = '<span class="muted">Нет данных</span>'; return; }
  state.charts[canvasId] = new Chart(el, {
    type: 'doughnut',
    data: { labels: items.map(x => x.name),
      datasets: [{ data: items.map(x => Math.round(x.amount)),
        backgroundColor: items.map((_, i) => FIN_DONUT_COLORS[i % FIN_DONUT_COLORS.length]), borderWidth: 0 }] },
    options: { responsive: true, maintainAspectRatio: false, cutout: '62%', plugins: { legend: { display: false },
      tooltip: { callbacks: { label: c => `${c.label}: ${fmtNum(c.parsed)} с. (${Math.round(c.parsed / total * 100)}%)` } } } },
  });
  const lg = $(legendId);
  if (lg) lg.innerHTML = items.map((x, i) => `
    <div class="fin-leg-row">
      <span class="fin-leg-dot" style="background:${FIN_DONUT_COLORS[i % FIN_DONUT_COLORS.length]}"></span>
      <span class="fin-leg-name">${esc(x.name)}</span>
      <span class="fin-leg-val">${Math.round(x.amount / total * 100)}%</span>
    </div>`).join('');
}

// ————— График динамики по дням —————
function finDrawTrend(canvasId, expenses) {
  const el = $(canvasId); if (!el) return;
  destroyChart(canvasId);
  const byDay = new Map();
  for (const e of expenses) {
    const d = finExpDate(e).slice(0, 10);
    if (!d) continue;
    byDay.set(d, (byDay.get(d) || 0) + (+e.amount || 0));
  }
  const days = Array.from(byDay.keys()).sort();
  if (!days.length) {
    const ctx = el.getContext('2d'); ctx.clearRect(0, 0, el.width, el.height);
    return;
  }
  state.charts[canvasId] = new Chart(el, {
    type: 'line',
    data: { labels: days.map(d => d.slice(5)),
      datasets: [{ label: 'Расходы', data: days.map(d => Math.round(byDay.get(d))),
        borderColor: '#10b981', backgroundColor: 'rgba(16,185,129,.12)', fill: true, tension: .3, pointRadius: 3 }] },
    options: { responsive: true, maintainAspectRatio: false, plugins: { legend: { display: false },
      tooltip: { callbacks: { label: c => `${fmtNum(c.parsed.y)} с.` } } },
      scales: { y: { ticks: { callback: v => fmtInt(v) } } } },
  });
}

// ————— Под-вкладка: Сравнение 6 месяцев —————
async function finPaintCompare() {
  const host = $('finSubBody');
  host.innerHTML = `<div class="loading">⏳ Считаю по месяцам…</div>`;
  try {
    // возьмём последние 6 месяцев относительно конца выбранного периода
    const end = (FIN._to || dushToday()).slice(0, 7);
    const [ey, em] = [+end.slice(0, 4), +end.slice(5, 7)];
    const months = [];
    for (let i = 5; i >= 0; i--) {
      const dt = new Date(Date.UTC(ey, em - 1 - i, 1));
      months.push(`${dt.getUTCFullYear()}-${String(dt.getUTCMonth() + 1).padStart(2, '0')}`);
    }
    const fromM = months[0] + '-01', toM = months[5] + '-01';
    const d = await posApi(`?action=fin-expenses&from=${fromM}&to=${toM}`, { method: 'GET' });
    const exp = d.expenses || [];
    const sums = new Map(months.map(m => [m, { fixed: 0, variable: 0 }]));
    for (const e of exp) {
      const m = (e.period_month || '').slice(0, 7);
      if (!sums.has(m)) continue;
      const o = sums.get(m); o[e.kind === 'fixed' ? 'fixed' : 'variable'] += (+e.amount || 0);
    }
    const RU = ['янв','фев','мар','апр','май','июн','июл','авг','сен','окт','ноя','дек'];
    const labels = months.map(m => `${RU[+m.slice(5, 7) - 1]} ${m.slice(2, 4)}`);
    host.innerHTML = `
      <div class="card card-pad">
        <div class="card-h-row"><h3>Сравнение расходов за 6 месяцев</h3></div>
        <div class="chart-box" style="height:280px"><canvas id="finCompare"></canvas></div>
      </div>
      <div class="card card-pad">
        <div class="tbl-wrap"><table class="tbl">
          <thead><tr><th>Месяц</th><th class="r">Постоянные</th><th class="r">Переменные</th><th class="r">Итого</th></tr></thead>
          <tbody>${months.map((m, i) => { const o = sums.get(m); const tot = o.fixed + o.variable; return `<tr>
            <td>${labels[i]}</td><td class="r">${money(o.fixed)}</td><td class="r">${money(o.variable)}</td>
            <td class="r strong neg">${money(tot)}</td></tr>`; }).join('')}</tbody>
        </table></div>
      </div>`;
    destroyChart('finCompare');
    state.charts['finCompare'] = new Chart($('finCompare'), {
      type: 'bar',
      data: { labels, datasets: [
        { label: 'Постоянные', data: months.map(m => Math.round(sums.get(m).fixed)), backgroundColor: '#f59e0b' },
        { label: 'Переменные', data: months.map(m => Math.round(sums.get(m).variable)), backgroundColor: '#10b981' },
      ] },
      options: { responsive: true, maintainAspectRatio: false, plugins: { legend: { position: 'bottom' } },
        scales: { x: { stacked: true }, y: { stacked: true, ticks: { callback: v => fmtInt(v) } } } },
    });
  } catch (e) {
    host.innerHTML = errBar('Не удалось построить сравнение: ' + (e.message || e));
  }
}

// ————— Под-вкладка: Выручка (ручной ввод) —————
async function finPaintRevenue() {
  const host = $('finSubBody');
  host.innerHTML = `<div class="loading">⏳ Загружаю выручку…</div>`;
  try {
    const month = (FIN._from || dushToday()).slice(0, 7) + '-01';
    const d = await posApi(`?action=fin-revenue&month=${month}`, { method: 'GET' });
    const rev = d.revenue || [];
    const byWh = new Map(rev.map(r => [r.warehouse_id || 'net', +r.amount || 0]));
    const netTotal = byWh.get('net') || 0;
    const rows = FIN.salons.map(s => {
      const v = byWh.get(s.warehouse_id) || 0;
      return `<tr>
        <td>${esc(s.name)}</td>
        <td class="r"><input type="number" class="fin-rev-inp" data-wh="${s.warehouse_id}" min="0" step="0.01" value="${v || ''}" placeholder="0.00"></td>
      </tr>`;
    }).join('');
    host.innerHTML = `
      <div class="card card-pad">
        <div class="card-h-row"><h3>Выручка за ${month.slice(0, 7)} (ручной ввод)</h3>
          <button class="btn btn-primary btn-sm" id="finRevSave">Сохранить выручку</button></div>
        <p class="muted" style="margin-bottom:14px">Введите грязную выручку по салонам за месяц. Используется ИИ-аналитиком для расчёта доли расходов.</p>
        <div class="tbl-wrap"><table class="tbl">
          <thead><tr><th>Салон</th><th class="r">Выручка (с.)</th></tr></thead>
          <tbody>
            <tr><td class="strong">Вся сеть (общая)</td>
              <td class="r"><input type="number" class="fin-rev-inp" data-wh="net" min="0" step="0.01" value="${netTotal || ''}" placeholder="0.00"></td></tr>
            ${rows}
          </tbody>
        </table></div>
        <div id="finRevMsg" style="margin-top:12px"></div>
      </div>`;
    $('finRevSave').addEventListener('click', async () => {
      const msg = $('finRevMsg');
      msg.innerHTML = `<div class="muted">Сохраняю…</div>`;
      try {
        const inputs = Array.from(host.querySelectorAll('.fin-rev-inp'));
        for (const inp of inputs) {
          const val = inp.value.trim();
          if (val === '') continue;
          const amount = parseFloat(val);
          if (!(amount >= 0)) continue;
          const wh = inp.dataset.wh;
          await posApi('?action=fin-revenue-set', { method: 'POST', body: JSON.stringify({
            period_month: month, warehouse_id: wh === 'net' ? null : wh, amount,
          }) });
        }
        msg.innerHTML = `<div class="fin-ok">✓ Выручка сохранена</div>`;
      } catch (e) { msg.innerHTML = errBar('Не удалось сохранить: ' + (e.message || e)); }
    });
  } catch (e) {
    host.innerHTML = errBar('Не удалось загрузить выручку: ' + (e.message || e));
  }
}

// ————— Экспорт CSV —————
function finExportCsv() {
  const arr = finFiltered();
  if (!arr.length) { alert('Нет данных для экспорта'); return; }
  const head = ['Дата','Тип','Категория','Название','Магазин','Сумма','Комментарий'];
  const lines = [head.join(';')];
  for (const e of arr) {
    const row = [
      finExpDate(e).slice(0, 10),
      finKindLabel(e.kind),
      (finCatName(e.category_id) || ''),
      (e.title || ''),
      (e.warehouse_id ? finSalonName(e.warehouse_id) : finOwnerLabel(e.owner_type)),
      (+e.amount || 0).toFixed(2),
      (e.comment || ''),
    ].map(x => `"${String(x).replace(/"/g, '""')}"`);
    lines.push(row.join(';'));
  }
  const blob = new Blob(['\ufeff' + lines.join('\n')], { type: 'text/csv;charset=utf-8' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url; a.download = `rashody_${(FIN._from||'').slice(0,7)}.csv`;
  document.body.appendChild(a); a.click(); document.body.removeChild(a);
  URL.revokeObjectURL(url);
}



// ══════════════════════════════════════════════════════════
//  РАСШИРЕНИЕ «Выручка-Расходы»: Обзор · Поставщики · Сотрудники
// ══════════════════════════════════════════════════════════

const FIN_COUNTRY_LABEL = { turkey: '🇹🇷 Турция', china: '🇨🇳 Китай', uzbekistan: '🇺🇿 Узбекистан', tajikistan: '🇹🇯 Таджикистан' };
const FIN_SALARY_LABEL = {
  fixed_per_salon: 'Оклад по салонам',
  percent_network: '% от выручки сети',
  salary_plus_personal_percent: 'Оклад + % личных продаж',
};

// ————————————————————————————————————————————————
//  ОБЗОР: 5 KPI + Финансовый результат + Выручка по магазинам + график
// ————————————————————————————————————————————————
async function finPaintOverview() {
  const host = $('finSubBody');
  host.innerHTML = `<div class="loading">⏳ Считаю финансовый результат…</div>`;
  try {
    const from = FIN._from, to = FIN._to;
    const d = await posApi(`?action=fin-profit&from=${from}&to=${to}`, { method: 'GET' });
    FIN.profit = d;
    const s = d.summary;
    const bySalon = d.by_salon || [];
    const prorated = d.range && d.range.prorated;

    // 5 KPI: Выручка / Постоянные / Переменные / Зарплаты / Чистая прибыль
    const profitTone = s.net_profit >= 0 ? 'green' : 'red';
    const kpiRow = `
      <div class="kpis" style="grid-template-columns:repeat(auto-fit,minmax(180px,1fr));margin-bottom:14px">
        ${kpi('💰','Выручка (из 1С)', money(s.revenue),'green', 'чистая, продажи − возвраты')}
        ${kpi('📌','Постоянные расходы', money(s.expenses_fixed),'amber', 'аренда, оклады и т.д.')}
        ${kpi('🧾','Переменные расходы', money(s.expenses_variable),'amber', 'закуп, логистика и т.д.')}
        ${kpi('👥','Зарплаты', money(s.payroll_total),'blue', `оклад ${fmtInt(s.payroll_oklad)} + % ${fmtInt(s.payroll_percent)}`)}
        ${kpi(s.net_profit>=0?'📈':'📉','Чистая прибыль', money(s.net_profit), profitTone, s.net_profit>=0?'прибыль за период':'убыток за период')}
      </div>`;

    // Финансовый результат — прозрачная расшифровка формулы
    const line = (label, val, sign, strong) => {
      const cls = sign < 0 ? 'fin-fr-minus' : (sign > 0 ? 'fin-fr-plus' : '');
      const pref = sign < 0 ? '− ' : (sign > 0 ? '' : '');
      return `<div class="fin-fr-row ${strong ? 'fin-fr-strong' : ''}">
        <span class="fin-fr-lbl">${label}</span>
        <span class="fin-fr-val ${cls}">${pref}${money(Math.abs(val))}</span></div>`;
    };
    const frBlock = `
      <div class="card card-pad" style="margin-bottom:14px">
        <h3 class="fin-h3">Финансовый результат ${prorated ? '<span class="fin-note">(пропорц. дням периода)</span>' : ''}</h3>
        <div class="fin-fr">
          ${line('Выручка (net из 1С)', s.revenue, 1, false)}
          ${line(`Себестоимость товара (${Math.round(s.cogs_rate*100)}%)`, s.cogs, -1, false)}
          ${line('Постоянные расходы', s.expenses_fixed, -1, false)}
          ${line('Переменные расходы', s.expenses_variable, -1, false)}
          ${line('Выплаты поставщикам', s.supplier_payments, -1, false)}
          ${line('Зарплаты (оклад + %)', s.payroll_total, -1, false)}
          <div class="fin-fr-sep"></div>
          ${line('ЧИСТАЯ ПРИБЫЛЬ', s.net_profit, s.net_profit>=0?1:-1, true)}
        </div>
        <p class="fin-note" style="margin-top:8px">Закупки у поставщиков в долг прибыль не уменьшают — учитываются только фактические выплаты (кассовый метод). Справочно за период добавлено долга: <b>${money(s.supplier_new_debt)}</b>.</p>
      </div>`;

    // Выручка по магазинам
    const maxRev = Math.max(1, ...bySalon.map(r => r.revenue));
    const salonRows = bySalon.map(r => `
      <tr>
        <td>${esc(r.name)}</td>
        <td class="num">${money(r.revenue)}</td>
        <td class="num">${money(r.expenses)}</td>
        <td class="num"><b class="${r.profit>=0?'fin-fr-plus':'fin-fr-minus'}">${money(r.profit)}</b></td>
        <td style="width:120px"><div class="fin-bar-bg"><div class="fin-bar-fill" style="width:${Math.round(r.revenue/maxRev*100)}%"></div></div></td>
      </tr>`).join('');
    const salonBlock = `
      <div class="card card-pad" style="margin-bottom:14px">
        <h3 class="fin-h3">Выручка по магазинам</h3>
        <table class="tbl fin-tbl">
          <thead><tr><th>Магазин</th><th class="num">Выручка</th><th class="num">Постоянные расходы</th><th class="num">Прибыль</th><th></th></tr></thead>
          <tbody>${salonRows || '<tr><td colspan="5" class="muted">Нет данных</td></tr>'}</tbody>
        </table>
        <p class="fin-note">Прибыль салона = выручка − (собственные постоянные + доля общих постоянных пропорц. выручке). Без себестоимости, зарплат-% и выплат поставщикам — они считаются по сети.</p>
      </div>`;

    // График динамики: выручка / расходы / чистая прибыль по дням
    const trendBlock = `
      <div class="card card-pad">
        <h3 class="fin-h3">Динамика за период</h3>
        <div style="position:relative;height:280px"><canvas id="finOverviewTrend"></canvas></div>
      </div>`;

    host.innerHTML = kpiRow + frBlock + salonBlock + trendBlock;
    finDrawOverviewTrend('finOverviewTrend', from, to);
  } catch (e) {
    host.innerHTML = errBar('Не удалось посчитать обзор: ' + (e.message || e));
  }
}

// График: 3 линии (выручка/расходы/чистая прибыль) по дням периода.
async function finDrawOverviewTrend(canvasId, from, to) {
  const el = $(canvasId); if (!el) return;
  destroyChart(canvasId);
  try {
    // Выручка по дням из 1С (через отдельный публичный проект — читаем на бэке нельзя по дням, берём агрегат).
    // Простая версия: расходы по дням (shop_expenses.expense_date) + выручка распределяем равномерно.
    const s = FIN.profit ? FIN.profit.summary : null;
    const days = [];
    for (let t = new Date(from + 'T00:00:00Z'); t.toISOString().slice(0,10) <= to; t = new Date(t.getTime() + 86400000)) days.push(t.toISOString().slice(0,10));
    if (!days.length) return;
    // расходы по дням
    const byDayExp = new Map();
    for (const e of (FIN.expenses || [])) {
      const dd = (e.expense_date || (e.period_month||'')).slice(0,10);
      if (dd) byDayExp.set(dd, (byDayExp.get(dd)||0) + (+e.amount||0));
    }
    const n = days.length;
    const revPerDay = s ? s.revenue / n : 0;
    const cogsPerDay = s ? s.cogs / n : 0;
    const supPerDay = s ? s.supplier_payments / n : 0;
    const payrollPerDay = s ? s.payroll_total / n : 0;
    const revArr = days.map(() => Math.round(revPerDay));
    const expArr = days.map(dd => Math.round((byDayExp.get(dd)||0) + cogsPerDay + supPerDay + payrollPerDay));
    const profitArr = days.map((dd,i) => revArr[i] - expArr[i]);
    state.charts[canvasId] = new Chart(el, {
      type: 'line',
      data: {
        labels: days.map(d => d.slice(5)),
        datasets: [
          { label: 'Выручка', data: revArr, borderColor: '#10b981', backgroundColor: 'rgba(16,185,129,.10)', fill: true, tension: .3, pointRadius: 2 },
          { label: 'Расходы', data: expArr, borderColor: '#e11d48', backgroundColor: 'rgba(225,29,72,.06)', fill: false, tension: .3, pointRadius: 2 },
          { label: 'Чистая прибыль', data: profitArr, borderColor: '#3b82f6', backgroundColor: 'rgba(59,130,246,.06)', fill: false, tension: .3, pointRadius: 2, borderDash: [5,3] },
        ],
      },
      options: { responsive: true, maintainAspectRatio: false,
        plugins: { legend: { display: true, position: 'top' }, tooltip: { callbacks: { label: c => `${c.dataset.label}: ${fmtNum(c.parsed.y)} с.` } } },
        scales: { y: { ticks: { callback: v => fmtInt(v) } } } },
    });
  } catch (e) { /* график необязателен */ }
}

// ————————————————————————————————————————————————
//  ДОЛГИ ПОСТАВЩИКАМ
// ————————————————————————————————————————————————
async function finPaintSuppliers() {
  const host = $('finSubBody');
  host.innerHTML = `<div class="loading">⏳ Загружаю поставщиков…</div>`;
  try {
    const [supR, fxR] = await Promise.all([
      posApi('?action=fin-suppliers&all=1', { method: 'GET' }),
      posApi('?action=fin-fx', { method: 'GET' }),
    ]);
    FIN.suppliers = supR.suppliers || [];
    FIN.fx = fxR.rates || {};

    const sups = FIN.suppliers;
    const totalDebt = sups.reduce((s, x) => s + (+x.debt_tjs || 0), 0);
    const activeCnt = sups.filter(x => x.is_active).length;
    const usd = FIN.fx.USD, cny = FIN.fx.CNY;

    const fxLine = `
      <div class="fin-fx-bar">
        <span class="fin-fx-item">💵 USD: <b>${usd ? fmtNum(usd.rate) : '—'}</b> с. <span class="fin-note">${usd ? usd.date : ''}</span></span>
        <span class="fin-fx-item">💴 CNY: <b>${cny ? fmtNum(cny.rate) : '—'}</b> с. <span class="fin-note">${cny ? cny.date : ''}</span></span>
        <button class="btn btn-ghost btn-sm" id="finFxRefresh">↻ Обновить курс (Алиф)</button>
        <button class="btn btn-ghost btn-sm" id="finFxManual">✎ Ввести вручную</button>
      </div>`;

    const rows = sups.map(x => {
      const debtCls = x.debt_tjs > 0.5 ? 'fin-debt-yes' : (x.debt_tjs < -0.5 ? 'fin-debt-over' : 'fin-debt-zero');
      const foreign = x.currency !== 'TJS' && Math.abs(x.debt_foreign) > 0.01 ? ` <span class="fin-note">(${fmtNum(x.debt_foreign)} ${x.currency})</span>` : '';
      return `<tr data-sup="${x.id}">
        <td>${x.photo_url ? `<img class="fin-sup-ph" src="${esc(x.photo_url)}" alt="">` : '<span class="fin-sup-ph fin-sup-ph-empty">🏷</span>'}</td>
        <td><b>${esc(x.name)}</b>${x.is_active ? '' : ' <span class="badge off">архив</span>'}</td>
        <td>${FIN_COUNTRY_LABEL[x.country] || x.country}</td>
        <td>${x.currency}</td>
        <td class="num"><b class="${debtCls}">${money(x.debt_tjs)}</b>${foreign}</td>
        <td class="fin-actions">
          <button class="btn btn-ghost btn-xs fin-sup-ops" data-id="${x.id}">Операции</button>
          <button class="btn btn-ghost btn-xs fin-sup-pay" data-id="${x.id}">＋ Выплата</button>
          <button class="btn btn-ghost btn-xs fin-sup-buy" data-id="${x.id}">＋ Закуп</button>
          <button class="btn btn-ghost btn-xs fin-sup-edit" data-id="${x.id}">✎</button>
        </td>
      </tr>`;
    }).join('');

    host.innerHTML = `
      ${fxLine}
      <div class="kpis" style="grid-template-columns:repeat(auto-fit,minmax(200px,1fr));margin-bottom:14px">
        ${kpi('🏷','Всего поставщиков', String(sups.length), 'blue', `${activeCnt} активных`)}
        ${kpi('💳','Общий долг', money(totalDebt), totalDebt>0?'red':'green', 'сумма долгов в сомони')}
      </div>
      <div class="card card-pad">
        <div class="fin-sec-head">
          <h3 class="fin-h3">Поставщики и долги</h3>
          <button class="btn btn-primary btn-sm" id="finSupAdd">＋ Поставщик</button>
        </div>
        <table class="tbl fin-tbl">
          <thead><tr><th></th><th>Поставщик</th><th>Страна</th><th>Валюта</th><th class="num">Долг</th><th></th></tr></thead>
          <tbody>${rows || '<tr><td colspan="6" class="muted">Нет поставщиков</td></tr>'}</tbody>
        </table>
        <p class="fin-note">Долг = сумма закупок − сумма выплат. Красный — мы должны; зелёный — переплата/аванс.</p>
      </div>
      <div id="finSupModal"></div>`;

    // события
    $('finSupAdd').addEventListener('click', () => finSupForm(null));
    $('finFxRefresh').addEventListener('click', finFxRefresh);
    $('finFxManual').addEventListener('click', finFxManualForm);
    host.querySelectorAll('.fin-sup-edit').forEach(b => b.addEventListener('click', () => finSupForm(b.dataset.id)));
    host.querySelectorAll('.fin-sup-ops').forEach(b => b.addEventListener('click', () => finSupOps(b.dataset.id)));
    host.querySelectorAll('.fin-sup-pay').forEach(b => b.addEventListener('click', () => finSupOpForm(b.dataset.id, 'payment')));
    host.querySelectorAll('.fin-sup-buy').forEach(b => b.addEventListener('click', () => finSupOpForm(b.dataset.id, 'purchase')));
  } catch (e) {
    host.innerHTML = errBar('Не удалось загрузить поставщиков: ' + (e.message || e));
  }
}

function finSupById(id) { return (FIN.suppliers || []).find(x => x.id === id); }

// модалка: создание/редактирование поставщика
function finSupForm(id) {
  const sup = id ? finSupById(id) : null;
  const m = $('finSupModal');
  const cOpts = Object.keys(FIN_COUNTRY_LABEL).map(c => `<option value="${c}" ${sup && sup.country===c?'selected':''}>${FIN_COUNTRY_LABEL[c]}</option>`).join('');
  m.innerHTML = `
    <div class="fin-modal-bg" id="finSupModalBg">
      <div class="fin-modal">
        <div class="fin-modal-head"><h3>${sup ? 'Редактировать поставщика' : 'Новый поставщик'}</h3><button class="fin-modal-x" id="finSupClose">✕</button></div>
        <div class="fin-modal-body">
          <label class="fld"><span>Название</span><input id="fsName" value="${sup ? esc(sup.name) : ''}" placeholder="Напр. Forelli"></label>
          <label class="fld"><span>Страна</span><select id="fsCountry">${cOpts}</select></label>
          <label class="fld"><span>Валюта</span><select id="fsCur">
            <option value="USD" ${sup&&sup.currency==='USD'?'selected':''}>USD</option>
            <option value="CNY" ${sup&&sup.currency==='CNY'?'selected':''}>CNY</option>
            <option value="TJS" ${sup&&sup.currency==='TJS'?'selected':''}>TJS (сомони)</option>
          </select></label>
          <label class="fld"><span>Фото (URL, необязательно)</span><input id="fsPhoto" value="${sup && sup.photo_url ? esc(sup.photo_url) : ''}" placeholder="https://…"></label>
          ${sup ? '' : `<label class="fld"><span>Начальный долг (в валюте, необязательно)</span><input id="fsDebt" type="number" step="0.01" placeholder="0"></label>`}
          ${sup ? `<label class="fld fld-check"><input type="checkbox" id="fsActive" ${sup.is_active?'checked':''}> Активен</label>` : ''}
        </div>
        <div class="fin-modal-foot">
          ${sup ? `<button class="btn btn-ghost btn-sm fin-btn-danger" id="fsDelete">Удалить</button>` : '<span></span>'}
          <div><button class="btn btn-ghost btn-sm" id="fsCancel">Отмена</button>
          <button class="btn btn-primary btn-sm" id="fsSave">Сохранить</button></div>
        </div>
        <div id="fsMsg"></div>
      </div>
    </div>`;
  const close = () => { m.innerHTML = ''; };
  $('finSupClose').addEventListener('click', close);
  $('fsCancel').addEventListener('click', close);
  $('finSupModalBg').addEventListener('click', e => { if (e.target.id === 'finSupModalBg') close(); });
  // при смене страны — подставим валюту по умолчанию
  $('fsCountry').addEventListener('change', () => {
    const def = { turkey:'USD', china:'CNY', uzbekistan:'TJS', tajikistan:'TJS' }[$('fsCountry').value];
    if (def) $('fsCur').value = def;
  });
  if ($('fsDelete')) $('fsDelete').addEventListener('click', async () => {
    if (!confirm('Удалить поставщика вместе со всеми операциями?')) return;
    try { await posApi('?action=fin-supplier-delete', { method:'POST', body: JSON.stringify({ id }) }); close(); finPaintSuppliers(); }
    catch (e) { $('fsMsg').innerHTML = errBar(e.message||e); }
  });
  $('fsSave').addEventListener('click', async () => {
    const body = {
      name: $('fsName').value.trim(),
      country: $('fsCountry').value,
      currency: $('fsCur').value,
      photo_url: $('fsPhoto').value.trim() || null,
    };
    if (!body.name) { $('fsMsg').innerHTML = errBar('Укажите название'); return; }
    try {
      if (sup) {
        body.id = id; body.is_active = $('fsActive').checked;
        await posApi('?action=fin-supplier-update', { method:'POST', body: JSON.stringify(body) });
      } else {
        const dv = parseFloat($('fsDebt') ? $('fsDebt').value : '');
        if (dv > 0) body.initial_debt = dv;
        await posApi('?action=fin-supplier-create', { method:'POST', body: JSON.stringify(body) });
      }
      close(); finPaintSuppliers();
    } catch (e) { $('fsMsg').innerHTML = errBar(e.message||e); }
  });
}

// модалка: операция (закуп/выплата)
function finSupOpForm(id, type) {
  const sup = finSupById(id); if (!sup) return;
  const m = $('finSupModal');
  const isPay = type === 'payment';
  const foreignCur = sup.currency;
  const canPayTjs = foreignCur !== 'TJS' && isPay;
  const rate = FIN.fx && FIN.fx[foreignCur] ? FIN.fx[foreignCur].rate : '';
  m.innerHTML = `
    <div class="fin-modal-bg" id="finSupOpBg">
      <div class="fin-modal">
        <div class="fin-modal-head"><h3>${isPay?'Выплата':'Закуп'} — ${esc(sup.name)}</h3><button class="fin-modal-x" id="finOpClose">✕</button></div>
        <div class="fin-modal-body">
          ${canPayTjs ? `<label class="fld fld-check"><input type="checkbox" id="foTjs"> Выплата в сомони (TJS)</label>` : ''}
          <label class="fld"><span>Сумма <span id="foCurLbl">(${foreignCur})</span></span><input id="foAmount" type="number" step="0.01" placeholder="0"></label>
          <div id="foRateWrap" style="display:${foreignCur!=='TJS'?'block':'none'}"><label class="fld"><span>Курс ${foreignCur}→TJS</span><input id="foRate" type="number" step="0.0001" value="${rate}"></label></div>
          <label class="fld"><span>Дата</span><input id="foDate" type="date" value="${dushToday()}"></label>
          <label class="fld"><span>Комментарий</span><input id="foComment" placeholder="необязательно"></label>
        </div>
        <div class="fin-modal-foot"><span></span><div>
          <button class="btn btn-ghost btn-sm" id="foCancel">Отмена</button>
          <button class="btn btn-primary btn-sm" id="foSave">Сохранить</button></div></div>
        <div id="foMsg"></div>
      </div>
    </div>`;
  const close = () => { m.innerHTML = ''; };
  $('finOpClose').addEventListener('click', close);
  $('foCancel').addEventListener('click', close);
  $('finSupOpBg').addEventListener('click', e => { if (e.target.id === 'finSupOpBg') close(); });
  if ($('foTjs')) $('foTjs').addEventListener('change', () => {
    const tjs = $('foTjs').checked;
    $('foCurLbl').textContent = tjs ? '(сомони)' : `(${foreignCur})`;
    $('foRateWrap').style.display = tjs ? 'block' : (foreignCur!=='TJS'?'block':'none');
  });
  $('foSave').addEventListener('click', async () => {
    const amount = parseFloat($('foAmount').value);
    if (!(amount >= 0)) { $('foMsg').innerHTML = errBar('Укажите сумму'); return; }
    const body = { supplier_id: id, type, amount_foreign: amount, operation_date: $('foDate').value, comment: $('foComment').value.trim() || null };
    if ($('foTjs') && $('foTjs').checked) body.payment_currency = 'TJS';
    if ($('foRate') && $('foRate').value) body.fx_rate = parseFloat($('foRate').value);
    try { await posApi('?action=fin-supplier-op-create', { method:'POST', body: JSON.stringify(body) }); close(); finPaintSuppliers(); }
    catch (e) { $('foMsg').innerHTML = errBar(e.message||e); }
  });
}

// модалка: история операций поставщика
async function finSupOps(id) {
  const sup = finSupById(id); if (!sup) return;
  const m = $('finSupModal');
  m.innerHTML = `<div class="fin-modal-bg" id="finOpsBg"><div class="fin-modal fin-modal-wide"><div class="fin-modal-head"><h3>Операции — ${esc(sup.name)}</h3><button class="fin-modal-x" id="finOpsClose">✕</button></div><div class="fin-modal-body"><div class="loading">⏳ Загружаю…</div></div></div></div>`;
  const close = () => { m.innerHTML = ''; };
  $('finOpsClose').addEventListener('click', close);
  $('finOpsBg').addEventListener('click', e => { if (e.target.id === 'finOpsBg') close(); });
  try {
    const d = await posApi(`?action=fin-supplier-ops&supplier_id=${id}`, { method:'GET' });
    const ops = d.operations || [];
    const rows = ops.map(o => `<tr>
      <td>${(o.operation_date||'').slice(0,10)}</td>
      <td>${o.type==='payment'?'<span class="fin-fr-minus">Выплата</span>':'<span class="fin-fr-plus">Закуп</span>'}</td>
      <td class="num">${fmtNum(o.amount_foreign)} ${sup.currency}</td>
      <td class="num">${money(o.amount_tjs)}</td>
      <td class="fin-note">${esc(o.comment||'')}</td>
      <td><button class="btn btn-ghost btn-xs fin-op-del" data-id="${o.id}">✕</button></td>
    </tr>`).join('');
    m.querySelector('.fin-modal-body').innerHTML = `
      <table class="tbl fin-tbl"><thead><tr><th>Дата</th><th>Тип</th><th class="num">Валюта</th><th class="num">Сомони</th><th>Комментарий</th><th></th></tr></thead>
      <tbody>${rows || '<tr><td colspan="6" class="muted">Нет операций</td></tr>'}</tbody></table>`;
    m.querySelectorAll('.fin-op-del').forEach(b => b.addEventListener('click', async () => {
      if (!confirm('Удалить операцию?')) return;
      try { await posApi('?action=fin-supplier-op-delete', { method:'POST', body: JSON.stringify({ id: b.dataset.id }) }); finSupOps(id); FIN.suppliers=null; }
      catch (e) { alert(e.message||e); }
    }));
  } catch (e) { m.querySelector('.fin-modal-body').innerHTML = errBar(e.message||e); }
}

async function finFxRefresh() {
  const btn = $('finFxRefresh'); if (btn) { btn.disabled = true; btn.textContent = '↻ Обновляю…'; }
  try { await posApi('?action=fin-fx-refresh', { method:'POST', body: '{}' }); finPaintSuppliers(); }
  catch (e) { alert('Не удалось обновить курс: ' + (e.message||e)); if (btn){btn.disabled=false;btn.textContent='↻ Обновить курс (Алиф)';} }
}

function finFxManualForm() {
  const m = $('finSupModal');
  const usd = FIN.fx && FIN.fx.USD ? FIN.fx.USD.rate : '';
  const cny = FIN.fx && FIN.fx.CNY ? FIN.fx.CNY.rate : '';
  m.innerHTML = `<div class="fin-modal-bg" id="finFxBg"><div class="fin-modal"><div class="fin-modal-head"><h3>Курс валют (вручную)</h3><button class="fin-modal-x" id="finFxClose">✕</button></div>
    <div class="fin-modal-body">
      <label class="fld"><span>USD → TJS</span><input id="fxUsd" type="number" step="0.0001" value="${usd}"></label>
      <label class="fld"><span>CNY → TJS</span><input id="fxCny" type="number" step="0.0001" value="${cny}"></label>
    </div>
    <div class="fin-modal-foot"><span></span><div><button class="btn btn-ghost btn-sm" id="fxCancel">Отмена</button><button class="btn btn-primary btn-sm" id="fxSave">Сохранить</button></div></div>
    <div id="fxMsg"></div></div></div>`;
  const close = () => { m.innerHTML = ''; };
  $('finFxClose').addEventListener('click', close);
  $('fxCancel').addEventListener('click', close);
  $('finFxBg').addEventListener('click', e => { if (e.target.id === 'finFxBg') close(); });
  $('fxSave').addEventListener('click', async () => {
    const body = {};
    if ($('fxUsd').value) body.USD = parseFloat($('fxUsd').value);
    if ($('fxCny').value) body.CNY = parseFloat($('fxCny').value);
    try { await posApi('?action=fin-fx-set', { method:'POST', body: JSON.stringify(body) }); close(); finPaintSuppliers(); }
    catch (e) { $('fxMsg').innerHTML = errBar(e.message||e); }
  });
}

// ————————————————————————————————————————————————
//  СОТРУДНИКИ И ЗАРПЛАТЫ
// ————————————————————————————————————————————————
async function finPaintEmployees() {
  const host = $('finSubBody');
  host.innerHTML = `<div class="loading">⏳ Загружаю сотрудников…</div>`;
  try {
    const d = await posApi('?action=fin-employees', { method:'GET' });
    FIN.employees = d.employees || [];
    const emps = FIN.employees;
    const active = emps.filter(e => e.status !== 'dismissed');
    const okladTotal = active.reduce((s, e) => s + (e.salaries||[]).reduce((a,x)=>a+(+x.amount||0),0), 0);

    const rows = emps.map(e => {
      const oklad = (e.salaries||[]).reduce((a,x)=>a+(+x.amount||0),0);
      const salByShop = (e.salaries||[]).map(x => `${x.warehouse_id?finSalonName(x.warehouse_id):'Офис/сеть'}: ${fmtInt(x.amount)}`).join(', ');
      const dism = e.status === 'dismissed';
      return `<tr class="${dism?'fin-emp-dism':''}">
        <td><b>${esc(e.full_name)}</b>${dism?' <span class="badge off">уволен</span>':''}<div class="fin-note">${esc(e.position||'')}</div></td>
        <td>${FIN_SALARY_LABEL[e.salary_type]||e.salary_type}${e.percent_rate?` <b>${fmtNum(e.percent_rate)}%</b>`:''}</td>
        <td class="num"><b>${fmtInt(oklad)}</b> <span class="cur">с.</span><div class="fin-note">${esc(salByShop)}</div></td>
        <td class="fin-actions">
          <button class="btn btn-ghost btn-xs fin-emp-sal" data-id="${e.id}">Оклады</button>
          <button class="btn btn-ghost btn-xs fin-emp-edit" data-id="${e.id}">✎</button>
        </td>
      </tr>`;
    }).join('');

    host.innerHTML = `
      <div class="kpis" style="grid-template-columns:repeat(auto-fit,minmax(200px,1fr));margin-bottom:14px">
        ${kpi('👥','Сотрудников', String(active.length), 'blue', `${emps.length} всего с уволенными`)}
        ${kpi('💵','Фонд окладов', money(okladTotal), 'amber', 'сумма окладов в месяц')}
      </div>
      <div class="card card-pad">
        <div class="fin-sec-head"><h3 class="fin-h3">Сотрудники</h3><button class="btn btn-primary btn-sm" id="finEmpAdd">＋ Сотрудник</button></div>
        <table class="tbl fin-tbl">
          <thead><tr><th>Сотрудник</th><th>Тип оплаты</th><th class="num">Оклад / мес</th><th></th></tr></thead>
          <tbody>${rows || '<tr><td colspan="4" class="muted">Нет сотрудников</td></tr>'}</tbody>
        </table>
        <p class="fin-note">Зарплата = оклад (по салонам) + % от продаж. «% от выручки сети» — от общей net-выручки; «Оклад + % личных продаж» — от личных продаж сотрудника.</p>
      </div>
      <div id="finEmpModal"></div>`;

    $('finEmpAdd').addEventListener('click', () => finEmpForm(null));
    host.querySelectorAll('.fin-emp-edit').forEach(b => b.addEventListener('click', () => finEmpForm(b.dataset.id)));
    host.querySelectorAll('.fin-emp-sal').forEach(b => b.addEventListener('click', () => finEmpSalaries(b.dataset.id)));
  } catch (e) {
    host.innerHTML = errBar('Не удалось загрузить сотрудников: ' + (e.message || e));
  }
}

function finEmpById(id) { return (FIN.employees || []).find(e => e.id === id); }

function finEmpForm(id) {
  const emp = id ? finEmpById(id) : null;
  const m = $('finEmpModal');
  const stOpts = Object.keys(FIN_SALARY_LABEL).map(k => `<option value="${k}" ${emp&&emp.salary_type===k?'selected':''}>${FIN_SALARY_LABEL[k]}</option>`).join('');
  m.innerHTML = `
    <div class="fin-modal-bg" id="finEmpBg"><div class="fin-modal">
      <div class="fin-modal-head"><h3>${emp?'Редактировать':'Новый сотрудник'}</h3><button class="fin-modal-x" id="finEmpClose">✕</button></div>
      <div class="fin-modal-body">
        <label class="fld"><span>ФИО</span><input id="feName" value="${emp?esc(emp.full_name):''}"></label>
        <label class="fld"><span>Должность</span><input id="fePos" value="${emp&&emp.position?esc(emp.position):''}"></label>
        <label class="fld"><span>Тип оплаты</span><select id="feType">${stOpts}</select></label>
        <label class="fld"><span>% от продаж (если применимо)</span><input id="feRate" type="number" step="0.1" value="${emp&&emp.percent_rate?emp.percent_rate:''}" placeholder="0"></label>
        <label class="fld"><span>Кошелёк / карта</span><input id="feWallet" value="${emp&&emp.wallet?esc(emp.wallet):''}"></label>
        <label class="fld"><span>Телефон</span><input id="fePhone" value="${emp&&emp.phone?esc(emp.phone):''}"></label>
        ${emp?`<label class="fld"><span>Статус</span><select id="feStatus"><option value="active" ${emp.status!=='dismissed'?'selected':''}>Активен</option><option value="dismissed" ${emp.status==='dismissed'?'selected':''}>Уволен</option></select></label>`:''}
      </div>
      <div class="fin-modal-foot">
        ${emp?`<button class="btn btn-ghost btn-sm fin-btn-danger" id="feDelete">Удалить</button>`:'<span></span>'}
        <div><button class="btn btn-ghost btn-sm" id="feCancel">Отмена</button><button class="btn btn-primary btn-sm" id="feSave">Сохранить</button></div>
      </div><div id="feMsg"></div>
    </div></div>`;
  const close = () => { m.innerHTML = ''; };
  $('finEmpClose').addEventListener('click', close);
  $('feCancel').addEventListener('click', close);
  $('finEmpBg').addEventListener('click', e => { if (e.target.id === 'finEmpBg') close(); });
  if ($('feDelete')) $('feDelete').addEventListener('click', async () => {
    if (!confirm('Удалить сотрудника?')) return;
    try { await posApi('?action=fin-employee-delete', { method:'POST', body: JSON.stringify({ id }) }); close(); finPaintEmployees(); }
    catch (e) { $('feMsg').innerHTML = errBar(e.message||e); }
  });
  $('feSave').addEventListener('click', async () => {
    const body = {
      full_name: $('feName').value.trim(), position: $('fePos').value.trim() || null,
      salary_type: $('feType').value, percent_rate: parseFloat($('feRate').value) || 0,
      wallet: $('feWallet').value.trim() || null, phone: $('fePhone').value.trim() || null,
    };
    if (!body.full_name) { $('feMsg').innerHTML = errBar('Укажите ФИО'); return; }
    try {
      if (emp) { body.id = id; body.status = $('feStatus').value; await posApi('?action=fin-employee-update', { method:'POST', body: JSON.stringify(body) }); }
      else await posApi('?action=fin-employee-create', { method:'POST', body: JSON.stringify(body) });
      close(); finPaintEmployees();
    } catch (e) { $('feMsg').innerHTML = errBar(e.message||e); }
  });
}

// модалка: оклады по салонам
function finEmpSalaries(id) {
  const emp = finEmpById(id); if (!emp) return;
  const m = $('finEmpModal');
  const salMap = {}; for (const s of (emp.salaries||[])) salMap[s.warehouse_id||'net'] = s.amount;
  const salonRows = FIN.salons.map(s => `
    <label class="fld fld-inline"><span>${esc(s.name)}</span><input class="fin-sal-inp" data-wh="${s.warehouse_id}" type="number" step="0.01" value="${salMap[s.warehouse_id]||''}" placeholder="0"></label>`).join('');
  m.innerHTML = `
    <div class="fin-modal-bg" id="finSalBg"><div class="fin-modal">
      <div class="fin-modal-head"><h3>Оклады — ${esc(emp.full_name)}</h3><button class="fin-modal-x" id="finSalClose">✕</button></div>
      <div class="fin-modal-body">
        <p class="fin-note">Оклад по каждому салону, где работает сотрудник. Пусто/0 — оклада нет.</p>
        ${salonRows}
        <label class="fld fld-inline"><span>Офис / сеть (без салона)</span><input class="fin-sal-inp" data-wh="net" type="number" step="0.01" value="${salMap['net']||''}" placeholder="0"></label>
      </div>
      <div class="fin-modal-foot"><span></span><div><button class="btn btn-ghost btn-sm" id="fsalCancel">Отмена</button><button class="btn btn-primary btn-sm" id="fsalSave">Сохранить</button></div></div>
      <div id="fsalMsg"></div>
    </div></div>`;
  const close = () => { m.innerHTML = ''; };
  $('finSalClose').addEventListener('click', close);
  $('fsalCancel').addEventListener('click', close);
  $('finSalBg').addEventListener('click', e => { if (e.target.id === 'finSalBg') close(); });
  $('fsalSave').addEventListener('click', async () => {
    const msg = $('fsalMsg'); msg.innerHTML = '<div class="muted">Сохраняю…</div>';
    try {
      for (const inp of m.querySelectorAll('.fin-sal-inp')) {
        const wh = inp.dataset.wh;
        const raw = inp.value.trim();
        const amount = raw === '' ? 0 : parseFloat(raw);
        if (!(amount >= 0)) continue;
        await posApi('?action=fin-employee-salary-set', { method:'POST', body: JSON.stringify({ employee_id: id, warehouse_id: wh === 'net' ? null : wh, amount }) });
      }
      close(); finPaintEmployees();
    } catch (e) { msg.innerHTML = errBar(e.message||e); }
  });
}


// ══════════════════════════════════════════════════════════
//  ПОСТУПЛЕНИЕ ТОВАРА — независимый раздел (без 1С)
//  Данные: suppliers / receiving_docs / receiving_items → products/variants/stock_units
// ══════════════════════════════════════════════════════════

// Локальное состояние документа поступления (черновик в памяти + localStorage).
const recv = {
  loaded: false,
  tab: 'new',             // 'новый документ' | 'docs' | 'suppliers'
  suppliers: [],
  warehouses: [],
  docId: null,           // id сохранённого черновика (если есть)
  status: 'draft',
  supplierId: '',
  warehouseId: '',
  docNumber: '',
  docDate: new Date().toISOString().slice(0, 10),
  items: [],             // [{uid, product_id, product_name, sku, category, sizeGrid:[], sizes:{}, cost_price, transport_cost, fixed_cost_pct, variable_cost_pct, doctor_pct, seller_pct, profit_pct}]
  activeCalcUid: null,   // какая позиция открыта в калькуляторе справа
  searchResults: [],
  docsList: null,        // кэш списка документов
  suppliersAll: null,    // кэш всех поставщиков (вкладка управления)
  docMode: 'new',        // 'new' | 'view' — открыт ли существующий документ
};

const RECV_LS_KEY = 'rmk.recv.draft.v1';

function recvNewUid() { return 'r' + Math.random().toString(36).slice(2, 9); }

// дефолтные параметры калькулятора (как на макете)
function recvDefaultCalc() {
  return { cost_price: 0, transport_cost: 0, fixed_cost_pct: 10, variable_cost_pct: 5, doctor_pct: 5, seller_pct: 5, profit_pct: 30 };
}

// продажная цена за пару (та же формула, что и на бэкенде)
function recvSalePrice(it) {
  const cost = Number(it.cost_price) || 0;
  const transport = Number(it.transport_cost) || 0;
  const base = cost + transport;
  const add = (p) => base * ((Number(p) || 0) / 100);
  return Math.round((base + add(it.fixed_cost_pct) + add(it.variable_cost_pct) + add(it.doctor_pct) + add(it.seller_pct) + add(it.profit_pct)) * 100) / 100;
}

// v1.2.30 — эффективная продажная цена: ручная (override) имеет приоритет над калькулятором
function recvEffPrice(it) {
  const ov = it && it.sale_price_override;
  if (ov != null && ov !== '' && Number(ov) > 0) return Math.round(Number(ov) * 100) / 100;
  return recvSalePrice(it);
}

// цена товара из базы отличается от текущей эффективной? (для флага «цена изменена»)
function recvPriceChanged(it) {
  if (!it || it.base_price == null || it.base_price === '') return false;
  return Math.round(recvEffPrice(it) * 100) / 100 !== Math.round(Number(it.base_price) * 100) / 100;
}

function recvItemQty(it) {
  let n = 0; const s = it.sizes || {};
  for (const k of Object.keys(s)) n += Math.max(0, Math.round(Number(s[k]) || 0));
  return n;
}
function recvItemCost(it) { return Math.round((Number(it.cost_price) || 0) * recvItemQty(it) * 100) / 100; }

function recvTotals() {
  let positions = 0, qty = 0, cost = 0;
  for (const it of recv.items) { const q = recvItemQty(it); if (q > 0 || (it.sizeGrid || []).length === 0) positions++; qty += q; cost += recvItemCost(it); }
  return { positions: recv.items.length, qty, cost: Math.round(cost * 100) / 100 };
}

// ── сохранение/восстановление черновика в localStorage ──
function recvPersist() {
  try {
    localStorage.setItem(RECV_LS_KEY, JSON.stringify({
      docId: recv.docId, supplierId: recv.supplierId, warehouseId: recv.warehouseId,
      docNumber: recv.docNumber, docDate: recv.docDate, items: recv.items,
    }));
  } catch (_) {}
}
function recvRestore() {
  try {
    const raw = localStorage.getItem(RECV_LS_KEY);
    if (!raw) return;
    const d = JSON.parse(raw);
    recv.docId = d.docId || null;
    recv.supplierId = d.supplierId || '';
    recv.warehouseId = d.warehouseId || '';
    recv.docNumber = d.docNumber || '';
    recv.docDate = d.docDate || recv.docDate;
    recv.items = Array.isArray(d.items) ? d.items : [];
  } catch (_) {}
}

async function renderReceiving(force) {
  const root = $('recvBody');
  if (!root) return;
  if (!recv.loaded || force) {
    root.innerHTML = `<div class="loading">⏳ Загрузка…</div>`;
    try {
      const [sup, wh] = await Promise.all([
        posApi('?action=recv-suppliers', { method: 'GET' }),
        posApi('?action=recv-warehouses', { method: 'GET' }),
      ]);
      recv.suppliers = sup.suppliers || [];
      recv.warehouses = wh.warehouses || [];
      recv.loaded = true;
      recvRestore();
      // дефолты
      if (!recv.warehouseId && recv.warehouses[0]) recv.warehouseId = recv.warehouses[0].id;
      if (!recv.supplierId && recv.suppliers[0]) recv.supplierId = recv.suppliers[0].id;
    } catch (e) {
      root.innerHTML = errBar('Не удалось загрузить справочники: ' + (e.message || e));
      return;
    }
  }
  recvPaint();
}

// ── Обёртка с под-вкладками ──
function recvPaint() {
  const root = $('recvBody');
  if (!root) return;
  const tab = recv.tab || 'new';
  const tabBtn = (id, label) => `<button class="recv-tab ${tab === id ? 'active' : ''}" data-rtab="${id}">${label}</button>`;
  root.innerHTML = `
    <div class="recv-tabs">
      ${tabBtn('new', '📝 Новый документ')}
      ${tabBtn('docs', '📄 Документы поступления')}
      ${tabBtn('suppliers', '🏢 Поставщики')}
    </div>
    <div id="recvTabBody"></div>
  `;
  root.querySelectorAll('.recv-tab').forEach(b => {
    b.onclick = () => { recv.tab = b.getAttribute('data-rtab'); recvPaint(); };
  });
  if (tab === 'docs') return recvPaintDocs();
  if (tab === 'suppliers') return recvPaintSuppliers();
  recvPaintNew();
}

// ── Вкладка «Новый документ» (бывший recvPaint) ──
function recvPaintNew() {
  const root = $('recvTabBody');
  if (!root) return;
  const t = recvTotals();
  const isPosted = recv.status === 'posted';
  const docNoTxt = recv.docNumber ? ` <span class="recv-docno">№ ${esc(recv.docNumber)}</span>` : '';
  const badge = isPosted
    ? `<span class="recv-badge recv-badge-ok">Проведён</span>`
    : `<span class="recv-badge">Черновик</span>`;
  const title = isPosted ? 'Редактирование документа' : 'Поступление товара';
  // Кнопки: для проведённого документа — сохранить изменения (без пересоздания ШК) + новый документ
  const actions = isPosted
    ? `<button class="btn btn-ghost" id="recvNewDoc">+ Новый документ</button>
       <button class="btn btn-outline" id="recvPrintLabelsTop">🖨 Напечатать ценники</button>
       <button class="btn btn-primary" id="recvPost">Сохранить изменения</button>`
    : `<button class="btn btn-ghost" id="recvCancel">Отменить</button>
       <button class="btn btn-outline" id="recvSaveDraft">Сохранить черновик</button>
       <button class="btn btn-primary" id="recvPost">Провести поступление</button>`;

  root.innerHTML = `
    ${isPosted ? `<div class="recv-note-bar">Документ уже проведён. Штрихкоды не будут созданы повторно. Изменённые цены обновятся в РМК и на кассе.</div>` : ''}
    <div class="recv-head">
      <div class="recv-title">${title} ${badge}${docNoTxt}</div>
      <div class="recv-head-actions">
        ${actions}
      </div>
    </div>

    <!-- Шапка документа -->
    <div class="recv-form-card">
      <div class="recv-form-grid">
        <label class="recv-field">
          <span class="recv-lbl">Поставщик <b class="req">*</b></span>
          <div class="recv-inline">
            <select class="finput" id="recvSupplier">
              ${recv.suppliers.map(s => `<option value="${s.id}" ${s.id === recv.supplierId ? 'selected' : ''}>${esc(s.name)}</option>`).join('')}
            </select>
            <button class="recv-plus" id="recvAddSupplier" title="Создать поставщика">+</button>
          </div>
        </label>
        <label class="recv-field">
          <span class="recv-lbl">Склад <b class="req">*</b></span>
          <select class="finput" id="recvWarehouse">
            ${recv.warehouses.map(w => `<option value="${w.id}" ${w.id === recv.warehouseId ? 'selected' : ''}>${esc(w.name)}</option>`).join('')}
          </select>
        </label>
        <label class="recv-field">
          <span class="recv-lbl">Номер документа</span>
          <input class="finput" id="recvDocNum" value="${esc(recv.docNumber)}" placeholder="ПТ-000124">
        </label>
        <label class="recv-field">
          <span class="recv-lbl">Дата поступления <b class="req">*</b></span>
          <input class="finput" id="recvDocDate" type="date" value="${esc(recv.docDate)}">
        </label>
      </div>
    </div>

    <!-- Тело: позиции + калькулятор -->
    <div class="recv-body-grid">
      <div class="recv-items-col">
        <div class="recv-items-card">
          <div class="recv-sec-title">Товары в документе</div>
          <div class="recv-search-row">
            <div class="recv-search-wrap">
              <input class="finput" id="recvSearch" placeholder="🔍 Поиск товара по названию или артикулу" autocomplete="off">
              <div class="recv-search-drop" id="recvSearchDrop" style="display:none"></div>
            </div>
            <button class="btn btn-outline" id="recvCreateNom">+ Создать номенклатуру</button>
          </div>
          <div id="recvItemsList">${recvItemsHTML()}</div>
          <button class="recv-add-btn" id="recvAddRow">+ Добавить товар</button>
        </div>

        <!-- Итоги -->
        <div class="recv-totals">
          <div class="recv-tot-card"><div class="recv-tot-lbl">Всего позиций</div><div class="recv-tot-val" id="recvTotPos">${fmtInt(t.positions)}</div></div>
          <div class="recv-tot-card"><div class="recv-tot-lbl">Общее количество</div><div class="recv-tot-val" id="recvTotQty">${fmtInt(t.qty)} пар</div></div>
          <div class="recv-tot-card"><div class="recv-tot-lbl">Общая себестоимость</div><div class="recv-tot-val" id="recvTotCost">${fmtNum(t.cost)} ${CUR}</div></div>
        </div>
      </div>

      <!-- Калькулятор цены -->
      <div class="recv-calc-col" id="recvCalcCol">${recvCalcHTML()}</div>
    </div>
  `;

  recvBindHead();
  recvBindSearch();
  recvBindItems();
  recvBindCalc();
}

// ── Позиции документа ──
function recvItemsHTML() {
  if (!recv.items.length) return `<div class="recv-empty">Пока нет позиций. Найдите товар выше или нажмите «Добавить товар».</div>`;
  return `<div class="recv-items-table">
    <div class="recv-it-head">
      <div>Номенклатура</div><div>Размеры и количество</div><div>Себестоимость</div><div class="c">Действия</div>
    </div>
    ${recv.items.map(recvRowHTML).join('')}
  </div>`;
}

function recvRowHTML(it) {
  const grid = it.sizeGrid || [];
  const sizesHTML = grid.length
    ? `<div class="recv-sizes">${grid.map(sz => `
        <div class="recv-size-cell">
          <div class="recv-size-lbl">${esc(sz)}</div>
          <input class="recv-size-inp" data-uid="${it.uid}" data-size="${esc(sz)}" type="number" min="0" inputmode="numeric"
                 value="${it.sizes && it.sizes[sz] ? esc(String(it.sizes[sz])) : ''}" placeholder="–">
        </div>`).join('')}</div>`
    : `<div class="recv-nosize"><label class="recv-lbl">Количество (шт.)</label>
        <input class="recv-size-inp recv-qty-solo" data-uid="${it.uid}" data-size="_" type="number" min="0" inputmode="numeric"
               value="${it.sizes && it.sizes['_'] ? esc(String(it.sizes['_'])) : ''}" placeholder="0"></div>`;
  const active = it.uid === recv.activeCalcUid ? 'recv-row-active' : '';
  return `
    <div class="recv-row ${active}" data-uid="${it.uid}">
      <div class="recv-nom">
        <div class="recv-nom-ph">📦</div>
        <div><div class="recv-nom-name">${esc(it.product_name)}</div>${it.sku ? `<div class="recv-nom-sku">Артикул: ${esc(it.sku)}</div>` : ''}</div>
      </div>
      <div>${sizesHTML}</div>
      <div class="recv-cost">
        <div class="recv-cost-lbl">за пару (${CUR})</div>
        <input class="recv-cost-inp" data-uid="${it.uid}" type="number" min="0" value="${esc(String(it.cost_price || ''))}" placeholder="0">
        <div class="recv-cost-total">Итого: <b>${fmtNum(recvItemCost(it))} ${CUR}</b></div>
      </div>
      <div class="c recv-actions">
        <button class="recv-icon-btn recv-calc-open" data-uid="${it.uid}" title="Калькулятор цены">🧮</button>
        <button class="recv-icon-btn recv-del" data-uid="${it.uid}" title="Удалить">🗑</button>
      </div>
    </div>`;
}

// ── Калькулятор цены (правая колонка) ──
function recvActiveItem() { return recv.items.find(x => x.uid === recv.activeCalcUid) || null; }

function recvCalcHTML() {
  const it = recvActiveItem();
  if (!it) return `<div class="recv-calc-card recv-calc-empty">
      <div class="recv-sec-title">Калькулятор цены</div>
      <div class="recv-empty">Выберите позицию (кнопка 🧮), чтобы рассчитать продажную цену.</div>
    </div>`;
  const sale = recvSalePrice(it);
  const eff = recvEffPrice(it);
  const hasBase = it.base_price != null && it.base_price !== '';
  const changed = recvPriceChanged(it);
  const pctRow = (id, label, val) => `
    <label class="recv-field">
      <span class="recv-lbl">${label}</span>
      <div class="recv-inline">
        <input class="finput recv-calc-inp" data-fld="${id}" type="number" min="0" value="${esc(String(val))}">
        <span class="recv-suffix">%</span>
      </div>
    </label>`;
  return `<div class="recv-calc-card">
    <div class="recv-sec-title">Калькулятор цены</div>
    <div class="recv-calc-for">Для: <b>${esc(it.product_name)}</b></div>
    <label class="recv-field">
      <span class="recv-lbl">Себестоимость товара</span>
      <div class="recv-inline"><input class="finput recv-calc-inp" data-fld="cost_price" type="number" min="0" value="${esc(String(it.cost_price || 0))}"><span class="recv-suffix">${CUR}</span></div>
    </label>
    <label class="recv-field">
      <span class="recv-lbl">Стоимость транспортировки</span>
      <div class="recv-inline"><input class="finput recv-calc-inp" data-fld="transport_cost" type="number" min="0" value="${esc(String(it.transport_cost || 0))}"><span class="recv-suffix">${CUR}</span></div>
    </label>
    ${pctRow('fixed_cost_pct', 'Постоянные затраты', it.fixed_cost_pct)}
    ${pctRow('variable_cost_pct', 'Переменные затраты', it.variable_cost_pct)}
    ${pctRow('doctor_pct', 'Процент врачам', it.doctor_pct)}
    ${pctRow('seller_pct', 'Процент продавцам', it.seller_pct)}
    ${pctRow('profit_pct', 'Желаемая чистая прибыль', it.profit_pct)}
    <div class="recv-saleprice">
      <div class="recv-sale-lbl">Продажная цена</div>
      <div class="recv-inline recv-sale-edit">
        <input class="finput recv-sale-inp" id="recvSaleInp" type="number" min="0" step="0.01" value="${esc(String(eff))}">
        <span class="recv-suffix">${CUR}</span>
      </div>
      <div class="recv-sale-calc">Расчёт калькулятора: <b id="recvSaleCalc">${fmtNum(sale)} ${CUR}</b> <button type="button" class="recv-sale-usecalc" id="recvUseCalc">использовать</button></div>
      ${hasBase ? `<div class="recv-sale-base ${changed ? 'recv-sale-changed' : ''}" id="recvSaleBase">${changed ? '⚠ Цена изменена (в базе: ' + fmtNum(it.base_price) + ' ' + CUR + '). При проведении обновится у всех вариантов товара.' : 'Цена из базы: ' + fmtNum(it.base_price) + ' ' + CUR}</div>` : `<div class="recv-sale-sub">за пару · новая цена товара</div>`}
    </div>
    <button class="btn btn-outline recv-apply-all" id="recvApplyAll">Применить ко всем товарам</button>
    <button class="btn btn-primary recv-gen-bc" id="recvGenBarcodes">▐╫ Сгенерировать штрихкоды</button>
    <button class="btn btn-outline recv-print" id="recvPrintLabels">🖨 Распечатать ценники</button>
  </div>`;
}

// ── Привязка обработчиков шапки ──
function recvBindHead() {
  const sup = $('recvSupplier'); if (sup) sup.onchange = () => { recv.supplierId = sup.value; recvPersist(); };
  const wh = $('recvWarehouse'); if (wh) wh.onchange = () => { recv.warehouseId = wh.value; recvPersist(); };
  const dn = $('recvDocNum'); if (dn) dn.oninput = () => { recv.docNumber = dn.value; recvPersist(); };
  const dd = $('recvDocDate'); if (dd) dd.onchange = () => { recv.docDate = dd.value; recvPersist(); };

  const addSup = $('recvAddSupplier'); if (addSup) addSup.onclick = recvCreateSupplier;
  const cancel = $('recvCancel'); if (cancel) cancel.onclick = recvCancelDoc;
  const saveDraft = $('recvSaveDraft'); if (saveDraft) saveDraft.onclick = () => recvSubmit(false);
  const post = $('recvPost'); if (post) post.onclick = () => recvSubmit(true);
  const newDoc = $('recvNewDoc'); if (newDoc) newDoc.onclick = () => { recvResetForm(); recvPaint(); };
  const printTop = $('recvPrintLabelsTop'); if (printTop) printTop.onclick = recvPrintLabels;
  const createNom = $('recvCreateNom'); if (createNom) createNom.onclick = () => alert('Создание номенклатуры — отдельный раздел (в разработке). Пока добавляйте существующие товары через поиск.');
  const addRow = $('recvAddRow'); if (addRow) addRow.onclick = () => { const s = $('recvSearch'); if (s) s.focus(); };
}

// ── Поиск товара с автодополнением ──
let recvSearchTimer = null;
function recvBindSearch() {
  const inp = $('recvSearch'); const drop = $('recvSearchDrop');
  if (!inp || !drop) return;
  inp.oninput = () => {
    const term = inp.value.trim();
    clearTimeout(recvSearchTimer);
    if (term.length < 2) { drop.style.display = 'none'; drop.innerHTML = ''; return; }
    recvSearchTimer = setTimeout(async () => {
      try {
        const d = await posApi('?action=recv-products&q=' + encodeURIComponent(term), { method: 'GET' });
        recv.searchResults = d.products || [];
        if (!recv.searchResults.length) { drop.innerHTML = `<div class="recv-drop-empty">Ничего не найдено</div>`; drop.style.display = 'block'; return; }
        drop.innerHTML = recv.searchResults.map((p, i) => `
          <div class="recv-drop-item" data-idx="${i}">
            <div class="recv-drop-name">${esc(p.name)}</div>
            <div class="recv-drop-meta">${p.sku ? 'Арт: ' + esc(p.sku) + ' · ' : ''}${esc(p.category || '')}${(p.sizeGrid || []).length ? ' · размеры ' + p.sizeGrid[0] + '–' + p.sizeGrid[p.sizeGrid.length - 1] : ' · без размеров'}</div>
          </div>`).join('');
        drop.style.display = 'block';
        drop.querySelectorAll('.recv-drop-item').forEach(el => {
          el.onclick = () => { recvAddProduct(recv.searchResults[Number(el.dataset.idx)]); inp.value = ''; drop.style.display = 'none'; };
        });
      } catch (e) { drop.innerHTML = `<div class="recv-drop-empty">Ошибка: ${esc(e.message || e)}</div>`; drop.style.display = 'block'; }
    }, 250);
  };
  document.addEventListener('click', (e) => { if (drop && !drop.contains(e.target) && e.target !== inp) drop.style.display = 'none'; });
}

function recvAddProduct(p) {
  if (!p) return;
  // не дублируем: если товар уже в документе — просто подсветим
  const exist = recv.items.find(x => x.product_id === p.id);
  if (exist) { recv.activeCalcUid = exist.uid; recvPaint(); return; }
  const it = { uid: recvNewUid(), product_id: p.id, product_name: p.name, sku: p.sku || '', category: p.category || '', sizeGrid: p.sizeGrid || [], sizes: {}, ...recvDefaultCalc() };
  // v1.2.30 — если у товара уже есть цена в базе — подставляем её как редактируемую
  if (p.basePrice != null && Number(p.basePrice) > 0) {
    it.base_price = Math.round(Number(p.basePrice) * 100) / 100;
    it.sale_price_override = it.base_price; // подставлена цена из базы (можно редактировать)
  }
  recv.items.push(it);
  recv.activeCalcUid = it.uid;
  recvPersist();
  recvPaint();
}

// ── Привязка обработчиков позиций (размеры, себестоимость, удаление, открыть калькулятор) ──
function recvBindItems() {
  document.querySelectorAll('.recv-size-inp').forEach(inp => {
    inp.oninput = () => {
      const it = recv.items.find(x => x.uid === inp.dataset.uid); if (!it) return;
      it.sizes = it.sizes || {};
      const v = Math.max(0, Math.round(Number(inp.value) || 0));
      if (v > 0) it.sizes[inp.dataset.size] = v; else delete it.sizes[inp.dataset.size];
      recvPersist();
      recvUpdateTotalsLive(it);
    };
  });
  document.querySelectorAll('.recv-cost-inp').forEach(inp => {
    inp.oninput = () => {
      const it = recv.items.find(x => x.uid === inp.dataset.uid); if (!it) return;
      it.cost_price = Number(inp.value) || 0;
      recvPersist();
      recvUpdateTotalsLive(it);
      // если позиция открыта в калькуляторе — синхронизируем поле себестоимости
      if (it.uid === recv.activeCalcUid) { const cf = document.querySelector('.recv-calc-inp[data-fld="cost_price"]'); if (cf) cf.value = it.cost_price; recvRecalcSale(); }
    };
  });
  document.querySelectorAll('.recv-del').forEach(b => {
    b.onclick = () => {
      recv.items = recv.items.filter(x => x.uid !== b.dataset.uid);
      if (recv.activeCalcUid === b.dataset.uid) recv.activeCalcUid = null;
      recvPersist(); recvPaint();
    };
  });
  document.querySelectorAll('.recv-calc-open').forEach(b => {
    b.onclick = () => { recv.activeCalcUid = b.dataset.uid; recvPaint(); };
  });
}

// живое обновление итогов без полной перерисовки
function recvUpdateTotalsLive(it) {
  const t = recvTotals();
  const p = $('recvTotPos'), q = $('recvTotQty'), c = $('recvTotCost');
  if (p) p.textContent = fmtInt(t.positions);
  if (q) q.textContent = fmtInt(t.qty) + ' пар';
  if (c) c.innerHTML = fmtNum(t.cost) + ' ' + CUR;
  // обновляем «Итого» строки позиции
  const row = document.querySelector(`.recv-row[data-uid="${it.uid}"] .recv-cost-total b`);
  if (row) row.textContent = fmtNum(recvItemCost(it)) + ' ' + CUR;
}

// ── Калькулятор: инпуты и пересчёт ──
function recvBindCalc() {
  document.querySelectorAll('.recv-calc-inp').forEach(inp => {
    inp.oninput = () => {
      const it = recvActiveItem(); if (!it) return;
      it[inp.dataset.fld] = Number(inp.value) || 0;
      // если меняли себестоимость — синхронизируем в строке позиции
      if (inp.dataset.fld === 'cost_price') { const ci = document.querySelector(`.recv-cost-inp[data-uid="${it.uid}"]`); if (ci) ci.value = it.cost_price; recvUpdateTotalsLive(it); }
      recvPersist();
      recvRecalcSale();
    };
  });
  const applyAll = $('recvApplyAll'); if (applyAll) applyAll.onclick = recvApplyToAll;
  const genBc = $('recvGenBarcodes'); if (genBc) genBc.onclick = () => recvSubmit(true);
  const printL = $('recvPrintLabels'); if (printL) printL.onclick = recvPrintLabels;

  // v1.2.30 — ручной ввод продажной цены (override)
  const saleInp = $('recvSaleInp');
  if (saleInp) saleInp.oninput = () => {
    const it = recvActiveItem(); if (!it) return;
    const v = saleInp.value;
    if (v === '' || Number(v) <= 0) delete it.sale_price_override;
    else it.sale_price_override = Math.round(Number(v) * 100) / 100;
    recvPersist();
    recvUpdateSaleFlags();
  };
  // кнопка «использовать расчёт калькулятора» — сбрасывает ручную цену
  const useCalc = $('recvUseCalc');
  if (useCalc) useCalc.onclick = () => {
    const it = recvActiveItem(); if (!it) return;
    delete it.sale_price_override;
    recvPersist();
    recvPaint();
  };
}

function recvRecalcSale() {
  const it = recvActiveItem(); if (!it) return;
  // обновляем «Расчёт калькулятора»; если ручной цены нет — синхронизируем поле цены
  const calcVal = recvSalePrice(it);
  const calcEl = $('recvSaleCalc'); if (calcEl) calcEl.innerHTML = fmtNum(calcVal) + ' ' + CUR;
  const hasOverride = it.sale_price_override != null && it.sale_price_override !== '' && Number(it.sale_price_override) > 0;
  if (!hasOverride) { const inp = $('recvSaleInp'); if (inp && document.activeElement !== inp) inp.value = String(calcVal); }
  recvUpdateSaleFlags();
}

// обновить индикатор «цена изменена / из базы» без полного перерисовывания
function recvUpdateSaleFlags() {
  const it = recvActiveItem(); if (!it) return;
  const baseEl = $('recvSaleBase'); if (!baseEl) return;
  const hasBase = it.base_price != null && it.base_price !== '';
  if (!hasBase) return;
  const changed = recvPriceChanged(it);
  baseEl.className = 'recv-sale-base' + (changed ? ' recv-sale-changed' : '');
  baseEl.innerHTML = changed
    ? '⚠ Цена изменена (в базе: ' + fmtNum(it.base_price) + ' ' + CUR + '). При проведении обновится у всех вариантов товара.'
    : 'Цена из базы: ' + fmtNum(it.base_price) + ' ' + CUR;
}

function recvApplyToAll() {
  const src = recvActiveItem(); if (!src) return;
  const keys = ['transport_cost', 'fixed_cost_pct', 'variable_cost_pct', 'doctor_pct', 'seller_pct', 'profit_pct'];
  recv.items.forEach(it => { keys.forEach(k => { it[k] = src[k]; }); });
  recvPersist();
  recvPaint();
  alert('Параметры калькулятора применены ко всем позициям (кроме себестоимости — она у каждого товара своя).');
}

// ── Создать поставщика ──
async function recvCreateSupplier() {
  const name = prompt('Название поставщика:');
  if (!name || !name.trim()) return;
  try {
    const d = await posApi('?action=recv-supplier-create', { method: 'POST', body: JSON.stringify({ name: name.trim() }) });
    recv.suppliers.push(d.supplier);
    recv.suppliers.sort((a, b) => a.name.localeCompare(b.name, 'ru'));
    recv.supplierId = d.supplier.id;
    recvPersist(); recvPaint();
  } catch (e) { alert('Не удалось создать поставщика: ' + (e.message || e)); }
}

// ── Отмена документа ──
function recvCancelDoc() {
  if (!confirm('Очистить текущий документ поступления? Несохранённые данные будут потеряны.')) return;
  recv.docId = null; recv.status = 'draft'; recv.items = []; recv.docNumber = ''; recv.activeCalcUid = null;
  recv.docDate = new Date().toISOString().slice(0, 10);
  try { localStorage.removeItem(RECV_LS_KEY); } catch (_) {}
  recvPaint();
}

// ── Сохранить черновик / Провести ──
async function recvSubmit(isPost) {
  if (isPost) {
    if (!recv.items.length) { alert('Добавьте хотя бы одну позицию.'); return; }
    const anyQty = recv.items.some(it => recvItemQty(it) > 0);
    if (!anyQty) { alert('Укажите количество хотя бы у одной позиции.'); return; }
    if (!recv.supplierId) { alert('Выберите поставщика.'); return; }
    if (!recv.warehouseId) { alert('Выберите склад.'); return; }
    // Перепроведение уже проведённого документа: ШК НЕ пересоздаются, обновляются только цены
    if (recv.docId && recv.status === 'posted') {
      if (!confirm('Сохранить изменения документа?\n\nНовые штрихкоды НЕ будут созданы (защита от дублей). Если вы изменили цены — они обновятся в РМК и на кассе.')) return;
    } else {
      if (!confirm('Провести поступление? Будут созданы экземпляры товара со штрихкодами и обновлён остаток.')) return;
    }
  }
  const supName = (recv.suppliers.find(s => s.id === recv.supplierId) || {}).name || null;
  const whName = (recv.warehouses.find(w => w.id === recv.warehouseId) || {}).name || null;
  const payload = {
    docId: recv.docId, docNumber: recv.docNumber || null, docDate: recv.docDate,
    supplierId: recv.supplierId || null, supplierName: supName,
    warehouseId: recv.warehouseId || null, warehouseName: whName,
    items: recv.items.map(it => ({
      product_id: it.product_id, product_name: it.product_name, sku: it.sku,
      sizes: it.sizeGrid && it.sizeGrid.length ? it.sizes : {}, // товары без сетки — количество в поле '_' пойдёт как есть? нет: для без-сетки используем sizes['_']
      cost_price: it.cost_price, transport_cost: it.transport_cost,
      fixed_cost_pct: it.fixed_cost_pct, variable_cost_pct: it.variable_cost_pct,
      doctor_pct: it.doctor_pct, seller_pct: it.seller_pct, profit_pct: it.profit_pct,
      // v1.2.30 — ручная цена (если задана) + базовая цена (для каскада)
      sale_price_override: (it.sale_price_override != null && it.sale_price_override !== '') ? it.sale_price_override : null,
      base_price: (it.base_price != null && it.base_price !== '') ? it.base_price : null,
    })),
  };
  // товары без размерной сетки: переносим количество '_' в sizes как ключ 'без размера'
  payload.items.forEach((pi, idx) => {
    const it = recv.items[idx];
    if (!(it.sizeGrid && it.sizeGrid.length) && it.sizes && it.sizes['_']) pi.sizes = { 'без размера': it.sizes['_'] };
  });

  const action = isPost ? 'recv-post' : 'recv-save-draft';
  try {
    const btn = isPost ? $('recvPost') : $('recvSaveDraft');
    if (btn) { btn.disabled = true; btn.textContent = isPost ? 'Проведение…' : 'Сохранение…'; }
    const d = await posApi('?action=' + action, { method: 'POST', body: JSON.stringify(payload) });
    recv.docId = d.doc.id;
    if (isPost) {
      const docNo = (d.doc && d.doc.doc_number) || recv.docNumber || '';
      const bcs = d.barcodes || [];
      recv.docsList = null; // сброс кэша списка
      if (d.reposted) {
        // Перепроведение: штрихкоды сохранены, цены обновлены каскадом
        const casc = d.cascadeVariants || 0;
        alert(`Документ${docNo ? ' № ' + docNo : ''} обновлён.\nОбновлено цен вариантов: ${d.updatedVariants || 0}.${casc ? '\nКаскад цены (все варианты товара): ' + casc : ''} (отразятся в РМК/кассе). Новые штрихкоды не создавались.`);
        recv.lastBarcodes = bcs;
        recvResetForm();
        recv.tab = 'docs';
        recvPaint();
      } else {
        const created = d.createdUnits || 0;
        const casc = d.cascadeVariants || 0;
        // Предлагаем печать ценников СРАЗУ (до очистки экрана)
        const msg = `Поступление проведено${docNo ? ' № ' + docNo : ''}.\nСоздано экземпляров: ${created}.${casc ? '\nКаскад цены (все варианты товара): ' + casc : ''}\n\nНапечатать ценники сейчас?`;
        const wantPrint = bcs.length && confirm(msg);
        if (wantPrint) {
          recv.lastBarcodes = bcs;
          try { await recvPrintLabels(); } catch (_) {}
        } else if (!bcs.length) {
          alert(`Поступление проведено${docNo ? ' № ' + docNo : ''}.`);
        }
        // ОЧИСТКА ЭКРАНА — документ ушёл в «Документы поступления»
        recvResetForm();
        recvPaint();
      }
    } else {
      recvPersist();
      alert('Черновик сохранён.');
      recvPaint();
    }
  } catch (e) {
    alert('Не удалось ' + (isPost ? 'провести' : 'сохранить') + ': ' + (e.message || e));
    recvPaint();
  }
}

// Сброс формы нового документа (без подтверждения) — после проведения/нового документа
function recvResetForm() {
  recv.docId = null; recv.status = 'draft'; recv.items = []; recv.docNumber = '';
  recv.activeCalcUid = null; recv.lastBarcodes = []; recv.docMode = 'new';
  recv.docDate = new Date().toISOString().slice(0, 10);
  if (recv.warehouses && recv.warehouses[0]) recv.warehouseId = recv.warehouses[0].id;
  if (recv.suppliers && recv.suppliers[0]) recv.supplierId = recv.suppliers[0].id;
  try { localStorage.removeItem(RECV_LS_KEY); } catch (_) {}
}

// ══════════════════════════════════════════════════════
//  ВКЛАДКА «ДОКУМЕНТЫ ПОСТУПЛЕНИЯ»
// ══════════════════════════════════════════════════════
async function recvPaintDocs() {
  const root = $('recvTabBody');
  if (!root) return;
  root.innerHTML = `<div class="loading">⏳ Загрузка документов…</div>`;
  if (!recv.docsList) {
    try {
      const d = await posApi('?action=recv-docs', { method: 'GET' });
      recv.docsList = d.docs || [];
    } catch (e) { root.innerHTML = errBar('Не удалось загрузить документы: ' + (e.message || e)); return; }
  }
  const docs = recv.docsList || [];
  const rows = docs.map(dc => {
    const st = dc.status === 'posted'
      ? `<span class="recv-badge recv-badge-ok">Проведён</span>`
      : (dc.status === 'cancelled' ? `<span class="recv-badge recv-badge-off">Отменён</span>` : `<span class="recv-badge">Черновик</span>`);
    return `<tr data-docid="${dc.id}">
      <td class="recv-dl-num">${esc(dc.doc_number || '—')}</td>
      <td>${esc((dc.doc_date || '').slice(0, 10))}</td>
      <td>${esc(dc.supplier_name || '—')}</td>
      <td>${esc(dc.warehouse_name || '—')}</td>
      <td class="c">${fmtInt(dc.positions_count || 0)}</td>
      <td class="c">${fmtInt(dc.total_qty || 0)}</td>
      <td class="r">${fmtNum(dc.total_cost || 0)} ${CUR}</td>
      <td class="c">${st}</td>
      <td class="c"><button class="btn btn-outline btn-sm recv-doc-open" data-docid="${dc.id}">Открыть</button></td>
    </tr>`;
  }).join('');
  root.innerHTML = `
    <div class="recv-head">
      <div class="recv-title">Документы поступления</div>
      <div class="recv-head-actions">
        <button class="btn btn-ghost" id="recvDocsRefresh">↻ Обновить</button>
        <button class="btn btn-primary" id="recvDocsNew">+ Новый документ</button>
      </div>
    </div>
    ${docs.length ? `<div class="recv-docs-tablewrap"><table class="recv-docs-table">
      <thead><tr>
        <th>№ документа</th><th>Дата</th><th>Поставщик</th><th>Склад</th>
        <th class="c">Позиций</th><th class="c">Кол-во</th><th class="r">Себестоимость</th><th class="c">Статус</th><th class="c"></th>
      </tr></thead>
      <tbody>${rows}</tbody>
    </table></div>` : `<div class="recv-empty">Пока нет документов поступления. Создайте новый во вкладке «Новый документ».</div>`}
  `;
  const rf = $('recvDocsRefresh'); if (rf) rf.onclick = () => { recv.docsList = null; recvPaintDocs(); };
  const nw = $('recvDocsNew'); if (nw) nw.onclick = () => { recvResetForm(); recv.tab = 'new'; recvPaint(); };
  root.querySelectorAll('.recv-doc-open').forEach(b => {
    b.onclick = () => recvOpenDoc(b.getAttribute('data-docid'));
  });
}

// Открыть существующий документ для просмотра/редактирования
async function recvOpenDoc(id) {
  if (!id) return;
  try {
    const d = await posApi('?action=recv-doc&id=' + encodeURIComponent(id), { method: 'GET' });
    if (!d.doc) { alert('Документ не найден.'); return; }
    const doc = d.doc;
    recv.docId = doc.id;
    recv.status = doc.status || 'draft';
    recv.docNumber = doc.doc_number || '';
    recv.docDate = (doc.doc_date || '').slice(0, 10) || recv.docDate;
    recv.supplierId = doc.supplier_id || '';
    recv.warehouseId = doc.warehouse_id || '';
    recv.docMode = 'view';
    recv.lastBarcodes = [];
    recv.activeCalcUid = null;
    // восстанавливаем позиции из receiving_items
    recv.items = (d.items || []).map(it => {
      const sizesRaw = (it.sizes && typeof it.sizes === 'object') ? it.sizes : {};
      // определяем сетку: если единственный ключ «без размера» — товар без сетки
      const keys = Object.keys(sizesRaw);
      const noGrid = keys.length === 1 && keys[0] === 'без размера';
      let sizes = sizesRaw, sizeGrid = keys.filter(k => k !== 'без размера');
      if (noGrid) { sizes = { '_': sizesRaw['без размера'] }; sizeGrid = []; }
      return {
        uid: recvNewUid(), product_id: it.product_id, product_name: it.product_name || '',
        sku: it.sku || '', category: '', sizeGrid, sizes,
        cost_price: Number(it.cost_price) || 0, transport_cost: Number(it.transport_cost) || 0,
        fixed_cost_pct: Number(it.fixed_cost_pct) || 0, variable_cost_pct: Number(it.variable_cost_pct) || 0,
        doctor_pct: Number(it.doctor_pct) || 0, seller_pct: Number(it.seller_pct) || 0,
        profit_pct: Number(it.profit_pct) || 0,
      };
    });
    recv.tab = 'new';
    recvPaint();
  } catch (e) { alert('Не удалось открыть документ: ' + (e.message || e)); }
}

// ══════════════════════════════════════════════════════
//  ВКЛАДКА «ПОСТАВЩИКИ»
// ══════════════════════════════════════════════════════
async function recvPaintSuppliers() {
  const root = $('recvTabBody');
  if (!root) return;
  root.innerHTML = `<div class="loading">⏳ Загрузка поставщиков…</div>`;
  if (!recv.suppliersAll) {
    try {
      const d = await posApi('?action=recv-suppliers&all=1', { method: 'GET' });
      recv.suppliersAll = d.suppliers || [];
    } catch (e) { root.innerHTML = errBar('Не удалось загрузить поставщиков: ' + (e.message || e)); return; }
  }
  const sups = recv.suppliersAll || [];
  const rows = sups.map(s => `<tr data-supid="${s.id}">
    <td>${esc(s.name)}</td>
    <td>${esc(s.note || '—')}</td>
    <td>${esc(s.phone || '—')}</td>
    <td class="c">${s.is_active ? '<span class="recv-badge recv-badge-ok">Активен</span>' : '<span class="recv-badge recv-badge-off">Скрыт</span>'}</td>
    <td class="c">
      <button class="btn btn-outline btn-sm recv-sup-edit" data-supid="${s.id}">Изменить</button>
      <button class="btn btn-ghost btn-sm recv-sup-toggle" data-supid="${s.id}">${s.is_active ? 'Скрыть' : 'Активировать'}</button>
    </td>
  </tr>`).join('');
  root.innerHTML = `
    <div class="recv-head">
      <div class="recv-title">Поставщики <span class="recv-badge">${sups.length}</span></div>
      <div class="recv-head-actions">
        <button class="btn btn-outline" id="recvSupImport">⬇ Импорт из 1С</button>
        <button class="btn btn-primary" id="recvSupAdd">+ Добавить</button>
      </div>
    </div>
    ${sups.length ? `<div class="recv-docs-tablewrap"><table class="recv-docs-table">
      <thead><tr><th>Название</th><th>Примечание</th><th>Телефон</th><th class="c">Статус</th><th class="c">Действия</th></tr></thead>
      <tbody>${rows}</tbody>
    </table></div>` : `<div class="recv-empty">Нет поставщиков. Нажмите «Импорт из 1С», чтобы подтянуть список.</div>`}
  `;
  const imp = $('recvSupImport'); if (imp) imp.onclick = recvImportSuppliers;
  const add = $('recvSupAdd'); if (add) add.onclick = () => recvSupplierDialog(null);
  root.querySelectorAll('.recv-sup-edit').forEach(b => {
    b.onclick = () => recvSupplierDialog(sups.find(x => x.id === b.getAttribute('data-supid')));
  });
  root.querySelectorAll('.recv-sup-toggle').forEach(b => {
    b.onclick = async () => {
      const s = sups.find(x => x.id === b.getAttribute('data-supid'));
      if (!s) return;
      try {
        await posApi('?action=recv-supplier-update', { method: 'POST', body: JSON.stringify({ id: s.id, is_active: !s.is_active }) });
        recv.suppliersAll = null; recv.loaded = false; recvPaintSuppliers();
      } catch (e) { alert('Ошибка: ' + (e.message || e)); }
    };
  });
}

// Импорт поставщиков из 1С
async function recvImportSuppliers() {
  if (!confirm('Импортировать поставщиков из 1С? Уже существующие не дублируются.')) return;
  try {
    const d = await posApi('?action=recv-suppliers-import', { method: 'POST', body: JSON.stringify({}) });
    alert(`Импорт из 1С завершён.\nДобавлено: ${d.inserted}. Пропущено (уже есть): ${d.skipped}. Всего в 1С: ${d.total1c}.`);
    recv.suppliersAll = null; recv.loaded = false; recvPaintSuppliers();
  } catch (e) { alert('Не удалось импортировать: ' + (e.message || e)); }
}

// Диалог добавления/редактирования поставщика (простой через prompt)
async function recvSupplierDialog(sup) {
  const isEdit = !!sup;
  const name = prompt(isEdit ? 'Название поставщика:' : 'Название нового поставщика:', isEdit ? (sup.name || '') : '');
  if (name === null) return;
  if (!name.trim()) { alert('Название обязательно.'); return; }
  const phone = prompt('Телефон (можно пусто):', isEdit ? (sup.phone || '') : '');
  if (phone === null) return;
  const note = prompt('Примечание (можно пусто):', isEdit ? (sup.note || '') : '');
  if (note === null) return;
  try {
    if (isEdit) {
      await posApi('?action=recv-supplier-update', { method: 'POST', body: JSON.stringify({ id: sup.id, name: name.trim(), phone, note }) });
    } else {
      await posApi('?action=recv-supplier-create', { method: 'POST', body: JSON.stringify({ name: name.trim(), phone, note }) });
    }
    recv.suppliersAll = null; recv.loaded = false; recvPaintSuppliers();
  } catch (e) { alert('Ошибка: ' + (e.message || e)); }
}

// ── Печать ценников (сгенерированные ШК) ──
// Цена для этикетки: округление до десятых, без хвостового нуля (387,50→387,5; 300→300; 294,50→294,5)
function recvFmtPrice(n) {
  const v = Math.round((Number(n) || 0) * 10) / 10;
  return v.toLocaleString('ru-RU', { minimumFractionDigits: 0, maximumFractionDigits: 1 });
}

// SVG-иконка стопы (белая на чёрном квадрате) — как на макете
function recvFootSVG() {
  return `<svg viewBox="0 0 100 130" xmlns="http://www.w3.org/2000/svg"><g fill="#fff">`
    + `<path d="M30 62 C22 62 16 72 16 88 C16 104 26 116 40 116 C54 116 62 106 62 92 C62 78 54 62 42 62 Z"/>`
    + `<ellipse cx="72" cy="52" rx="11" ry="14"/>`
    + `<ellipse cx="60" cy="34" rx="8.5" ry="11"/>`
    + `<ellipse cx="46" cy="24" rx="7.5" ry="9.5"/>`
    + `<ellipse cx="33" cy="22" rx="6.5" ry="8"/>`
    + `<ellipse cx="22" cy="28" rx="5.5" ry="7"/>`
    + `</g></svg>`;
}

// Печать этикеток 58×40мм с настоящим EAN-13 (JsBarcode)
// items: [{barcode, size, productName, salePrice}]  — по одной этикетке на экземпляр
function recvBuildLabelsHTML(items) {
  const cards = items.map((b, i) => `
    <div class="lbl">
      <div class="lbl-name">${esc(String(b.productName || ''))}</div>
      <div class="lbl-hr"></div>
      <div class="lbl-mid">
        <div class="lbl-col">
          <div class="lbl-tag">РАЗМЕР</div>
          <div class="lbl-size">${esc(String(b.size || ''))}</div>
        </div>
        <div class="lbl-vsep"></div>
        <div class="lbl-col">
          <div class="lbl-tag">ЦЕНА</div>
          <div class="lbl-price"><span class="lbl-price-num">${recvFmtPrice(b.salePrice)}</span> <span class="lbl-cur">TJS</span></div>
        </div>
      </div>
      <div class="lbl-bc"><svg class="bc" data-code="${esc(String(b.barcode || ''))}" id="bc${i}"></svg></div>
    </div>`).join('');

  return `<!doctype html><html lang="ru"><head><meta charset="utf-8"><title>Ценники</title>
    <script src="https://cdn.jsdelivr.net/npm/jsbarcode@3.11.6/dist/JsBarcode.all.min.js"><\/script>
    <style>
      @page{size:58mm 40mm;margin:0}
      *{box-sizing:border-box;margin:0;padding:0;-webkit-print-color-adjust:exact;print-color-adjust:exact}
      html,body{width:58mm;background:#fff}
      body{font-family:Arial,'Helvetica Neue',sans-serif}
      @media screen{body{background:#e9edef;padding:6mm}}
      /* Каждая этикетка = отдельная страница 58×40мм. Grid с фиксированными строками — блоки не наложатся. */
      .lbl{width:58mm;height:40mm;background:#fff;padding:2mm 2.5mm;
           display:grid;grid-template-rows:8mm 0.5mm 11mm 1fr;row-gap:0.8mm;
           overflow:hidden;page-break-after:always;break-after:page;
           page-break-inside:avoid;break-inside:avoid}
      .lbl:last-child{page-break-after:auto;break-after:auto}
      @media screen{.lbl{margin-bottom:6mm;box-shadow:0 1px 5px rgba(0,0,0,.15)}}
      /* Название — до 2 строк, обрезка по высоте ячейки. Шрифт авто-подгоняется в fitLabels(). */
      .lbl-name{font-size:3.1mm;font-weight:800;line-height:1.05;color:#000;text-transform:uppercase;
                height:8mm;overflow:hidden;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical}
      .lbl-hr{background:#000;width:100%;height:0.4mm}
      /* Размер и цена — две равные колонки с разделителем; крупный отступ между ними */
      .lbl-mid{display:grid;grid-template-columns:1fr 0.4mm 1.15fr;align-items:center;column-gap:3mm;overflow:hidden}
      .lbl-col{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:1mm;overflow:hidden;min-width:0;width:100%}
      .lbl-vsep{width:0.4mm;height:8mm;background:#000;align-self:center}
      .lbl-tag{font-size:2mm;font-weight:800;letter-spacing:0.2mm;color:#fff;background:#000;
               border-radius:0.8mm;padding:0.4mm 2mm;text-transform:uppercase;white-space:nowrap}
      /* Размер — не переносится, шрифт авто-подгоняется в fitLabels() под ширину колонки. */
      .lbl-size{font-size:6mm;font-weight:900;color:#000;line-height:1;white-space:nowrap;max-width:100%}
      .lbl-price{color:#000;line-height:1;white-space:nowrap}
      .lbl-price-num{font-size:5mm;font-weight:900}
      .lbl-cur{font-size:2.4mm;font-weight:800;margin-left:0.3mm}
      /* Штрихкод — своя ячейка, строго вписан по высоте */
      .lbl-bc{width:100%;height:100%;min-height:0;display:flex;align-items:center;justify-content:center;overflow:hidden}
      .lbl-bc svg{max-width:100%;max-height:100%;display:block}
    </style></head><body>
    ${cards}
    <script>
      // Авто-подгонка шрифта: длинные названия и длинные размеры («стандарт») уменьшаются, пока не влезут.
      function fitOne(el, opts){
        if(!el) return;
        var min=opts.min, cur=opts.max, byW=opts.byWidth, byH=opts.byHeight;
        // Для замера высоты снимаем line-clamp и фиксированную высоту, иначе scrollHeight = обрезанной.
        var clampProp=null, hProp=null;
        if(byH){ clampProp=el.style.webkitLineClamp; hProp=el.style.height;
                 el.style.webkitLineClamp='unset'; el.style.display='block'; el.style.height='auto'; }
        el.style.fontSize=cur+'mm';
        // Максимум высоты: 8мм ячейки названия (в px через временный замер).
        var probe=document.createElement('div'); probe.style.height='8mm'; probe.style.position='absolute'; probe.style.visibility='hidden';
        document.body.appendChild(probe); var maxH=probe.clientHeight; document.body.removeChild(probe);
        var guard=0;
        while(guard++<60){
          var okW = byW ? (el.scrollWidth <= el.clientWidth+1) : true;
          var okH = byH ? (el.scrollHeight <= maxH+1) : true;
          if(okW && okH) break;
          cur -= 0.15;
          if(cur < min){ cur=min; el.style.fontSize=cur+'mm'; break; }
          el.style.fontSize=cur+'mm';
        }
        // Возвращаем clamp и высоту — на случай если на min всё равно не влезло (обрежет «…»).
        if(byH){ el.style.display='-webkit-box'; el.style.webkitLineClamp = clampProp || '2'; el.style.height = hProp || '8mm'; }
      }
      function fitLabels(){
        document.querySelectorAll('.lbl').forEach(function(lbl){
          // Размер — в одну строку по ширине колонки (6мм → до 2.6мм)
          fitOne(lbl.querySelector('.lbl-size'), {max:6, min:2.6, byWidth:true, byHeight:false});
          // Название — до 2 строк по высоте ячейки (3.1мм → до 2.2мм)
          fitOne(lbl.querySelector('.lbl-name'), {max:3.1, min:2.2, byWidth:false, byHeight:true});
        });
      }
      function draw(){
        if(!window.JsBarcode){setTimeout(draw,120);return;}
        document.querySelectorAll('svg.bc').forEach(function(el){
          var code=el.getAttribute('data-code')||'';
          try{
            if(/^[0-9]{13}$/.test(code)){
              JsBarcode(el,code,{format:'EAN13',width:1.6,height:34,fontSize:11,margin:0,textMargin:1,displayValue:true});
            }else{
              JsBarcode(el,code,{format:'CODE128',width:1.3,height:34,fontSize:11,margin:0,displayValue:true});
            }
          }catch(e){
            JsBarcode(el,code,{format:'CODE128',width:1.3,height:34,fontSize:11,margin:0,displayValue:true});
          }
        });
        fitLabels();
        setTimeout(function(){fitLabels();window.focus();window.print();},400);
      }
      window.onload=draw;
    <\/script></body></html>`;
}

async function recvPrintLabels() {
  let bc = recv.lastBarcodes || [];
  // если штрихкодов нет в памяти, но документ проведён — подтянем из БД (перепечать)
  if (!bc.length && recv.docId) {
    try {
      const d = await posApi('?action=recv-doc-barcodes&id=' + encodeURIComponent(recv.docId), { method: 'GET' });
      bc = d.barcodes || [];
      recv.lastBarcodes = bc;
    } catch (e) { alert('Не удалось загрузить штрихкоды документа: ' + (e.message || e)); return; }
  }
  if (!bc.length) { alert('Сначала проведите поступление — тогда появятся штрихкоды для печати.'); return; }
  const html = recvBuildLabelsHTML(bc);
  // открываем в новом окне (надёжнее для загрузки JsBarcode и диалога печати)
  const w = window.open('', '_blank');
  if (w) { w.document.open(); w.document.write(html); w.document.close(); }
  else {
    // fallback — во встроенный iframe
    const frame = $('recvPrintFrame');
    if (frame) { const doc = frame.contentWindow.document; doc.open(); doc.write(html); doc.close(); }
    else alert('Разрешите всплывающие окна для печати этикеток.');
  }
}


